(window.GIM_TS=window.GIM_TS||{})["Shabbat.11"]={"from":264,"a":[["\u0003חספניתא\u0004 \u0005[פצעים].\u0006 ואם לא עשה כן ונעשו בגופו פצעים \u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]\u0006 — \u0003לימשי טובא במיא דסילקא\u0004 \u0005[שירחץ הרבה במי תרדים].\u0006","שנינו במשנה שאם \u0003לא שחק\u0004 את הכמון \u0003מערב שבת\u0004 שוחקו בשינוי בשבת. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003דברים שאין עושין למילה בשבת\u0004 — \u0003עושין לה ביום טוב.\u0004 וכגון: \u0003שוחקין לה\u0004 (לצורכה) \u0003כמון, וטורפין\u0004 (מערבים) \u0003לה יין ושמן.\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אביי לרב יוסף: מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003כמון\u0004 שמותר לשוחקו \u0003ביום טוב\u0004 — משום \u0003דחזי\u0004 \u0005[ש\u0006הוא \u0005ראוי]\u0006 \u0003לקדרה\u0004 לבישול. ואולם אם משתמשים אנו בטעם זה, הלא \u0003יין ושמן\u0004 טרופים \u0003חזי נמי\u0004 \u0005[ראויים גם כן]\u0006 \u0003בשבת לחולה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין טורפין יין ושמן לחולה בשבת. אמר ר' שמעון בן אלעזר משום\u0004 (בשם) \u0003ר' מאיר: אף טורפין יין ושמן\u0004 בשבת.","ו\u0003אמר ר' שמעון בן אלעזר:\u0004 מעשה היה ו\u0003פעם אחת חש ר' מאיר במעיו\u0004 בשבת, \u0003ובקשנו לטרוף לו יין ושמן\u0004 לרפואה \u0003ולא הנחנו. אמרנו לו:\u0004 וכי \u0003דבריך יבטלו בחייך?!\u0004 שהרי אתה מתיר לטרוף לחולה. \u0003אמר לנו: אף על פי שאני אומר כך וחבירי אומרים כך,\u0004 ואין אני חוזר בי מדברי, מכל מקום — \u0003מימי לא מלאני לבי לעבור על דברי חבירי\u0004 ולעשות מעשה כדעתי. ומכאן נסיק: \u0003הוא ניהו\u0004 \u0005[זה]\u0006 ש\u0003מחמיר אנפשיה\u0004 \u0005[על עצמו],\u0006 \u0003אבל לכולי עלמא\u0004 — \u0003שרי\u0004 \u0005[לכל העולם\u0006 — \u0005מותר]!\u0006","ומתרצים, שיש לחלק בין הדברים: \u0003התם\u0004 \u0005[שם]\u0006 לצורך רפואה — \u0003לא בעי ליכא\u0004 \u0005[אין צריך טריפה יפה],\u0006 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 במילה \u0003בעי ליכא\u0004 \u0005[צריך טריפה יפה].\u0006 ושואלים: \u0003הכא נמי ניעביד\u0004 \u0005[כאן גם כן נעשה,\u0006 נטרוף\u0005]\u0006 \u0003ו\u0004אולם \u0003לא לילך\u0004 \u0005[נטרוף יפה]!\u0006 ומשיבים: אמנם כן עושים, ו\u0003היינו דקתני\u0004 \u0005[זהו ששנינו]:\u0006 \u0003נותן זה בפני עצמו וזה בפני עצמו,\u0004 שהכוונה היא שמותר לו לערבם, אבל אינו טורפם היטב.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בעבודת יום טוב: \u0003אין מסננין את החרדל במסננת שלו, ואין ממתקין אותו בגחלת. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: מאי שנא מהא דתנן\u0004 \u0005[במה שונה\u0006 דבר זה \u0005מזה ששנינו\u0006 במשנה\u0005]:\u0006 \u0003נותנים\u0004 בשבת \u0003ביצה במסננת של חרדל\u0004 כדי שתסתנן?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: יש לחלק בין הדברים ולומר כי \u0003התם\u0004 \u0005[שם]\u0006 — \u0003לא מיחזי\u0004 \u0005[אינו נראה]\u0006 \u0003כבורר,\u0004 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 — \u0003מיחזי\u0004 \u0005[נראה]\u0006 \u0003כבורר.\u0004 שכן הביצה אינה מסתננת ממש ואין מתבררים חלקים ממנה בתוך המסננת כמו החרדל.","מקודם שנינו ש\u0003אין ממתקין אותו,\u0004 את החרדל, \u0003בגחלת.\u0004 ושואלי ם: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ממתקין אותו בגחלת!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה],\u0006 וניתן לחלק ולומר כי \u0003כאן\u0004 שהתירו — מדובר \u0003בגחלת של מתכת,\u0004 שאין בכיבויה איסור מן התורה, ואילו \u0003כאן\u0004 שנאסר הדבר — הרי זה \u0003בגחלת של עץ.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: מאי שנא מבישרא אגומרי\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 החרדל \u0005מבשר ש\u0006מניחים \u0005על גחלים]\u0006 שמותר אף אם הגחלים כבו על ידי הדם הנוטף מן הכבש! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף לאביי: אין הדברים דומים, שכן \u0003התם\u0004 \u0005[שם]\u0006 — \u0003לא\u0004 \u0005[אי]\u0006 \u0003אפשר\u0004 לעשות זאת בדרך אחרת, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 בחרדל — \u0003אפשר\u0004 לעשות זאת \u0005בדרך אחרת.\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: מהו\u0004 הדין האם מותר \u0003לגבן\u0004 גבינה ביום טוב? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אסור.\u0004 ושאל אביי: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 הדבר \u0003מלישה\u0004 של פת המותרת ביום טוב? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003התם\u0004 \u0005[שם]\u0006 — \u0003לא\u0004 (אי) \u0003אפשר\u0004 שיהא הלחם מאתמול טוב כל כך ולכן מותו ללושו אף בו ביום, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 בגבינה מאתמול — \u0003אפשר.\u0004","והקשה לו: \u0003והא אמרי נהרדעי\u0004 \u0005[והרי אמרו\u0006 חכמי \u0005נהרדעא]\u0006 ש\u0003גבינה בת יומא\u0004 \u0005[יום]\u0006 \u0003מעליא\u0004 \u0005[מעולה\u0006 היא\u0005],\u0006 ומדוע אין עושים אותה בו ביום? ענה לו, \u0003הכי קאמרי\u0004 \u0005[כך אמרו]:\u0006 ש\u0003אפילו גבינה בת יומא\u0004 \u0005[יום]\u0006 \u0003מעליא\u0004 \u0005[מעולה\u0006 היא\u0005],\u0006 ואולם גבינה ששהתה זמן מרובה טובה יותר. ומשום כך לא התירו לגבן, שאין זה מצורכי יום טוב.","שנינו במשנה ש\u0003אין עושין לה\u0004 למילה \u0003חלוק\u0004 (כעין כיס לתחבושת) בשבת. \u0003אמר אביי,\u0004 כך \u0003אמרה לי אם\u0004 (אומנתי): \u0003האי חלוק\u0004 \u0005[חלוק זה]\u0006 ששמים כתחבושת על המילה \u0003דינוקא\u0004 \u0005[של תינוק],\u0006 \u0003לפניה לסיטרא לעילאי, דילמא מידביק גרדא מיניה, ואתי\u0004 \u0005[ישים אותו מצידו העליון\u0006 ואת החוטים מלמטה, \u0005שמא ידבק חוט ממנו\u0006 במילה, \u0005ויבוא\u0006 התינוק\u0005]\u0006 \u0003לידי\u0004 מצב בו יחתוך החוט את בשרו וייהפך ל\u0003כרות שפכה.\u0004 ומסופר כי \u0003אימיה\u0004 \u0005[אומנתו]\u0006 של \u0003אביי עבדא כיסתתא לפלגא\u0004 \u0005[היתה עושה\u0006 כעין \u0005כיס למחצית,\u0006 לאמצע\u0005]\u0006 כדי שלא תבוא המילה במגע עם שפת הבגד המלאה בחוטים. \u0003אמר אביי: האי ינוקא דלית ליה\u0004 \u0005[תינוק זה שאין\u0006 \u0003לו] חלוק\u0004 למילתו — \u0003לייתי בליתא דאית ליה שיפתא, וליכרכיה לשיפתא לתתאי, ועייף ליה לעילאי\u0004 \u0005[שיביא בגד בלוי שיש לו אימרה, ויכרוך את אימרתו מלמטה, ויקפל אותה מלמעלה],\u0006 שלא ידבקו בפצע חלקי חוטים מן הבלאי.","\u0003ו\u0004עוד \u0003אמר אביי, אמרה לי אם\u0004 (אומנתי): \u0003האי ינוקא דלא ידיע מפקתיה\u0004 \u0005[תינוק זה שאין יודעים יציאתו,\u0006 מקום פי הטבעת שלו\u0005]\u0006 שהעור מכסה אותה — \u0003לשייפיה מישחא ולוקמיה להדי יומא, והיכא דזיג ליקרעיה בשערתא\u0004 \u0005[שימרחוהו בשמן ושיעמידוהו מול\u0006 אור \u0005היום, ובמקום\u0006 שרואים \u0005ש\u0006הוא \u0005שקוף שיקרעו ב\u0006אמצעות \u0005שעורה]\u0006 \u0003שתי וערב, אבל בכלי מתכות\u0004 — \u0003לא\u0004 יעשה זאת, \u0003משום דזריף\u0004 \u0005[שגורם לדלקת ונפיחות]\u0006. \u0003ו\u0004עוד \u0003אמר אביי, אמרה לי אם\u0004 (אומנתי): \u0003האי ינוקא דלא מייץ\u0004 \u0005[תינוק זה שאיננו יונק]\u0006 — הרי זה כיון \u0003שמיקר דקר פומיה\u0004 \u0005[שקירר את פיו]\u0006 ואינו יכול לינוק. ו\u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]\u0006 — \u0003ליתו כסא גומרי, ולינקטיה ליה להדי פומיה, דחיים פומיה ומייץ\u0004 \u0005[שיביאו כוס\u0006 של \u0005גחלים, וישימו אותה ליד פיו שיתחמם פיו ויינק].\u0006 \u0003ו\u0004עוד \u0003אמר אביי, אמרה לי אם\u0004 (אומנתי): \u0003האי ינוקא דלא מנשתיה\u0004 \u0005[תינוק זה שאיננו יכול להטיל מים]\u0006 — \u0003לינפפיה בנפוותא ומנשתיה\u0004 \u0005[שיכניסו אותו בנפה\u0006 וינערו אותו בה \u0005ויוכל להטיל מים].\u0006","\u0003ו\u0004עוד \u0003אמר אביי, אמרה לי אם\u0004 (אומנתי): \u0003האי ינוקא דלא מעוי\u0004 \u0005[תינוק זה שאינו נושם]\u0006 — \u0003ליתו סליתא דאימיה ולישרקיה עילויה, ומעוי\u0004 \u0005[יביאו את שיליית אמו, וישימו עליו, וינשום].\u0006 \u0003ו\u0004עוד \u0003אמר אביי, אמרה לי אם\u0004 (אומנתי): \u0003האי ינוקא דקטין\u0004 \u0005[תינוק זה ש\u0006הוא \u0005קטן\u0006 מידי\u0005],\u0006 \u0003לייתו לסילתא דאימיה, ולישרקיה עילויה מקוטנא לאולמא\u0004 \u0005[שיביאו את שיליית אמו וישפשפנה בו מצידה הקצר לצידה הרחב].\u0006 \u0003ואי אלים\u0004 \u0005[ואם חזק,\u0006 גדול הוא מדי\u0005]\u0006 — יעשה כן \u0003מאולמא לקוטנא\u0004 \u0005[מן הצד הרחב אל הצד הקצר].\u0006 \u0003ו\u0004עוד \u0003אמר אביי, אמרה לי אם\u0004 (אומנתי): \u0003האי ינוקא דסומק\u0004 \u0005[תינוק זה ש\u0006הוא \u0005אדום]\u0006 — הרי זה משום \u0003דאכתי\u0004 \u0005[שעדיין]\u0006 \u0003לא איבלע ביה דמא\u0004 \u0005[נבלע\u0006 \u0003בו הדם],\u0004 ותקנתו: \u0003ליתרחו ליה\u0004 \u0005[ימתינו לו]\u0006 \u0003עד דאיבלע ביה דמא, ולימהלוה\u0004 \u0005[שיבלע בו הדם, וימולו אותו].\u0006 וכן בתינוק שהוא \u0003ירוק\u0004 (חיור) \u0003ואכתי לא נפל ביה דמיה\u0004 \u0005[ועדיין לא נכנס בו דמו]\u0006 — \u0003ליתרחו\u0004 \u0005[שימתינו]\u0006 \u0003עד דנפל ביה דמיה, ולימהלוה\u0004 \u0005[שיבא בו דמו, וימולו אותו].\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' נתן: פעם אחת הלכתי לכרכי הים, ובאת\u0004 (באה) \u0003אשה אחת לפני\u0004 אחר \u0003שמלה\u0004 את \u0003בנה\u0004 ה\u0003ראשון ומת,\u0004 וכן את ה\u0003שני ומת,\u0004 ומשחששה למול את ה\u0003שלישי\u0004 שמא ימות אף הוא, \u0003הביאתו לפני,\u0004 ו\u0003ראיתיו שהוא אדום. אמרתי לה: המתיני עד שיבלע בו דמו, המתינה לו עד שנבלע בו דמו, ומלה אותו וחיה, והיו קורין\u0004 ל\u0003אותו\u0004 התינוק \u0003\"נתן הבבלי\" על שמי.\u0004","ועוד סיפר ר' נתן: \u0003שוב פעם אחת הלכתי למדינת קפוטקיא, ובאת\u0004 (באה) \u0003אשה אחת לפני\u0004 אחר \u0003שמלה\u0004 את \u0003בנה\u0004 ה\u0003ראשון ומת,\u0004 וכן את ה\u0003שני ומת,\u0004 ומשחששה למול את ה\u0003שלישי הביאתו לפני,\u0004 ו\u0003ראיתיו שהוא ירוק. הצצתי בו ולא ראיתי בו דם ברית,\u0004 כלומר, שהיה מחוסר דם. \u0003אמרתי לה: המתיני לו עד שיפול בו דמו, והמתינה לו ומלה אותו וחיה, והיו קורין שמו \"נתן הבבלי\" על שמי.\u0004"],["\u0003מרחיצין את הקטן, בין לפני המילה ובין לאחר המילה\u0004 בשבת, \u0003ומזלפין\u0004 (מתיזים) \u0003עליו\u0004 מים חמים \u0003ביד, אבל לא בכלי,\u0004 בכדי לעשות שינוי. \u0003ר' אלעזר בן עזריה אומר: מרחיצין את הקטן,\u0004 אפילו \u0003ביום השלישי\u0004 למילתו \u0003שחל להיות בשבת,\u0004 שהרי ביום השלישי למילה התינוק נחשב כיש בו סכנה, וכפי \u0003שנאמר\u0004 באנשי שכם שמלו: \u0003\"ויהי ביום השלישי בהיותם כאבים\"\u0004 (בראשית לד, כה), והרי שאף ביום השלישי כאב המילה קרוב לסכנה.","תינוק שיש \u0003ספק\u0004 אם למולו אם לאו, \u0003ו\u0004כן \u0003אנדרוגינוס\u0004 (מי שיש לו איברי זכר ונקבה) — \u0003אין מחללין עליו את השבת\u0004 כדי למולו, כיון שאין מילתו מחוייבת ודאי, וחילול שבת יש בכך. \u0003ור' יהודה מתיר באנדרוגינוס.\u0004","מתחילה מקשים על סגנון המשנה נאמר בה שמזלפים על הקטן ביד, ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרת\u0004 ב\u0003רישא\u0004 \u0005[מתחילה]\u0006 ש\u0003מרחיצין\u0004 אותו, ואם להרחיץ מותר — לזלף לא כל שכן!","\u0003רב יהודה ורבה בר אבוה דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 שמשנה זו בדרך הסגנון של \u0003\"כיצד\" תני\u0004 \u0005[שנוי]\u0006 ומשפט אחד בא לבאר את משנהו. וכך יש להבינה: \u0003מרחיצין את הקטן בין לפני מילה בין לאחר מילה. כיצד\u0004 עושים זאת? — \u0003מזלפין עליו ביד אבל לא בכלי.\u0004","\u0003אמר רבא: והא\u0004 \u0005[והרי]\u0006 בלשון \u0003\"מרחיצין\" קתני\u0004 \u0005[שנינו],\u0006 והרחצה אינה זילוף! \u0003אלא אמר רבא: הכי קתני\u0004 \u0005[כך שנינו]:\u0006 \u0003מרחיצין את הקטן בין מלפני\u0004 ה\u0003מילה בין לאחר המילה, ביום הראשון\u0004 למילה — \u0003כדרכו, וביום השלישי שחל להיות בשבת\u0004 — רק \u0003מזלפין עליו ביד, אבל לא בכלי,\u0004 ובודאי שאין מרחיצין. ואילו \u0003ר' אלעזר בן עזריה אומר:\u0004 אף \u0003מרחיצין את הקטן\u0004 אף \u0003ביום השלישי שחל להיות בשבת,\u0004 שהרי הוא נחשב כיש בו סכנה, וכפי \u0003שנאמר: ויהי ביום השלישי בהיותם כאבים.\u0004","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא: מרחיצין את הקטן בין לפני\u0004 ו\u0003בין לאחר מילה, ביום הראשון\u0004 — \u0003כדרכו, וביום השלישי שחל להיות בשבת\u0004 — \u0003מזלפין עליו ביד,\u0004 אבל אין מרחיצין. \u0003ר' אלעזר בן עזריה אומר:\u0004 אף \u0003מרחיצין את הקטן ביום השלישי שחל להיות בשבת. ואף על פי שאין ראיה\u0004 גמורה \u0003לדבר\u0004 מכל מקום יש \u0003זכר לדבר,\u0004 וכפי \u0003שנאמר: \"ויהי ביום השלישי בהיותם כאבים\".\u0004","וממשיכה הברייתא: \u0003וכשהן מזלפין\u0004 — \u0003אין מזלפין\u0004 מים \u0003לא בכוס ולא בקערה ולא בכלי\u0004 אחר, \u0003אלא ביד.\u0004 ומעירים: \u0003אתאן\u0004 \u0005[באנו]\u0006 \u0003ל\u0004שיטת \u0003התנא קמא\u0004 \u0005[הראשון],\u0006 שהרי הביאור כיצד נעשה הזילוף אינו לשיטת ר' אלעזר בן עזריה אלא המשך לדברי התנא הראשון.","ומעירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אף על פי שאין ראיה לדבר\u0004 מכל מקום יש \u0003זכר לדבר\"?\u0004 מדוע קורא לכך \"זכר לדבר\"? והלא לכאורה ראיה גמורה היא שביום השלישי עדיין גדול כאב המילה! ומשיבים: אכן אין זו ראיה גמורה \u0003משום\u0004 שבאדם \u0003גדול\u0004 (מבוגר) \u0003לא סליק בישרא הייא\u0004 \u0005[אין הבשר מתרפא מיד],\u0006 \u0003קטן סליק ביה בישרא הייא\u0004 \u0005[בקטן מתרפא הבשר מיד]\u0006 ושמא ביום השלישי שוב אינו מסוכן.","ומסופר: \u0003ההוא דאתא לקמיה\u0004 \u0005[אדם אחד בא לפני]\u0006 \u0003רבא\u0004 לשאול בענין רחיצת תינוק לאחר מילה, \u0003אורי ליה כשמעתיה\u0004 \u0005[הורה לו כשמועתו,\u0006 כהלכתו\u0005]\u0006 שלדעת הכל מותר לרחוץ את התינוק ביום הראשון. אחר כך \u0003איחלש\u0004 \u0005[נחלש,\u0006 חלה\u0005]\u0006 \u0003רבא\u0004 בחולי, ו\u0003אמר: אנא בהדי תרגימנא דסבי\u0004 \u0005[אני בין שיטותיהם של הזקנים]\u0006 \u0003למה לי\u0004 להתערב, שהרי חכמי הדור הקודם פירשו את הדברים בדרך אחרת ולחומרה, וסבר רבא שנענש בידי שמים על שהקל בדעת חכמי הדור הקודם.","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרבא: והתניא כוותיה דמר\u0004 \u0005[והרי שנויה\u0006 ברייתא \u0005כשיטתו של אדוני],\u0006 ומשום מה חושש אתה לפירושך? הרי ראויה היא! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מתניתין כוותייהו דיקא\u0004 \u0005[משנתנו כשיטתם מדוקדקת].\u0006","ו\u0003ממאי\u0004 \u0005[ממה]\u0006 אפשר להסיק זאת — \u0003מדקאמר\u0004 \u0005[מ\u0006מה שאמר] שם ש\u0003ר' אלעזר בן עזריה אומר: מרחיצין את הקטן ביום השלישי שחל להיות בשבת, אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שלדעת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003מזלפין\u0004 בלבד \u0003קאמר\u0004 \u0005[אמר],\u0006 ולא התיר כלל להרחיץ את התינוק, אף ביום הראשון — \u0003היינו דקאמר ליה\u0004 \u0005[זהו שאמר לו]\u0006 \u0003ר' אלעזר בן עזריה\u0004 שלדעתו אף \u0003מרחיצין. אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 אף \u0003מרחיצין ביום הראשון קאמר\u0004 \u0005[אמר],\u0006 \u0003ומזלפין ביום השלישי,\u0004 אם כן \u0003האי\u0004 \u0005[\u0006ביטוי \u0005זה]\u0006 ש\u0003ר' אלעזר בן עזריה אומר\u0004 ש\u0003מרחיצין\u0004 אינו במקומו, ו\u0003\"אף מרחיצין\" מיבעי ליה\u0004 \u0005[היה לו]\u0006 לומר, שהרי לא נחלק על עיקר היתר הרחיצה, אלא על רחיצה ביום מסויים. וכיון שדקדוק דברי המשנה מסייע לאמוראים ההם אין כוחה של ברייתא לעקור את הדבר.","ולגופה של הלכה, \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' אלעזר: הלכה כ\u0004שיטת \u0003ר' אלעזר בן עזריה.\u0004","\u0003הוו\u0004 \u0005[עסקו]\u0006 \u0003בה\u0004 בשאלה זו \u0003במערבא\u0004 \u0005[במערב,\u0006 בארץ ישראל\u0005]:\u0006 האם מה שנאמר בענין רחיצה הכוונה ל\u0003הרחצת כל גופו\u0004 של התינוק \u0003או הרחצת\u0004 מקום ה\u0003מילה\u0004 בלבד?","\u0003אמר להו ההוא מרבנן\u0004 \u0005[להם אחד החכמים],\u0006 \u0003ור' יעקב שמיה\u0004 \u0005[שמו]:\u0006 \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר שהמדובר ב\u0003הרחצת כל גופו, דאי סלקא דעתך\u0004 \u0005[שאם יעלה על דעתך]\u0006 לומר שנחלקו ב\u0003הרחצת מילה, מי גרע\u0004 \u0005[האם גרוע\u0006 הדבר\u0005]\u0006 \u0003מחמין\u0004 ששמים \u0003על גבי מכה\u0004 (פצע), שכן \u0003אמר רב: אין מונעין חמין ושמן מעל גבי מכה בשבת,\u0004 ואם כן בודאי מותר לרחוץ אף את המילה!","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף:\u0004 אין מקום לפתרון זה, \u0003ולא שני לך\u0004 \u0005[ו\u0006כי \u0005אין זה שונה לך,\u0006 בעיניך\u0005]\u0006 \u0003בין חמין שהוחמו בשבת לחמין שהוחמו מערב שבת?\u0004 שחמין שהוחמו מערב שבת יש בהם רק החשש שבגזירת איסור רפואה, ואילו חמין שהוחמו בשבת הוא חילול שבת.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב דימי\u0004 על דברי רב יוסף: \u0003וממאי דהכא\u0004 \u0005[וממה\u0006 מסיק \u0003אתה\u0004 \u0005שכאן]\u0006 \u0003בחמין שהוחמו בשבת פליגי\u0004 \u0005[נחלקו]?\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003בחמין שהוחמו בערב שבת פליגי\u0004 \u0005[נחלקו]?!\u0006 \u0003אמר אביי: אנא בעאי דאישני ליה\u0004 \u0005[אני רציתי לתרץ לו],\u0006 \u0003וקדם ושני ליה\u0004 \u0005[ותירץ לו]\u0006 \u0003רב יוסף\u0004 שבודאי אין מדברים אלא בחימום חמין בשבת \u0003מפני שסכנה הוא לו.\u0004","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 בשם אמורא אחר ש\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' אבהו\u0004 שכך \u0003אמר ר' אלעזר, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שכך \u0003אמר ר' אבהו\u0004 שכך \u0003אמר ר' יוחנן: הלכה\u0004 היא \u0003כ\u0004שיטת \u0003ר' אלעזר בן עזריה בין בחמין שהוחמו בשבת, בין בחמין שהוחמו מערב שבת, בין הרחצת כל גופו, בין הרחצת\u0004 מקום ה\u0003מילה\u0004 בלבד, \u0003מפני שסכנה היא לו.\u0004","הזכרנו קודם בדרך אגב את דברי רב בענין טיפול בפצע בשבת. ומעתה באים לדון בהם \u0003גופא\u0004 \u0005[לגופם].\u0006 שנינו ש\u0003אמר רב: אין מונעין חמין ושמן מעל גבי מכה בשבת. ושמואל אמר:\u0004 אסור לתת את החמין או השמן ישירות על גבי המכה משום שנראה הדבר כרפואה, אלא \u0003נותן\u0004 את החמין או השמן \u0003חוץ למכה\u0004 מעליה, \u0003ושותת ויורד למכה\u0004 עצמה.","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא: \u0003אין נותנין שמן וחמין על גבי מוך\u0004 (סמרטוט) \u0003ליתן\u0004 אותו \u0003על גבי\u0004 ה\u0003מכה בשבת,\u0004 והרי זה כדברי שמואל האוסר לעשות דבר שנראה כעשוי לרפואה, וקשה לרב! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 לא משום חשש רפואה אסרו אלא \u0003משום\u0004 חשש \u0003סחיטה.\u0004","ועוד \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא דומה: \u0003אין נותנין חמין ושמן על גבי מוך, שעל גבי מכה בשבת,\u0004 והרי ראיה מכך לשיטת שמואל. ותירצו: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 \u0003משום סחיטה\u0004 חששו.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא מפורשת \u0005כשיטתו]\u0006 של \u0003שמואל: אין נותנין חמין ושמן על גבי מכה בשבת, אבל נותנין חוץ למכה ושותת ויורד למכה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא אחרת: \u0003נותנין על גבי המכה מוך יבש וספוג יבש, אבל לא גמי\u0004 (מין סוף) \u0003יבש ולא כתיתין\u0004 (סמרטוטים) \u0003יבשין.\u0004 ומעירים: \u0003קשיא\u0004 \u0005[קשה]\u0006 מענין \u0003כתיתין\u0004 על ענין \u0003כתיתין,\u0004 שהרי מתחילה התיר מוך ואחר אסר כתיתים! ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאסר — הרי זה \u0003בחדתי\u0004 \u0005[בחדשים]\u0006 שמרפאים, \u0003הא\u0004 \u0005[זה]\u0006 שהתיר הרי זה \u0003בעתיקי\u0004 \u0005[בישנים]\u0006 שאינם מועילים כל כך. \u0003אמר אביי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003הני\u0004 \u0005[אלו]\u0006 ה\u0003כתיתין מסו\u0004 \u0005[מרפאים],\u0006 ונלמד מכאן לענין רפואת כל מכה.","שנינו במשנה כי תינוק שיש \u0003ספק\u0004 אם למולו אם לאו \u0003ו\u0004כן \u0003אנדרוגינוס\u0004 אין מילתם דוחה את השבת אף שהיא היום השמיני ללידתם. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: נאמר \"וביום השמיני ימול בשר ערלתו\" (ויקרא יב, ג), ופירשו את הכתוב: \u0003\"ערלתו\"\u0004 משמעו — \u0003ערלתו ודאי דוחה את השבת,\u0004"],["\u0003ו\u0004אולם \u0003לא ספק\u0004 שאין ברור אם יש למול אותו \u0003דוחה את השבת.\u0004 ועוד, \u0003\"ערלתו\"\u0004 משמע — ערלתו \u0003ודאי דוחה את השבת, ו\u0004כן \u0003לא אנדרוגינוס\u0004 שספק אם חייב הוא מילה \u0003דוחה את השבת.\u0004","ואילו \u0003ר' יהודה אומר: אנדרוגינוס דוחה את השבת, ו\u0004אם לא נימול הרי כשהגדיל \u0003ענוש כרת.\u0004 והוא מדקדק מן המקרא: \u0003ערלתו ודאי דוחה את השבת, ולא\u0004 מילת \u0003זה שנולד בין השמשות דוחה את השבת.\u0004 וכן \u0003ערלתו ודאי דוחה את השבת ולא\u0004 מילת מי ש\u0003נולד כשהוא מהול\u0004 (שנולד בלא ערלה) \u0003דוחה את השבת.\u0004 שאכן נחלקו בית שמאי ובית הלל בדינו של ילד כזה \u0003שבית שמאי אומרים: צריך להטיף ממנו דם ברית\u0004 כעין מילה, \u0003ובית הלל אומרים: אינו צריך,\u0004 שהרי הוא נימול כבר.","\u0003אמר ר' שמעון בן אלעזר:\u0004 לא על כך היתה המחלוקת, ו\u0003לא נחלקו בית שמאי ובית הלל על\u0004 זה ש\u0003נולד כשהוא מהול שצריך להטיף ממנו דם ברית, מפני\u0004 שהסכימו \u0003שערלה כבושה היא,\u0004 כלומר, שילד זה אינו מהול ממש אלא שאין ערלתו נראית. \u0003על מה נחלקו\u0004 — \u0003על גר שנתגייר כשהוא מהול,\u0004 שמלו אותו משום מה בהיותו גוי, \u0003שבית שמאי אומרים: צריך להטיף ממנו דם ברית, ובית הלל אומרים: אין צריך להטיף ממנו דם ברית,\u0004 ודיו בטבילה בלבד.","מקודם הבאנו את מה ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 ש\u0003לא\u0004 מילת \u0003ספק דוחה את השבת.\u0004 ושואלים: \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה],\u0006 איזה ספק נוסף? ומשיבים: \u0003לאתויי הא דתנו רבנן\u0004 \u0005[להביא\u0006 את \u0005זה ששנו חכמים]:\u0006 ילד \u0003בן שבעה,\u0004 כלומר, שנולד לאחר שבעה חדשים של הריון, \u0003מחללין עליו את השבת,\u0004 שהוא קרוב לחיים. \u0003ובן שמנה\u0004 חדשי הריון סבורים שמסוכן הוא, ובודאי לא יחיה, ולכן \u0003אין מחללין עליו\u0004 את \u0003השבת.\u0004 ואף זה שהוא \u0003ספק בן שבעה ספק בן שמונה\u0004 חדשים — \u0003אין מחללין עליו את השבת.\u0004","ואמרו: \u0003בן שמונה\u0004 חדשים — \u0003הרי הוא כאבן\u0004 לדיני מוקצה, \u0003ואסור לטלטלו. אבל אמו שוחה\u0004 (מתכופפת עליו) \u0003ומניקתו מפני הסכנה\u0004 שלה, שמא מתוך שאינה מניקה יגרום החלב שבדדיה למחלה.","לענין פסק הלכה בנולד מהול \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בכך חכמים, \u0003רב אמר: הלכה כ\u0004דעת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 כלומר, כשיטת ר' יהודה במחלוקת בית שמאי ובית הלל שלדעתו נחלקו בנולד מהול, וכיון שאנו פוסקים כבית הלל, נמצא שילד שנולד כשהוא מהול אינו צריך אפילו הטפת דם ברית. \u0003ושמואל אמר: הלכה כ\u0004שיטת \u0003ר' שמעון בן אלעזר\u0004 שלא נחלקו בית הלל ובית שמאי בנולד מהול ולדעת הכל הטפת דם ברית.","ומסופר: \u0003רב אדא בר אהבה אתיליד ליה ההוא ינוקא\u0004 \u0005[נולד לו תינוק אחד]\u0006 \u0003כשהוא מהול,\u0004 והגיע זמן מילתו בשבת. \u0003אהדריה אתליסר מהולאי\u0004 \u0005[החזירו על שלושה עשר מוהלים]\u0006 ולא רצו למולו, \u0003עד\u0004 שמלו בעצמו ואירע \u0003דשוייה\u0004 \u0005[שעשאו]\u0006 בשל כך \u0003כרות שפכה,\u0004 שלא ידע למול ופצע אותו יותר מכדי הצורך. \u0003אמר\u0004 רב אדא בר אהבה: \u0003תיתי\u0004 \u0005[מגיע]\u0006 \u0003לי\u0004 דבר זה, משום \u0003דעברי\u0004 \u0005[שעברתי]\u0006 על דברי \u0003רב,\u0004 שהרי פסק רב שהנולד כשהוא מהול אף הטפת דם ברית אינו צריך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: ו\u0004כי על דברי \u0003שמואל לא עבר?! אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר שמואל\u0004 ופסק שצריך להטיף ממנו דם ברית רק \u0003בחול,\u0004 ואולם \u0003בשבת מי\u0004 \u0005[האם]\u0006 \u0003אמר?\u0004 ובוודאי אין מחללים שבת במקרה זה. ומעירים כי \u0003הוא\u0004 רב אדא בר אהבה \u0003סבר\u0004 \u0005[סבור היה]\u0006 כשיטה אחרת, שלא רק שחוששים אנו כאן לערלה כבושה, אלא \u0003ודאי ערלה כבושה היא.\u0004 וכיון שוודאי ערלה היא, יש צורך לעשות בתינוק מעין מילה, ודוחה היא אם כן את השבת. \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שכבר נחלקו אמוראים בדבר ילד שנולד כשהוא מהול האם מותר להטיף בו דם ברית בשבת, \u0003רבה אמר: חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא ערלה כבושה היא,\u0004 וספק אם כן אם הוא ערל גמור ומותר למולו בשבת או שמא לא. ואילו \u0003רב יוסף אומר: ודאי ערלה כבושה היא,\u0004 ובודאי מותר למולו, שהרי ודאי ערל הוא.","\u0003אמר רב יוסף: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 סברה זו — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר הקפר אומר:\u0004 מסורת היא כי \u0003לא נחלקו בית שמאי ובית הלל על\u0004 ילד ש\u0003נולד כשהוא מהול\u0004 — \u0003שצריך להטיף ממנו דם ברית,\u0004 ו\u0003על מה נחלקו\u0004 — אם \u0003לחלל עליו את השבת\u0004 לצורך מילתו. \u0003בית שמאי אומרים מחללין עליו את השבת, ובית הלל אומרים: אין מחללין עליו את השבת.\u0004 ומכאן מסיק רב יוסף: \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003מכלל\u0004 הדברים אתה למד שה\u0003תנא קמא\u0004 \u0005הראשון]\u0006 שר' אליעזר הקפר בא לחלוק עליו \u0003סבר\u0004 \u0005[סבור]\u0006 ש\u0003מחללין עליו את השבת\u0004 לדברי הכל, ובא ר' אליעזר הקפר לחלוק על דבריו ולומר שלא בכך נחלקו בית שמאי ובית הלל אם מחללין עליו את השבת?!","ודוחים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 של \u0003דברי הכל אין מחללין\u0004 את השבת \u0003קאמר\u0004 \u0005[אמר],\u0006 ובא ר' אליעזר הקפר לומר שיש מחלוקת בדבר! ומיד דוחים טענה זו: \u0003אם כן\u0004 שבא ר' אליעזר הקפר לומר שיש מחלוקת בדבר אם מתירים לחלל שבת, הרי מי הוא החולק — בית שמאי, וכי \u0003ר' אליעזר הקפר טעמא\u0004 \u0005[\u0006את \u0005הטעם]\u0006 של \u0003בית שמאי אתא לאשמעינן\u0004 \u0005[בא להשמיענו]?\u0006 והלא שיטתם דחויה מן ההלכה, ולא הוצרך לבוא להוסיף דברים בענין זה! ומשיבים שאף זו אינה ראיה גמורה: \u0003דילמא הכי קאמר\u0004 \u0005[שמא כך אמר]:\u0006 \u0003לא נחלקו בית שמאי ובית הלל בדבר זה\u0004 בענין מילה בשבת, אלא רק בצורך בהטפת דם ברית בחול.","\u0003אמר ר' אסי:\u0004 כלל הוא ש\u0003כל שאמו טמאה לידה\u0004 בלידתו — \u0003נימול לשמונה\u0004 ימים, \u0003וכל שאין אמו טמאה לידה,\u0004 כגון ילד שלא נולד כדרכו אלא הוצא על ידי ניתוח — \u0003אין נימול לשמנה\u0004 דווקא, \u0003שנאמר \"אשה כי תזריע וילדה זכר וטמאה\u0004 שבעת ימים, \u0003וביום השמיני ימול בשר ערלתו\"\u0004 (ויקרא יב, ב-ג), ובכתוב זה השווה הכתוב את הדברים, ללמד שרק אותו ילד שאמו טמאה בלידתו הוא שנימול ביום השמיני.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: דורות הראשונים\u0004 שמאברהם עד מתן תורה \u0003יוכיחו, שאין אמו טמאה לידה,\u0004 שהרי עדיין לא ניתנה אז הלכה זו של טומאת לידה \u0003ו\u0004בכל זאת \u0003נימול\u0004 הילד \u0003לשמנה\u0004 ימים כאמור בתורה בספר בראשית!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אסי: מכאן אין להוכיח, שכן \u0003נתנה תורה\u0004 לאחר מכן,"],["\u0003ונתחדשה הלכה\u0004 ואין להוכיח מדברים שהיו לפני מתן תורה.","ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]\u0006 לגבי עיקר הלכתו של ר' אסי? \u0003והא איתמר\u0004 \u0005[והרי נאמר]\u0006 שיש מחלוקת בהלכה זו. ששנינו: \u0003יוצא דופן\u0004 (ילד שלא נולד כדרכו אלא על ידי ניתוח) \u0003ומי שיש לו שתי ערלות,\u0004 נחלקו בו \u0003רב הונא ורב חייא בר רב. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: מחללין עליו את השבת\u0004 במילתו. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אין מחללין.\u0004 ו\u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003אלא\u0004 בענין ההיתר \u0003לחלל עליו את השבת, אבל\u0004 בכלל למולו \u0003לשמנה\u0004 ימים — \u0003ודאי מהלינן ליה\u0004 \u0005[מלים אנו אותו]\u0006 אף שיוצא דופן אין אמו טמאה לידה! ומשיבים: \u0003הא בהא תליא\u0004 \u0005[זו בזו תלויה],\u0006 ואין כאן שתי מחלוקות, אלא הסבור שמחללים עליו את השבת סבור אף שמלים אותו ביום השמיני.","ומעירים: דבר זה שאמר רב אסי שחובת המילה לשמונה ימים תלויה בהיות האם טמאה לידה, כבר \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 הוא שנוי. ששנינו: \u0003יש יליד בית\u0004 (ילד שנולד בתוך בית ישראל לשפחה כנענית, שיש למולו כשאר עבדי ישראל), \u0003ש\u0004הוא \u0003נימול ל\u0004יום \u0003אחד,\u0004 כלומר, מיד עם לידתו. \u0003ויש יליד בית שנימול לשמנה. יש\u0004 עבד \u0003מקנת כסף שנימול ל\u0004יום \u0003אחד,\u0004 ביום הראשון ללידתו, \u0003ויש מקנת כסף שנימול לשמונה.\u0004","ומסבירים, \u0003כיצד? לקח\u0004 (קנה) \u0003שפחה מעוברת ואחר כך ילדה\u0004 ברשותו ילד — \u0003זהו מקנת כסף\u0004 (שהרי קנה את העובר עם השפחה) \u0003הנימול לשמונה.\u0004 ואם \u0003לקח שפחה\u0004 שכבר ילדה \u0003ו\u0004קנה את \u0003ולדה עמה\u0004 מיד כשהגיע התינוק לרשותו חייב למולו, ונמצא ש\u0003זו היא מקנת כסף שנימול לאחד.\u0004","\u0003ו\u0004כן \u0003יש יליד בית שנימול לשמונה, כיצד?\u0004 — כגון ש\u0003לקח שפחה ונתעברה אצלו וילדה\u0004 — \u0003זהו יליד בית שנימול לשמנה. ר' חמא אומר,\u0004 יש לחלק בצורה אחרת בין המקרים: אם \u0003ילדה\u0004 השפחה \u0003ואחר כך הטבילה\u0004 לשם שפחות — \u0003זהו יליד בית שנימול לאחד.\u0004 ואם \u0003הטבילה ואחר כך ילדה\u0004 — \u0003זהו יליד בית שנימול לשמנה.\u0004","\u0003ו\u0004נמצא שה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003לא שני ליה\u0004 \u0005[אינו שונה לו,\u0006 אינו מחלק\u0005]\u0006 \u0003בין הטבילה ואחר כך ילדה\u0004 ו\u0003בין ילדה ואחר כך הטבילה, דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003אין אמו טמאה לידה,\u0004 שהרי לפני טבילתה אינה חייבת כלל במצוות, ואין בה טומאת לידה, מכל מקום הוא \u0003נימול לשמנה.\u0004 נמצא שנחלקו ר' חמא ותנא קמא בהלכה זו שקבע ר' אסי.","ולגופו של דבר \u0003אמר רבא: בשלמא\u0004 \u0005[נניח],\u0006 \u0003ל\u0004שיטת \u0003ר' חמא משכחת לה\u0004 \u0005[מוצא אתה אותה\u0006 אפשרות\u0005]\u0006 שיהא \u0003יליד בית\u0004 ה\u0003נימול לאחד,\u0004 וכן \u0003יליד בית\u0004 ה\u0003נימול לשמנה,\u0004 ו\u0003מקנת כסף\u0004 ה\u0003נימול לאחד ומקנת כסף\u0004 ה\u0003נימול לשמנה,\u0004 באופן זה: אם \u0003ילדה ו\u0004רק \u0003אחר כך הטבילה\u0004 — הרי \u0003זהו יליד בית שנימול לאחד. הטבילה ואחר כך ילדה\u0004 — \u0003זהו יליד בית שנימול לשמנה.\u0004","\u0003מקנת כסף\u0004 ה\u0003נימול לשמנה\u0004 — \u0003כגון שלקח שפחה מעוברת\u0004 ונמצא ששילם גם בעד העובר וקנאו, \u0003והטבילה\u0004 לאחר מכן, \u0003ואחר כך ילדה. מקנת כסף\u0004 ה\u0003נימול לאחד\u0004 — \u0003כגון שלקח\u0004 אדם \u0003זה שפחה, וזה,\u0004 אדם אחר, קנה את \u0003עוברה\u0004 ומיד כשנולד יש לו למולו, שמאחר ואין לבעל העובר חלק באמו, הריהו נימול לאחד.","\u0003אלא ל\u0004דעת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 \u0003בשלמא כולהו משכחת להו\u0004 \u0005[נניח כל\u0006 המקרים \u0005מוצא אתה אותם]\u0006 גם לשיטתו, \u0003אלא יליד בית\u0004 ה\u0003נימול לאחד היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותה\u0006 אפשרות\u0005]?\u0006","\u0003אמר ר' ירמיה: בלוקח שפחה לעוברה,\u0004 שקונה שפחה לא לצורך עצמה, אלא כדי שעוברה יהא שלו.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[\u0006דבר \u0005זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003קנין פירות לאו\u0004 \u0005[לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 שאדם שאינו קונה את גוף הרכוש אלא רק את הרווחים והפירות היוצאים ממנו אינו נחשב כקונה את גוף הדבר. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003קנין פירות כקנין הגוף דמי\u0004 \u0005[נחשב]\u0006 \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי אינו מחלק אם קונה את גוף השפחה, או קונה רק את פרי עמלה או ילדים שיולדת!","\u0003אמר רב משרשיא:\u0004 לשיטה זו יש להסביר כי מדובר \u0003ב\u0004אופן ש\u0003לוקח שפחה על מנת שלא להטבילה,\u0004 שיכולה היא להתנות עמו, או הוא עמה, שלא יטבילנה לשפחות אלא תישאר גויה כשהיתה, ואילו עוברה הוא עבד שנולד לישראל, וחייב מיד עם לידתו במילה.","בדברים הקרובים לנושא שדנו בו מביאים עוד, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003רבן שמעון בן גמליאל אומר: כל\u0004 ילד \u0003ששהה\u0004 כשהוא חי \u0003שלשים יום\u0004 אחר לידתו, \u0003באדם\u0004 — \u0003אינו\u0004 חשוד עוד שהוא \u0003נפל,\u0004 ויש לשער שהוא ילד רגיל שימשיך לחיות. וראיה לדבר ממה \u0003שנאמר\u0004 בדיני פדיון וערכים: \u0003\"ופדויו מבן חדש תפדה\u0004 בערכך כסף חמשת שקלים בשקל הקודש עשרים גרה הוא\u0003\"\u0004 (במדבר יח, טז), נמצא שבפחות מבן חודש אין לו ערך כלל, שעדיין אין ידוע אם אינו נפל. וכן וולד ששהה \u0003שמנת ימים בבהמה\u0004 — שוב \u0003אינו נפל,\u0004 וכפי \u0003שנאמר: \"\u0004שור או כשב או עז כי יוולד והיה שבעת ימים תחת אמו \u0003ומיום השמיני והלאה ירצה לקרבן\u0004 אשה לה'\" (ויקרא כב, כז).","ושואלים: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא שהה\u0004 עדיין הילד עד שלושים יום — \u0003ספיקא הוי\u0004 \u0005[ספק הוא]\u0006 אם נפל הוא או לא לגבי כמה הלכות,"],["\u0003מימהל\u0004 \u0005[למול]\u0006 \u0003היכי מהלינן ליה\u0004 \u0005[כיצד אנו מלים אותו],\u0006 שמא נפל הוא ואין לחלל שבת על מילתו!","\u0003אמר רב אדא בר אהבה: מלין אותו ממה נפשך\u0004 (בכל אופן שנוכל לדון), ומתוך שיקול זה: \u0003אם חי הוא\u0004 — \u0003שפיר קא מהיל\u0004 \u0005[יפה הוא מוהל],\u0006 \u0003ואם לאו\u0004 \u0005[לא],\u0006 אלא נפל הוא — \u0003מחתך בבשר הוא,\u0004 והמחתך בבשר המת אינו נחשב כעושה חבורה, ואם כן אינו עושה מלאכת איסור.","ומקשים: \u0003ואלא הא דתניא\u0004 \u0005[\u0006הלכה \u0005זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003ספק\u0004 הוא \u0003בן שבעה\u0004 חדשים להריון, \u0003ספק בן שמונה\u0004 — \u0003אין מחללין עליו את השבת,\u0004 והשאלה היא: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003נימהליה\u0004 \u0005[נמול אותו]\u0006 בשבת \u0003ממה נפשך!\u0004 שכן \u0003אם חי הוא\u0004 — \u0003שפיר קא מהיל\u0004 \u0005[יפה הוא מוהל],\u0006 \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003מחתך בבשר הוא,\u0004 וחיתוך בשבת בבשר המת אין בו איסור!","\u0003אמר מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא: אנא\u0004 \u0005[אני]\u0006 \u0003ורב נחומי בר זכריה תרגימנא\u0004 \u0005[הסברנו]:\u0006 אכן, \u0003מימהיל\u0004 \u0005[למול]\u0006 — \u0003הכי נמי מהלינן ליה\u0004 \u0005[כך גם כן\u0006 ש\u0005מלים אותו].\u0006 \u0003לא נצרכה\u0004 מה שאמרנו שאין מחללין עליו את השבת \u0003אלא ל\u0004ענין \u0003מכשירי מילה\u0004 שאין מכינים עבורו בשבת, \u0003ואליבא\u0004 \u0005[ולשיטת]\u0006 \u0003ר' אליעזר\u0004 הסבור שלצורך מילה בזמנה דוחים את השבת אפילו להכנת המכשירים.","\u0003אמר אביי:\u0004 ילד שעדיין לא שהה שלושים יום מלידתו אם כחי או כמת הוא נחשב, הרי זה \u0003כתנאי\u0004 \u0005[כתנאים],\u0006 שנחלקו בדבר זה אם נפל דינו כחי או מת, שעל הכתוב \u0003\"וכי ימות מן הבהמה אשר היא לכם לאכלה\u0004 הנוגע בנבלתה יטמא עד הערב\u0003\"\u0004 (ויקרא יא, לט) דרשו: פסוק זה בא \u0003להביא\u0004 (לרבות) עובר בהמה גסה (שיולדת כרגיל לתשעה חדשים) \u0003בן שמנה\u0004 חדשים להריון \u0003שאין שחיטתו מטהרתו\u0004 אלא דינו כנבלה. ולא רק שאסור באכילה אלא מטמא במגע ובמשא. ואילו \u0003ר' יוסי בר' יהודה ור' אלעזר בר' שמעון אומרים: שחיטתו מטהרתו,\u0004 ואינו כנבילה.","\u0003מאי לאו בהא קא מיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה נחלקו],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' יוסי בר' יהודה ור' אלעזר בר' שמעון \u0005סבור]\u0006 שעובר כזה ל\u0003חי הוא\u0004 נחשב, ולכן שחיטתו מטהרתו כדין כל בהמה טהורה. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 התנא הראשון, \u0005סבור]\u0006 של \u0003מת הוא\u0004 נחשב.","\u0003אמר רבא: אי הכי, אדמיפלגי\u0004 \u0005[אם כך, עד ש\u0006הם \u0005נחלקים]\u0006 \u0003לענין טומאה וטהרה, ליפלגי\u0004 \u0005[שיחלקו]\u0006 \u0003לענין אכילה\u0004 אם מותר לאכול ולד זה לאחר שחיטה! ומאחר ולא נחלקו בדבר זה — ראיה היא שלא דנו כלל בצד זה.","\u0003אלא\u0004 יש לדחות את ההסבר הקודם ולומר כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 ל\u0003מת הוא\u0004 נחשב, \u0003ו\u0004אולם \u0003ר' יוסי בר' יהודה ור' אלעזר בר' שמעון סברי\u0004 \u0005[סבורים]\u0006 שדינו \u0003כטרפה,\u0004 ומעתה \u0003טרפה לאו אף על גב\u0004 \u0005[האם לא אף על פי]\u0006 שלענין הלכה ל\u0003מתה היא\u0004 נחשבת, שהרי אין טריפה אלא בהמה שאין לה סיכוי לחיות עוד, ובכל זאת אם שחטוה — \u0003שחיטתה מטהרתה,\u0004 ואינה מטמאה כנבילה, אף שהיא אסורה באכילה כטריפה, \u0003הכא נמי\u0004 — \u0003לא שנא\u0004 \u0005[כאן גם כן\u0006 — \u0005אינו שונה].\u0006 \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שאינם מקבלים טענה זו אומרים: \u0003לא דמי\u0004 \u0005[אינו דומה]\u0006 \u0003לטרפה,\u0004 שכן \u0003טרפה\u0004 — \u0003היתה לה שעת הכושר,\u0004 שלפני שנפל בה אותו מום או פצע אשר הטריפה היה זמן שהיתה כשרה לגמרי, ואולם \u0003האי\u0004 \u0005[זו]\u0006 שהיא בת שמונה חדשי הריון בלבד — \u0003לא היתה לה שעת הכושר\u0004 מעולם.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 זו שהיא \u0003טרפה\u0004 כבר \u0003מבטן,\u0004 שנולדה בעלת מום \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 והלא גם היא לא היתה לה שעת הכושר? אלא אף שם \u0003איכא למימר\u0004 \u0005[יש לומר]\u0006 ולחלק: \u0003התם\u0004 \u0005[שם]\u0006 בטריפה — \u0003יש\u0004 לפחות \u0003במינה שחיטה, הכא\u0004 \u0005[כאן]\u0006 בנפל — \u0003אין במינה שחיטה,\u0004 שנפל כזה אין שום צד שיהא ראוי לשחיטה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]:\u0006 \u0003מי פליגי רבנן עליה\u0004 \u0005[האם חלוקים חכמים עליו]\u0006 על \u0003רבן שמעון בן גמליאל\u0004 הסבור כי כל בהמה שעברו שמונה יום ללידתה והיא חיה שוב אין לחשוש שהיא נפל, \u0003או לא\u0004 סבורים הם כשיטתו? \u0003אם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי \u0003פליגי\u0004 \u0005[חלוקים]\u0006 הם, אם כן האם \u0003הלכה כמותו\u0004 בענין זה, \u0003או אין הלכה כמותו?\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003עגל שנולד ביום טוב\u0004 — \u0003שוחטין אותו ביום טוב\u0004 זה, הרי שאיננו חוששים לשיטת רבן שמעון בן גמליאל, ואין ממתינים עד היום השמיני ללידתו! ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים],\u0006 \u0003דקים ליה בגוויה\u0004 \u0005[שמוחזק לנו בו]\u0006 באותו עגל \u0003שכלו לו חדשיו\u0004 ונשלם זמן הריונו ואינו ספק נפל.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה ששנינו: \u0003ושוין\u0004 ר' יהודה ור' שמעון שנחלקו בענין ההיתר לראות את מומי הבכור ביום טוב, \u0003שאם נולד\u0004 בכור \u0003הוא ומומו עמו\u0004 — \u0003שזה מן המוכן,\u0004 ואיננו אומרים שהוא מוקצה כיון שהוא בכור האסור באכילה עד שיפול בו מום ואחר יבוא חכם ויבקר וידע אם מותר לשחטו. ולענייננו — הלא רואים מכאן ששוחטים את הבכור ביום לידתו! ודוחים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003שכלו לו חדשיו\u0004 בוודאי ואינו ספק נפל.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה ממה ששנינו ש\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: הלכה\u0004 בענין זה \u0003כ\u0004שיטת \u0003רבן שמעון בן גמליאל.\u0004 ונלמד מכאן גם כי אם נפסקת \u0003הלכה\u0004 — \u0003מכלל\u0004 הדבר אתה למד \u0003דפליגי\u0004 \u0005[שנחלקו\u0006 בדבר\u0005].\u0006 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 תשובה שלימה לשתי הבעיות בענין זה.","\u0003אמר אביי:\u0004 תינוק שלא מלאו לו שלושים יום ו\u0003נפל מן הגג או אכלו ארי\u0004 — \u0003דברי הכל\u0004 תינוק זה \u0003חי הוא,\u0004 כלומר, אנו מניחים שהיה זה תינוק חי, ומת בתאונה. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה במקרה כגון \u0003שפיהק ומת.\u0004 שנשם התינוק מעט ומת מיד, \u0003מר סבר\u0004 \u0005[חכם\u0006 זה, חכמים, \u0005סברו]:\u0006 התינוק \u0003חי הוא\u0004 כיון שנולד חי. \u0003ומר סבר\u0004 \u0005[וחכם זה סבור]:\u0006 \u0003מת הוא,\u0004 עד שיעבור לפחות חודש מלידתו.","\u0003למאי נפקא מיניה\u0004 \u0005[מה יוצא מזה\u0006 להלכה\u0005]\u0006 אם התינוק נחשב כנולד או לא? — הרי זה לענין \u0003לפטור\u0004 את האם \u0003מן הייבום.\u0004 שאם נולד ילד חי — שוב אין אמו חייבת ביבום, ואולם אם מת הוא מתחילה הרי זה כאילו לא היה למת ילד כלל וחייבת אשתו ביבום.","ומקשים: וכי אפשר להניח ש\u0003נפל מן הגג או אכלו ארי\u0004 ל\u0003דברי הכל חי הוא? והא\u0004 \u0005[והרי]\u0006 \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע איקלעו לבי בריה\u0004 \u0005[הזדמנו לבית בנו]\u0006 של \u0003רב אידי בר אבין, ועביד להו עיגלא תילתא ביממא דשבעה\u0004 \u0005[ועשה להם עגל משולש ביום השביעי]\u0006 ללידתו. \u0003ואמרי ליה\u0004 \u0005[ואמרו לו\u0006\u0003]: אי איתרחיתו ליה עד לאורתא\u0004 \u0005[אם הייתם ממתינים לו עד הערב]\u0006 — \u0003הוה אכלינן מיניה\u0004 \u0005[היינו אוכלים ממנו],\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 שלא המתנת — \u0003לא אכלינן מיניה\u0004 \u0005[אין אנו אוכלים ממנו].\u0006 נמצא איפוא שעגל ששחטוהו לפני הזמן שיצא בו מכלל נפל עדיין יש לחשוש שמא נפל היה, ואם כן הוא הדין לילד שמת בתאונה!","\u0003אלא\u0004 יש לגרוס אחרת: \u0003כשפיהק ומת\u0004 ל\u0003דברי הכל\u0004 — \u0003מת הוא\u0004 מתחילתו, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה \u0003ב\u0004אופן ש\u0003נפל מן הגג ו\u0004כן ב\u0003אכלו ארי,\u0004 ש\u0003מר סבר\u0004 \u0005[חכם זה\u0006, רבן שמעון בן גמליאל \u0005סבור]:\u0006 \u0003מת הוא, ומר סבר\u0004 \u0005[וחכם זה\u0006 סבור] כי כיון שלא מת מעצמו \u0003חי הוא.\u0004","מסופר: \u0003בריה\u0004 \u0005[בנו]\u0006 של \u0003רב דימי בר יוסף אתיליד ליה ההוא ינוקא\u0004 \u0005[נולד לו תינוק אחד].\u0006 \u0003בגו תלתין יומין שכיב\u0004 \u0005[בתוך שלושים יום מת]\u0006 אותו תינוק. \u0003יתיב קמתאביל עילויה\u0004 \u0005[ישב\u0006 ו\u0005היה מתאבל עליו].\u0006 \u0003אמר ליה אבוה\u0004 \u0005[לו אביו]\u0006 רב דימי בר יוסף: האם \u0003צוורוניתא קבעית למיכל\u0004 \u0005[מטעמים שמאכילים אבלים רוצה אתה לאכול]?\u0006 והלא הלכה היא שילד שמת לפני שלושים דינו כנפל, ואין מתאבלים עליו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קים לי ביה\u0004 \u0005[מוחזק לי בו]\u0006 \u0003שכלו לו חדשיו.\u0004","ובדומה לזה מסופר ש\u0003רב אשי איקלע בי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב כהנא. איתרע ביה מילתא בגו תלתין יומין\u0004 \u0005[אירע בו דבר\u0006 על תינוק שמת \u0005בתוך שלושים יום].\u0006 \u0003חזייה דיתיב וקא מתאבל עילויה\u0004 \u0005[ראהו שיושב ומתאבל עליו]\u0006 על אותו תינוק. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 וכי \u0003לא סבר ליה מר להא\u0004 \u0005[אין אדוני סבור את\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: הלכה כרבן שמעון בן גמליאל\u0004 שרק זה שעברו עליו שלושים יום ללידתו אינו נפל? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קים לי בגויה\u0004 \u0005[מוחזק לי בו]\u0006 \u0003שכלו לו חדשיו\u0004 ואינו נפל.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שדנו חכמים בשאלה: מה קורה כאשר \u0003מת\u0004 תינוק \u0003בתוך שלשים\u0004 יום ללידתו ונמצאת אמו אלמנה ללא ילדים, \u0003ו\u0004לפני שהספיקו לדון אם חייבת היא ביבום \u0003עמדה ונתקדשה\u0004 לאחר. \u0003אמר רבינא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא:\u0004"],["\u0003אם אשת ישראל היא,\u0004 שנתקדשה עכשיו לישראל, מאחר וישראל מותר בחלוצה — \u0003חולצת\u0004 מספק, שמא היה זה נפל והריהו כמת מתחילתו, ונמצא שהיא זקוקה עדיין ליבום, ועל ידי החליצה אנו יוצאים ידי חובת כל ספק שיש בדבר, ותשב עם בעלה. ו\u0003אם אשת כהן היא\u0004 — \u0003אינה חולצת,\u0004 שאם תחלוץ תהא אסורה לבעלה הכהן, וכיון שיש אומרים שתינוק שנולד חי דינו כחי מרגע היוולדו — סומכים בדיעבד על שיטתם ואין מחייבים אותה לחלוץ.","\u0003ו\u0004אילו \u0003רב שרביא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר: אחת זו ואחת זו\u0004 — \u0003חולצת,\u0004 שחמור האיסור בנשיאת יבמה שלא הותרה מקשר הזיקה ליבום ואין מתחשבים בבעלה הכהן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב שרביא: באורתא\u0004 \u0005[בערב]\u0006 \u0003אמר רבא הכי\u0004 \u0005[כך],\u0006 כפי שאתה אומר, ואולם \u0003לצפרא הדר ביה\u0004 \u0005[בבוקר חזר בו],\u0006 ואני שמעתי את דבריו המתוקנים. אולם רב שרביא לא קבל הסבר זה, ואמר: \u0003שריתוה\u0004 \u0005[התרתם אותה]\u0006 לאותה אשת כהן אף בלא חליצה? והלא כל עוד אינו בן שלושים יום הריהו נחשב כנפל לדעת רבן שמעון בן גמליאל, ומאחר ועברתם על דבריו, \u0003יהא רעוא דתשרו תרבא\u0004 \u0005[יהי רצון ש\u0006תמשיכו בדרך זו ו\u0005תתירו\u0006 לאכול \u0005חלב].\u0006","שנינו במשנה ש\u0003ר' יהודה מתיר\u0004 למול אנדרוגינוס בשבת. \u0003אמר רב שיזבי\u0004 שכך \u0003אמר רב חסדא: לא לכל\u0004 דבר \u0003אמר ר' יהודה\u0004 ש\u0003אנדרוגינוס זכר הוא\u0004 אלא לדין מילה בלבד, \u0003שאם אתה אומר כן\u0004 שדינו כזכר לכל דבר, אם כן אף \u0003בערכין\u0004 שמקדישין בני אדם \u0003יערך!\u0004","\u0003ומנלן דלא מיערך\u0004 \u0005[ומנין לנו שאינו מוערך]\u0006 בערכין? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 בספרא (מדרש ההלכה על ספר \"ויקרא\") על הכתוב \"והיה ערכך \u0003הזכר\u0004 מבן עשרים שנה ועד בן ששים שנה והיה ערכך חמישים שקל כסף בשקל הקודש\" (ויקרא כז, ג), ודקדקו חכמים: \"הזכר\" — הוודאי ולא \u0003טומטום ואנדרוגינוס. יכול לא יהא\u0004 אחד מאלה נערך \u0003בערך איש, אבל יהא בערך אשה\u0004 — \u0003תלמוד לומר\u0004 מצד אחד \u0003\"הזכר\",\u0004 ובפסוק אחר \u0003\"ואם נקבה היא\u0004 והיה ערכך שלושים שקל\u0003\"\u0004 (ויקרא כז, ד), ומשמע: \u0003זכר ודאי, נקבה ודאית, ולא טומטום ואנדרוגינוס,\u0004 שאינם לא בגדר זכר ולא בגדר נקבה."],["\u0003וסתם\u0004 הלכה המובאת ב\u0003ספרא\u0004 בלא שם אומרה כרגיל מפי \u0003ר' יהודה\u0004 נאמרה.","\u0003אמר רב נחמן בר יצחק: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 הוכחה שאין ר' יהודה סבור שאנדרוגינוס דינו לכל דבר כזכר, שנחלקו חכמים בענין קידוש מי חטאת, כלומר, מתן אפר הפרה האדומה בתוך מים חיים (מים מעין), שאמרו: \u0003הכל כשרים לקדש, חוץ מחרש שוטה וקטן. ר' יהודה מכשיר בקטן ופוסל באשה ואנדרוגינוס,\u0004 נמצא שאין ר' יהודה סבור שאנדרוגינוס דינו כזכר. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה\u0006 כן\u0005].\u0006","ושואלים: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003מילה\u0004 שר' יהודה מרבה לגביה אנדרוגינוס כזכר? \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004זאת בריתי אשר תשמרו ביני וביניכם ובין זרעך אחריך \u0003המול לכם כל זכר\"\u0004 (בראשית יז, י), והוא מפרש: \"כל זכר\" — כל שניתן לכלול אותו בוודאות במושג \"זכר\".","\u0003מי שהיו לו שני תינוקות\u0004 שהוא צריך למול אותם, \u0003אחד\u0004 שצריך \u0003למול\u0004 ביום ראשון \u0003אחר השבת, ואחד למול בשבת, ושכח, ומל את של אחר השבת בשבת\u0004 — \u0003חייב\u0004 קרבן חטאת, משום שעשה מלאכה (פציעה) בלי לעשות מצוה, שהרי אין עדיין הילד חייב במילה.","ואם היו לו שני תינוקות \u0003אחד למול בערב שבת, ואחד למול בשבת, ושכח ומל את של ערב שבת בשבת\u0004 — \u0003ר' אליעזר מחייב חטאת,\u0004 שכן מילה לאחר זמנה אינה דוחה את השבת, \u0003ור' יהושע פוטר,\u0004 כיון שהתכוון אותו אדם לעשות מצוה ואם אמנם שגה בדבר אבל בכל זאת עשה מצוה — פטור הוא אף מלהביא קרבן.","בגרסתה של משנתינו נחלקו אמוראים, בהתאם למחלוקת תנאים קדומה, \u0003רב הונא מתני\u0004 \u0005[שונה]\u0006 בחלקה הראשון של המשנה \u0003\"חייב\",\u0004 ואילו \u0003רב יהודה מתני\u0004 \u0005[שונה]\u0006 בחלקה הראשון \u0003\"פטור\".\u0004","ומפרטים: \u0003רב הונא מתני\u0004 \u0005[שונה]\u0006 \u0003\"חייב\",\u0004 וסמך דבריו על זה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' שמעון בן אלעזר: לא נחלקו ר' אלעזר ור' יהושע על מי שהיו לו שני תינוקות, אחד למול בשבת ואחד למול אחר השבת, ושכח ומל את של אחר השבת בשבת\u0004 — \u0003ש\u0004לדעת הכל \u0003הוא חייב\u0004 חטאת.","\u0003על מה נחלקו\u0004 — \u0003על מי שהיו לו שני תינוקות, אחד למול בערב שבת ואחד בשבת, ושכח ומל את של ערב שבת בשבת. שר' אליעזר מחייב חטאת\u0004 על שגגה זו \u0003ור' יהושע פוטר.\u0004","\u0003ושניהם לא למדוה אלא מעבודה זרה\u0004 שבה פירש הכתוב דין הבאת קרבן חטאת על שגגה. \u0003ר' אליעזר סבר\u0004 \u0005[סבור]:\u0006 דין כל שגגה \u0003כעבודה זרה, מה עבודה זרה אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"לא תעביד\u0004 \u0005[תעשה]\u0006 \u0003\", וכי עביד\u0004 \u0005[וכאשר עושה,\u0006 עובד עבודה זרה בשגגה\u0005]\u0006 — הריהו \u0003מיחייב\u0004 \u0005[חייב\u0006 חטאת\u0005],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 — \u0003לא שנא\u0004 \u0005[אינו שונה],\u0006 וכיון שעבר על מה שאסרה התורה חייב להביא קרבן חטאת.","\u0003ור' יהושע, התם\u0004 \u0005[שם]\u0006 — \u0003דלאו\u0004 \u0005[שלא]\u0006 היתה השגגה לשם עשיית \u0003מצוה,\u0004 ולכן אם עבר בשוגג הריהו חייב חטאת, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 — הרי כל רצונו היה בעשיית \u0003מצוה,\u0004 והטועה בדבר מצוה ושגג ועבר תוך כדי כך — אפילו קרבן חטאת אינו מביא. כל זה לשיטת רב הונא כדברי ר' שמעון בן אלעזר.","\u0003רב יהודה מתני\u0004 \u0005[שונה]\u0006 במשנתנו \u0003\"פטור\",\u0004 ומסתמך על זה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' מאיר: לא נחלקו ר' אליעזר ור' יהושע על מי שהיו לו שני תינוקות\u0004 שהיה צורך למול אותם, \u0003אחד למול בערב שבת ואחד בשבת, ושכח ומל את של ערב שבת בשבת\u0004 — \u0003ש\u0004לדעת הכל \u0003הוא פטור\u0004 מחטאת, כיון שעשה מצוה במילה זו.","\u0003על מה נחלקו\u0004 — \u0003על מי שהיו לו שני תינוקות, אחד למול אחר השבת ואחד למול בשבת, ושכח ומל את של אחר השבת בשבת, שר' אליעזר מחייב חטאת, ור' יהושע פוטר.\u0004","\u0003ו\u0004מעירים: \u0003ו\u0004אף כאן \u0003שניהם לא למדוה אלא מעבודה זרה. ר' אליעזר סבר\u0004 \u0005[סבור]:\u0006 דין כל שגגה \u0003כעבודה זרה, מה עבודה זרה אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"לא תעביד\u0004 \u0005[תעשה]\u0006 \u0003\", וכי עביד\u0004 \u0005[וכאשר עושה,\u0006 עובד עבודה זרה בשגגה\u0005]\u0006 — הריהו \u0003מיחייב\u0004 \u0005[חייב\u0006 חטאת\u0005],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 — \u0003לא שנא\u0004 \u0005[אינו שונה],\u0006 וכיון שעבר על מה שאסרה התורה חייב להביא קרבן חטאת.","\u0003ור' יהושע\u0004 אומר: \u0003התם\u0004 \u0005[שם\u0006 בעבודה זרה\u0005]\u0006 — \u0003לא טריד\u0004 \u0005[אינו טרוד]\u0006 בעשיית \u0003מצוה,\u0004 ולכן כשעבר הריהו חייב חטאת, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 — הריהו \u0003טריד\u0004 \u0005[טרוד]\u0006 בעשיית \u0003מצוה,\u0004 וכל המתעסק במצוה וטרוד בה, אם שגג ועבר — אינו חייב חטאת.","גירסה נוספת של אותה המחלוקת \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא,\u0004 שלדעתו \u0003אומר היה ר' מאיר: לא נחלקו ר' אליעזר ור' יהושע על מי שהיו לו שני תינוקות, אחד למול בערב שבת ואחד בשבת, ושכח ומל את של ערב שבת בשבת\u0004 — \u0003ש\u0004לדעת הכל \u0003הוא חייב\u0004 חטאת.","\u0003על מה נחלקו\u0004 — \u0003על מי שהיו לו\u0004 למול \u0003שני תינוקות, אחד למול אחר השבת ואחד בשבת, ושכח ומל של אחר השבת בשבת, שר' אליעזר מחייב חטאת ור' יהושע פוטר.\u0004","על גירסה אחרונה זו תוהים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 שיודעים אנו ש\u0003ר' יהושע סיפא דלא קא עביד\u0004 \u0005[בסוף,\u0006 במקרה \u0005שאינו עושה]\u0006 \u0003מצוה\u0004 — \u0003פוטר\u0004 הוא, \u0003רישא, דקא עביד\u0004 \u0005[בתחילה, שהוא עושה]\u0006 \u0003מצוה\u0004 — \u0003מחייב\u0004 \u0005[מתחייב\u0006 הוא\u0005]?!\u0006","\u0003אמרי דבי\u0004 \u0005[אמרו\u0006 בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: רישא\u0004 \u0005[התחלת\u0006 הברייתא\u0005]\u0006 במקרה מיוחד היא, \u0003כגון שקדם\u0004 המוהל בטעות \u0003ומל\u0004 את התינוק \u0003של\u0004 (מילת) \u0003שבת, בערב שבת,\u0004 שכיון שכך כבר \u0003לא ניתנה שבת לידחות,\u0004 שהרי התינוק שצריך היה למולו בשבת כבר נימול, ואין לו עוד היתר למול בשבת. ואילו במקרה האחר ב\u0003סיפא\u0004 \u0005[\u0006ב\u0005סוף]\u0006 היה זה באופן שעדיין \u0003ניתנה שבת לידחות.\u0004","על הסבר זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא\u0004 בקושיה: \u0003רישא נמי\u0004 \u0005[בתחילה גם כן]\u0006 \u0003ניתנה שבת לידחות לגבי\u0004 \u0005[אצל]\u0006 \u0003תינוקות דעלמא\u0004 \u0005[בכלל],\u0006 שהגיע זמן מילתם בשבת! והשיב לו: אמנם כן הוא, ואולם \u0003להאי גברא מיהא\u0004 \u0005[לאדם זה לפחות]\u0006 \u0003לא איתיהיב\u0004 \u0005[ניתנה]\u0006 רשות, שהרי עליו לא היתה עוד כל חובה למול ילד בשבת, ואם שגג ועשה זאת — אין אנו אומרים ששגג בשעת טרדת מצוה.","אף שבדרך כלל \u0003קטן נימול לשמנה\u0004 ימים, וכאמור: \"וביום השמיני ימול בשר ערלתו\" (ויקרא יב, ג), מכל מקום לפעמים הוא נימול \u0003לתשעה, ו\u0004לפעמים \u0003לעשרה\u0004 ימים, \u0003ולאחד עשר ולשנים עשר, לא פחות ולא יותר.\u0004","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד?\u0004 — \u0003כדרכו\u0004 כרגיל נימול \u0003לשמנה.\u0004 ואם \u0003נולד לבין השמשות\u0004 ואין יודעים באיזה יום נולד — \u0003נימול לתשעה,\u0004 שמתוך הספק מאחרים את מילתו, שמא עדיין לא הגיע היום השמיני. ואם הגיע זמן מילתו להיות \u0003בין השמשות של ערב שבת\u0004 — אין מלים אותו בשבת, שהרי מילה זו מספק הוא, ואין מילת ספק דוחה את השבת, אלא מלים ביום ראשון ונמצא ש\u0003נימול לעשרה.\u0004","ואם היה \u0003יום טוב לאחר\u0004 אותה \u0003השבת\u0004 — אין מלים אותו אף ביום טוב, אלא \u0003נימול לאחד עשר.\u0004 ואם היו לאחר השבת \u0003שני ימים של ראש השנה\u0004 — נמצא ש\u0003נימול לשנים עשר\u0004 יום.","הלכה אחרת אמרו: \u0003קטן החולה\u0004 — \u0003אין מוהלין אותו, עד שיבריא\u0004 כל צרכו.","שנינו במשנה שתינוק חולה אין מלים אותו עד שיחלים כל צרכו. ובענין זה \u0003אמר שמואל:\u0004 תינוק שהיה חולה והיה לו חום גבוה ואחר כך \u0003חלצתו חמה\u0004 (עזב אותו החום) — \u0003נותנין לו כל שבעה\u0004 ימים לאחר מכן \u0003להברותו\u0004 (להבריאו).","בענין זה \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003מי בעינן\u0004 \u0005[האם צריכים אנו]\u0006 בהמתנה נוספת זו לחכות \u0003מעת לעת,\u0004 כלומר, שבע יממות שלמות, או די בשבעה ימים בלא להקפיד על חשבון הזמנים המדוייק?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 החכם \u0003לודא: יום הבראתו כיום הולדו. מאי לאו\u0004 \u0005[האם לא\u0006 נפרש\u0005]:\u0006 \u0003מה יום הולדו\u0004 — \u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 להמתין למולו בדיוק שמונה ימים לרגע הולדו \u0003מעת לעת\u0004 — \u0003אף יום הבראתו לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 להמתין \u0003מעת לעת.\u0004","ודוחים: \u0003לא, עדיף יום הבראתו מיום הולדו,\u0004 ש\u0003אילו\u0004 מ\u0003יום הולדו\u0004 — \u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 להמתין ממש \u0003מעת לעת, ואילו\u0004 מ\u0003יום הבראתו\u0004 — \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 למנות שבעה ימים שלמים \u0003מעת לעת.\u0004","\u0003אלו הן ציצין\u0004 (חתיכות בשר) \u0003המעכבין את המילה\u0004 אם לא הסירום. עיקרו של דבר שיש למול \u0003בשר החופה את רוב העטרה,\u0004 ותינוק שלא נימול כך — דינו כערל, \u0003ואינו אוכל בתרומה.\u0004","\u0003ואם\u0004 נימול כראוי אלא ש\u0003היה בעל בשר\u0004 ונראה כאילו לא נימול כל צרכו — \u0003מתקנו\u0004 ומל יותר מן השיעור, \u0003מפני מראית העין,\u0004 שלא יראה כערל."],["\u0003מל ולא פרע\u0004 (גילה) את העור החופה \u0003את המילה\u0004 — \u0003כאילו לא מל.\u0004 \u0003אמר ר' אבינא\u0004 שכך \u0003אמר ר' ירמיה בר אבא\u0004 שכך \u0003אמר רב:\u0004 \"רוב עטרה\" שאמרו, כוונתו: \u0003בשר החופה את רוב גובהה של עטרה,\u0004 וגם צריך למול רוב הקיפה. \u0003ו\u0004עוד שנינו במשנה ש\u0003אם היה\u0004 התינוק \u0003בעל בשר\u0004 — מתקנים את מילתו שלא יראה כערל. \u0003אמר שמואל: קטן המסורבל בבשר, רואין אותו, כל זמן שמתקשה\u0004 איברו \u0003ו\u0004באותה שעה \u0003נראה מהול\u0004 — \u0003אינו צריך למול\u0004 אותו שוב, \u0003ואם לאו\u0004 \u0005[לא],\u0006 שאף אז נראה כערל — \u0003צריך למול.\u0004","","","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנו],\u0006 \u0003רבן שמעון בן גמליאל אומר: קטן המסורבל בבשר, רואין אותו, כל זמן שמתקשה ואינו נראה מהול\u0004 — \u0003צריך למולו, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינו צריך למולו.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל המעשי \u0005ביניהם]\u0006 בין שני הניסוחים? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה, אם היה \u0003נראה ו\u0004אולם \u0003אינו נראה\u0004 כל הצורך, שלדעת שמואל חייב להיראות מהול, ולדעת רבן שמעון בן גמליאל רק מי שנראה שהוא ערל צריך להימול שנית.","שנינו במשנה שאם \u0003מל ולא פרע\u0004 את החופה את המילה — כאילו לא מל. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא, \u0003המל\u0004 את התינוק \u0003אומר: \"אשר קדשנו במצותיו וצונו על המילה\"\u0004 ו\u0003אבי הבן אומר: \"אשר קדשנו במצותיו וצונו להכניסו בבריתו של אברהם אבינו\"\u0004 ו\u0003העומדים\u0004 שם \u0003אומרים: \"כשם שנכנס לברית, כך יכנס לתורה לחופה ולמעשים טובים\".\u0004","\u0003והמברך אומר\u0004 ברכה נוספה זו: \u0003\"אשר קידש ידיד מבטן, חוק בשארו\u0004 (בבשרו) \u0003שם, וצאצאיו חתם באות ברית קדש. על כן בשכר זאת אל חי חלקנו, צוה להציל ידידות שארינו\u0004 (בשרנו) \u0003משחת\u0004 (גיהנום) \u0003למען בריתו אשר שם בבשרנו. ברוך אתה ה' כורת הברית\".\u0004","\u0003המל את הגרים אומר: \"ברוך אתה ה' אלהינו מלך העולם אשר קדשנו במצותיו וצונו על המילה\", והמברך אומר: \"אשר קדשנו במצותיו וצונו למול את הגרים ולהטיף מהם דם ברית, שאילמלא דם ברית לא נתקיימו שמים וארץ, שנאמר: 'אם לא בריתי יומם ולילה חקות שמים וארץ לא שמתי'\"\u0004 (ירמיהו לג, כה), (ומפרשים שאילולי ברית זו, ברית המילה, המתקיימת גם ביום וגם בלילה לא היה קיום לעולם) \u0003ברוך אתה ה' כורת הברית\".\u0004","\u0003המל את העבדים,\u0004 שכאשר אדם קונה עבד כנעני הריהו חייב למולו כדי להכניסו באופן חלקי בברית ישראל, ובאותה שעה המל \u0003אומר: \"אשר קדשנו במצותיו וציונו על המילה\", והמברך אומר: \"אשר קדשנו במצותיו וצונו למול את העבדים ולהטיף מהם דם ברית, שאילמלא דם ברית חקות שמים וארץ לא נתקיימו, שנאמר: \"אם לא בריתי יומם ולילה חקות שמים וארץ לא שמתי\" ברוך אתה ה' כורת הברית\".\u0004 וכן אומרים בשינוי מסוים מעין ברכות אלה בשעה שמלים עבד כנעני ומכניסים אותו באופן חלקי בברית ישראל. \u0003ר' אליעזר אומר: תולין\u0004 ומותחים את \u0003המשמרת\u0004 שמסננים בה את היין מן השמרים \u0003ביום טוב,\u0004 ובשבת אין תולים \u0003ו\u0004אולם \u0003נותנין\u0004 יין \u0003ל\u0004משמרת ה\u0003תלויה\u0004 מבעוד יום \u0003בשבת. וחכמים אומרים: אין תולין את המשמרת ביום טוב, ואין נותנין\u0004 יין לסינון \u0003לתלויה בשבת, אבל נותנין לתלויה ביום טוב.\u0004","","","על שיטת ר' אליעזר תוהים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ר' אליעזר\u0004 סבור כי אף \u0003אוסופי\u0004 \u0005[להוסיף]\u0006 על \u0003אהל עראי לא מוספינן\u0004 \u0005[אין אנו מוסיפים]\u0006 בשבת, וכי \u0003למיעבד\u0004 \u0005[לעשות]\u0006 כך \u0003לכתחלה שרי\u0004 \u0005[יתיר]?!\u0006 והרי תליית המשמרת היא כעין יצירת אוהל!","ומסבירים את השאלה, \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 שיטת ר' אליעזר זו — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003פקק החלון\u0004 שמכסים בו חלונות שבארובת הגג, \u0003ר' אליעזר אומר: בזמן שקשור\u0004 לחלון \u0003ותלוי\u0004 — \u0003פוקקין בו\u0004 בשבת, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין פוקקין בו. וחכמים אומרים: בין כך ובין כך,\u0004 בין שהוא קשור ולתלוי בחלון ובין לא — \u0003פוקקין בו.\u0004","\u0003ואמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: הכל מודים שאין עושין אהל עראי בתחלה ביום טוב, ואין צריך לומר\u0004 שאסור לעשותו \u0003בשבת. לא נחלקו אלא\u0004 האם מותר \u0003להוסיף\u0004 על אוהל כזה שהוא כבר קיים, \u0003שר' אליעזר אומר: אין מוסיפין\u0004 עליו \u0003ביום טוב, ואין צריך לומר\u0004 שאין מוסיפים \u0003בשבת,\u0004 ולדעתו הנחת פקק וכיסוי על החלון כמוה כהוספה על אוהל. \u0003וחכמים אומרים: מוסיפין בשבת, ואין צריך לומר\u0004 שמוסיפים \u0003ביום טוב.\u0004 ואם כן, כיצד מתיר ר' אליעזר לתלות את המשמרת ביום טוב? ומשיבים: אמנם סבור ר' אליעזר שתליית המשמרת יש בה משום מלאכה, ואולם \u0003ר' אליעזר סבר לה\u0004 \u0005[סבור הוא]\u0006 בענין זה \u0003כ\u0004שיטת \u0003ר' יהודה\u0004 לענין הכנת מכשירי אוכל ביום טוב. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין\u0004 הבדל \u0003בין יום טוב לשבת\u0004 לענין איסור עשיית מלאכה \u0003אלא\u0004 לענין היתר עשייית \u0003אוכל נפש בלבד,\u0004 שמותר לעשות מלאכה ביום טוב כדי להכין אוכל הדרוש ליום טוב, מה שאין כן בשבת. \u0003ר' יהודה מתיר\u0004 לעשות ביום טוב \u0003אף מכשירי אוכל נפש,\u0004 כגון תיקון כלי עבודה שעל ידם יעשו אוכל לחג. וכמו כן מתיר ר' אליעזר לעשות מלאכה ולתלות את המשמרת כדי להכין יין לצורך יום טוב.","","ושואלים: \u0003אימר דשמעינן ליה\u0004 \u0005[אמור ששמענו אותו]\u0006 את \u0003ר' יהודה\u0004 שמתיר לעשות ביום טוב מכשירי אוכל נפש דווקא \u0003ב\u0004אותם \u0003מכשירין שאי אפשר לעשותם מערב יום טוב,\u0004 ואולם \u0003במכשירין שאפשר לעשותם מערב יום טוב מי\u0004 \u0005[האם]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]\u0006 שהתיר?! ומשיבים: ההיתר של \u0003ר' אליעזר עדיפא\u0004 \u0005[עדיף]\u0006 \u0003מ\u0004זה של \u0003ר' יהודה,\u0004 שר' אליעזר אינו מחלק ומתיר כל מכשירי אוכל נפש בכל מקרה, ואף אלו שאפשר היה להכינם מערב יום טוב. שנינו במשנה ש\u0003חכמים אומרים\u0004 שאין תולים את המשמרת אף ביום טוב. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 אם \u0003תלה\u0004 את המשמרת בשוגג \u0003מאי\u0004 \u0005[מה]\u0006 דינו? \u0003אמר רב יוסף:\u0004 אם \u0003תלה\u0004 — \u0003חייב חטאת,\u0004 ככל עושה בשבת מלאכה האסורה מן התורה בשוגג. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה,\u0004 אם סבור אתה שדבר כעין זה קרוי בנין, ואסור, אם \u0003תלא כוזא בסיכתא הכי נמי דמיחייב\u0004 \u0005[תלה כד ביתד, כך גם כן שיתחייב]\u0006 משום עושה אוהל?!","","",""],["\u0003אלא אמר אביי:\u0004 הלכה זו \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003היא\u0004 וגזרו כך כדי \u0003שלא יעשה\u0004 בשבת ויום טוב \u0003כדרך שהוא עושה בחול.\u0004","\u0003מנקיט\u0004 \u0005[היה מלקט]\u0006 \u0003אביי\u0004 את \u0003חומרי מתניתא\u0004 \u0005[כללי הברייתות]\u0006 בענין עשיית אהל \u0003בשבת, ותני\u0004 \u0005[והיה שונה]:\u0006 \u0003הגוד\u0004 (כעין נאד גדול), \u0003והמשמרת\u0004 של יין, \u0003כילה\u0004 שעל גבי מטה, \u0003וכסא גלין\u0004 (כסא מתקפל שכיסויו נפרד מרגליו) \u0003לא יעשה\u0004 (ירכיב אותם) משום איסור יצירת אוהל עראי. \u0003ואם עשה\u0004 כן בשוגג — \u0003פטור\u0004 מדין תורה ואינו חייב להביא חטאת, \u0003אבל אסור\u0004 מדברי חכמים. \u0003אהלי קבע\u0004 — \u0003לא יעשה, ואם עשה\u0004 — \u0003חייב חטאת,\u0004 משום בונה. \u0003אבל מטה וכסא טרסקל\u0004 (כסא מתקפל שכיסויו צמוד לרגליו), \u0003ואסלא\u0004 של בית הכסא שהיא מתקפלת \u0003מותר לנטותן\u0004 (לפרשם) \u0003לכתחילה,\u0004 כיון שהם מוכנים מבעוד יום.","שנינו במשנה ש\u0003אין נותנין\u0004 יין לסינון אף \u0003ל\u0004משמרת ה\u0003תלויה\u0004 מכבר \u0003בשבת. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 אם \u0003שימר\u0004 נתן את היין לסינון בשוגג \u0003מאי\u0004 \u0005[מה]\u0006 דינו? \u0003אמר רב כהנא:\u0004 אם \u0003שימר\u0004 — \u0003חייב\u0004 קרבן \u0003חטאת.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ששת: מי איכא מידי דרבנן מחייבי\u0004 \u0005[האם יש דבר שחכמים מחייבים]\u0006 על עשייתו קרבן \u0003חטאת, ו\u0004אילו \u0003ר' אליעזר שרי\u0004 \u0005[מתיר]\u0006 את עשייתו \u0003לכתחילה?!\u0004 שאין אנו מוצאים חילוקי דעות קיצוניים כל כך במשנה אחת!","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על קושיה זו \u0003רב יוסף: אלמה\u0004 \u0005[מדוע]\u0006 \u0003לא?\u0004 ו\u0003הרי\u0004 יש מחלוקת כעין זו בענין הוצאת תכשיט הקרוי \u0003עיר של זהב\u0004 מרשות אחת לרשות אחרת על ידי אשה בשבת, ש\u0003ר' מאיר מחייב חטאת\u0004 את המוציאה, \u0003ור' אליעזר שרי\u0004 \u0005[מתיר]\u0006 להוציאו אף מ\u0003לכתחילה.\u0004","\u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 מחלוקת זו — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא תצא אשה\u0004 בשבת בתכשיט הקרוי \u0003עיר של זהב, ואם יצאה\u0004 — \u0003חייבת חטאת,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים:\u0004 מלכתחילה \u0003לא תצא, ו\u0004אולם \u0003אם יצאה\u0004 — \u0003פטורה\u0004 מחטאת. \u0003ר' אליעזר אומר: יוצאה\u0004 (יוצאת) \u0003אשה בעיר של זהב\u0004 אף מ\u0003לכתחילה.\u0004 הרי שמצאנו חילוקי דעות בין חכם המחייב מן התורה ואחר המתיר לחלוטין!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי \u0003ר' אליעזר\u0004 על \u0003ר' מאיר קאי\u0004 \u0005[עומד,\u0006 מתייחס\u0005],\u0006 שר' מאיר \u0003אמר\u0004 שהיא \u0003חייבת חטאת?\u0004 לא כי, אלא \u0003אדרבנן קאי, דאמרי\u0004 \u0005[לדברי חכמים\u0006 הוא \u0005עומד,\u0006 מתייחס, \u0005ש\u0006הם \u0005אומרים]\u0006 \u0003פטור אבל אסור, ואמר להו איהו\u0004 \u0005[להם הוא]\u0006 שלדעתו \u0003מותר לכתחילה.\u0004 אבל אם לא היתה דעה ממוצעת לא היתה אפשרית מחלוקת כזו מקצה לקצה.","ולמעשה שואלים על ההלכה: \"משמר\" זה \u0003משום מאי\u0004 \u0005[מה],\u0006 איזה אב מלאכה \u0003מתרינן ביה\u0004 \u0005[מתרים אנו בו]?\u0006 \u0003רבה אמר: משום\u0004 מלאכת \u0003בורר,\u0004 שהרי הוא מברר את היין מן השמרים. \u0003ר' זירא אמר: משום\u0004 מלאכת \u0003מרקד\u0004 (מסנן קמח בנפה), שאף היא סוג מסויים של ברירה.","\u0003אמר רבה: כוותי דידי מסתברא\u0004 \u0005[כשיטתי שלי מסתבר],\u0006 שכן \u0003מה דרכו של בורר\u0004 — שהוא \u0003נוטל\u0004 את ה\u0003אוכל ומניח את הפסולת, אף הכא נמי\u0004 \u0005[כאן\u0006 ביין \u0005גם כן]\u0006 \u0003נוטל את האוכל ומניח את הפסולת.\u0004","\u0003אמר ר' זירא: כוותי דידי מסתברא\u0004 \u0005[כשיטתי שלי מסתבר]\u0006 שאין כאן ברירה סתם, אלא סוג מסויים של ברירה: \u0003מה דרכו של מרקד\u0004 שלבסוף ה\u0003פסולת\u0004 נשארת \u0003מלמעלה\u0004 בנפה \u0003ואוכל מלמטה, אף הכא נמי\u0004 \u0005[כאן\u0006 ביין \u0005גם כן]\u0006 ה\u0003פסולת\u0004 נשארת \u0003מלמעלה ואוכל\u0004 (כלומר, יין) \u0003מלמטה.\u0004","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רמי בר יחזקאל: טלית כפולה לא יעשה\u0004 אדם בשבת, שאסור לאדם לשטוח טלית על חבל ולנטותה לצדדים שתהווה כעין כילה לשכב מתחתיה (גאונים, רי\"ף), \u0003ואם עשה\u0004 כן — \u0003פטור\u0004 מדין תורה ואינו חייב חטאת, \u0003אבל אסור\u0004 מדברי חכמים. ואם \u0003היה כרוך עליה חוט או משיחה\u0004 והיתה הטלית מונחת על החבל כשהיא מכווצת \u0003מותר לנטותה\u0004 ולפרשה \u0003לכתחילה.\u0004","ובענין דומה במקצת \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב כהנא מרב: כילה מהו\u0004 דינה, האם מותר לנטותה בשבת? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אף מטה אסורה.\u0004 ושאל: \u0003מטה מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אף כילה מותרת.\u0004 וחזר ושאל: \u0003כילה ומטה מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כילה אסורה ומטה מותרת.\u0004","ומעירים: \u0003ולא קשיא\u0004 \u0005[ואינו קשה]\u0006 שבאמת אין התשובות סותרות זו את זו. אלא, \u0003הא דקאמר\u0004 \u0005[זה שאמר]\u0006 \u0003אף מטה אסורה\u0004 — הרי הוא \u0003כדקרמנאי\u0004 (כעין המטות המתקפלות שעושים בני אותו מקום), שפרישתה הריהי יצירת אהל. \u0003הא דקאמר ליה\u0004 \u0005[זה שאמר לו]\u0006 \u0003אף כילה מותרת\u0004 — הרי זה באופן שהסביר \u0003רמי בר יחזקאל,\u0004 שהיה כרוך עליה חוט מבעוד יום. ומה שאמר \u0003כילה אסורה ומטה מותרת\u0004 — הרי הוא \u0003כדדידן\u0004 \u0005[כמו שלנו],\u0006 שהמטה אין בה קיפול ולא שייכת בה בניה, ובכילה יש מעין יצירת אוהל.","\u0003אמר רב יוסף: חזינא להו לכילי דבי\u0004 \u0005[ראיתי אותן את הכילות של בית]\u0006 \u0003רב הונא דמאורתא נגידו ומצפרא חביטא רמיא\u0004 \u0005[שמהערב היו פרושות ובבוקר היו מושלכות ומוטלות],\u0006 הרי שמותר לפרקן ואף לפורשן בשבת.","\u0003אמר רב משום\u0004 (בשם) \u0003ר' חייא: וילון מותר לנטותו ומותר לפורקו\u0004 בשבת, שמכיון שאין בו גג אין בו איסור עשיית אוהל.","\u0003ואמר שמואל משום ר' חייא\u0004"],["\u0003כילת חתנים\u0004 שאין לה גג מלמעלה אלא כולה משופעת \u0003מותר לנטותה ומותר לפורקה\u0004 בשבת.","\u0003אמר רב ששת בריה\u0004 \u0005בנו\u0006 של \u0003רב אידי: לא אמרן\u0004 \u0005[אמרנו]\u0006 כך \u0003אלא\u0004 כ\u0003שאין בגגה\u0004 רוחב \u0003טפח, אבל\u0004 אם \u0003יש בגגה טפח\u0004 — \u0003אסורה.\u0004 ועוד: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003אין בגגה טפח נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שמותר \u0003אלא שאין בפחות משלשה\u0004 טפחים \u0003סמוך לגגה\u0004 רוחב \u0003טפח, אבל\u0004 אם \u0003יש בפחות משלשה\u0004 טפחים \u0003סמוך לגגה\u0004 רוחב \u0003טפח\u0004 — \u0003אסור. ו\u0004כן \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 היתר זה \u0003אלא\u0004 כ\u0003שאין בשיפועה\u0004 רוחב \u0003טפח, אבל\u0004 אם \u0003יש בשיפועה\u0004 רוחב \u0003טפח\u0004 — אסור, לפי הכלל ש\u0003שפועי אהלים כאהלים דמו\u0004 \u0005[נחשבים].\u0006 \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שכילה זו מותרת \u0003אלא\u0004 כש\u0003לא נחית מפוריא\u0004 \u0005[יורד\u0006 חלק מן הכילה למטה \u0005מן המטה]\u0006 \u0003טפח, אבל\u0004 אם \u0003נחית מפוריא\u0004 \u0005[יורד מן המטה]\u0006 \u0003טפח\u0004 — \u0003אסור,\u0004 שהמיטה עצמה נעשית כגג והיריעה כקיר.","\u0003ו\u0004עוד \u0003אמר רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: האי סיאנא שרי\u0004 \u0005[כובע זה של לבד מותר]\u0006 לחובשו בשבת, אף שיש לו שוליים רחבים ודומה כמין אוהל. ומקשים, \u0003והאיתמר\u0004 \u0005[והרי נאמר]\u0006 במקום אחר: \u0003סיאנא אסור\u0004 ללובשו בשבת! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שאסור ללובשו הרי זה באופן \u0003דאית ביה\u0004 \u0005[שיש בו,\u0006 בשוליו\u0005]\u0006 \u0003טפח\u0004 ודומה יותר לאוהל, \u0003הא\u0004 \u0005[זה]\u0006 שאמר רב ששת שמותר ללובשו הרי זה באופן \u0003דלית ביה\u0004 \u0005[שאין בו]\u0006 \u0003טפח.\u0004","ותוהים: \u0003אלא מעתה,\u0004 אם \u0003שרביב בגלימא\u0004 \u0005[שירבב את הגלימה\u0006 שלו\u0005]\u0006 \u0003טפח\u0004 מחוץ לראשו \u0003הכי נמי דמיחייב\u0004 \u0005[כך גם כן\u0006 תאמר \u0005ש\u0006הוא \u0005חייב]\u0006 משום עושה אוהל? \u0003אלא לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה],\u0006 ויש לדחות את מה שאמרנו ולומר כי לא משום עשיית אוהל נאסר הדבר, כי אם מחשש שמא תפריח הרוח את הכובע מראשו ויבוא לטלטלו בידו. ונבין את הדעות השונות כך: \u0003הא\u0004 \u0005[זה]\u0006 שאמר רב ששת שמותר ללובשו הרי זה באופן \u0003דמיהדק\u0004 \u0005[ש\u0006הוא \u0005מהודק]\u0006 בראשו, \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שאסור ללובשו הרי זה באופן \u0003דלא מיהדק\u0004 \u0005[שאינו מהודק].\u0006","\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רמי בר יחזקאל לרב הונא: אימא לן איזי הנך מילי מעלייתא\u0004 \u0005[אמור לנו אותם דברים מעולים]\u0006 ש\u0003אמרת לן משמיה\u0004 \u0005[לנו משמו]\u0006 של \u0003רב, תרתי\u0004 \u0005[שתים]\u0006 \u0003ב\u0004ענין \u0003שבת וחדא ב\u0004ענין \u0003תורה.\u0004","\u0003שלח ליה\u0004 \u0005[לו]\u0006 רב הונא בתשובה: \u0003הא דתניא\u0004 \u0005[זה ששנינו\u0006 בברייתא\u0005]\u0006 ה\u0003גוד\u0004 (כעין נאד גדול) \u0003בכיסנא\u0004 \u0005[ברצועותיו]\u0006 \u0003מותר לנטותה בשבת. אמר רב: לא שנו\u0004 שמותר \u0003אלא ב\u0004שעושים זאת \u0003שני בני אדם\u0004 ביחד, שאינם מותחים אותו כעין אוהל אלא מניחים אותו בלא לנטותו, \u0003אבל באדם אחד\u0004 — \u0003אסור,\u0004 שיש לחשוש שמא תוך כדי הנחה יעשהו כעין אוהל.","\u0003אמר אביי: וכילה אפילו בעשרה בני אדם אסור\u0004 לפורסה בשבת. וטעם הדבר — שכן \u0003אי אפשר דלא מימתחא פורתא\u0004 \u0005[שלא תמתח מעט]\u0006 ותיעשה כאוהל במשך זמן מסוים.","\u0003אידך\u0004 \u0005[\u0006ההלכה ה\u0005אחרת\u0006 בענין שבת \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא — דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כירה שנשמטה אחת מירכותיה\u0004 (רגליה) — \u0003מותר לטלטלה\u0004 בשבת, משום שיש לה עדיין דין כלי המותר בטלטול לצורך מקומו. אבל אם נשמטו \u0003שתים\u0004 — \u0003אסור,\u0004 שנעשתה כשבר כלי. \u0003רב אמר: אפילו\u0004 כאשר נשמטה רק \u0003חד\u0004 \u0005[אחת]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור\u0004 לטלטלה, \u0003גזירה שמא יתקע\u0004 וישים בחזקה את הרגל שנשמטה במקומה, ויתחייב משום מתקן כלי.","ובענין \u0003תורה\u0004 — הוא ש\u0003אמר רב: עתידה תורה שתשתכח מישראל,\u0004 וכפי \u0003שנאמר\u0004 בסוף הקללות שבתוכחה: \u0003\"והפלא ה' את מכתך\u0004 ואת מכות זרעך מכות גדולות ונאמנות וחליים רעים ונאמנים\" (דברים כח, נט), \u0003ולשון הפלאה זו\u0004 שנאמרה בכתוב כתוספת על הענשים המפורשים \u0003איני יודע מהו.\u0004 ואולם \u0003כשהוא אומר: \"לכן הנני יוסף להפליא את העם הזה הפלא ופלא\u0004 ואבדה חכמת חכמיו ובינת נבוניו תסתתר\u0003\"\u0004 (ישעיהו כט, יד) \u0003הוי אומר: הפלאה זו\u0004 הרי היא שכחת ה\u0003תורה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 מעין זה בתוספתא: \u0003כשנכנסו רבותינו לכרם ביבנה אמרו: עתידה תורה שתשתכח מישראל,\u0004 וכפי \u0003שנאמר: \"הנה ימים באים נאם ה' אלהים והשלחתי רעב בארץ לא רעב ללחם ולא צמא למים כי אם לשמע את דברי ה'\"\u0004(עמוס ח, יא), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ונעו מים עד ים ומצפון ועד מזרח ישוטטו לבקש את דבר ה' ולא ימצאו\"\u0004 (עמוס ח, יב).","\"דבר ה'\" יש לו משמעויות רבות: \u0003\"דבר ה'\"\u0004— \u0003זו הלכה, \"דבר ה'\"\u0004— \u0003זה הקץ, \"דבר ה'\"\u0004— \u0003זו נבואה,\u0004 שכל אלה יאבדו מישראל.","\u0003ומאי\u0004 \u0005[ומה\u0006 הוא\u0005]\u0006 \u0003\"ישוטטו לבקש את דבר ה'\"? אמרו: עתידה אשה שתטול ככר\u0004 לחם \u0003של תרומה ותחזור\u0004 (תסתובב) \u0003בבתי כנסיות ובבתי מדרשות לידע אם טמאה היא ואם טהורה היא, ואין מבין.\u0004","ושואלים: כיצד ייתכן שלא ידעו לענות על שאלה פשוטה כזו \u0003אם טהורה היא ואם טמאה היא\u0004 ש\u0003בהדיא כתיב ביה\u0004 \u0005[במפורש\u0006 ובמישרין \u0005כתוב בה]:\u0006 \u0003\"מכל האכל אשר יאכל\u0004 אשר יבוא עליו מים יטמא וכל משקה אשר ישתה בכל כלי יטמא\u0003\"\u0004 (ויקרא יא, לד) ואין ספק בדבר טומאת לחם! \u0003אלא\u0004 מבארים: שתרצה האשה \u0003לידע אם\u0004 בדרגות הטומאה \u0003ראשונה היא\u0004 לטומאה \u0003ואם שניה היא, ואין מבין.\u0004","ותוהים: \u0003הא נמי מתניתין\u0004 \u0005[זו גם כן משנה]\u0006 מפורשת \u0003היא,\u0004 וכיצד ייתכן שלא ידעו משנה מפורשת? \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003השרץ\u0004 המת \u0003שנמצא ב\u0004אויר ה\u0003תנור\u0004 — \u0003הפת שבתוכו, שניה\u0004 לטומאה, \u0003שהתנור\u0004 נטמא מחמת השרץ (שהוא אב הטומאה) ונעשה \u0003תחילה\u0004 (ראשון לטומאה) והפת שניה.","ואומרים: \u0003מסתפקא להו הא\u0004 \u0005[מסופק להם\u0006 כעין \u0005זה]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר אהבה לרבא: ליחזייה האי תנורא כמאן דמלי\u0004 \u0005[שיראו את התנור\u0006 הזה \u0005כמי שמלא]\u0006 \u0003טומאה ותיהוי\u0004 \u0005[ותהא]\u0006 ה\u0003פת ראשונה\u0004 לטומאה, שכן אין צורך שיגע השרץ בפת, אלא כל מאכל הנמצא באוירו (חללו) של כלי חרס שיש בו שרץ מת — נטמא באופן ישיר מן השרץ!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא אמרינן ליחזייה האי תנורא כמאן דמלי\u0004 \u0005[אין אנו אומרים שיראו את התנור כמי שמלא]\u0006 ב\u0003טומאה. יכול יהו כל הכלים מיטמאין באויר כלי חרס\u0004 שיש בתוכו שרץ, \u0003תלמוד לומר:\u0004 \"וכל כלי חרש אשר יפול מהם אל תוכו \u0003כל אשר בתוכו יטמא\u0004 ואותו תשבורו. \u0003מכל האכל אשר יאכל\u0004 וגו'\" (ויקרא יא, לג–לד). ומסמיכות הכתובים אנו למדים: \u0003אוכלין מטמאין באויר כלי חרס, ואין כלים מטמאין באויר כלי חרס.\u0004 הרי שאין חלל התנור נחשב כמלא טומאת השרץ, שאלמלא כן היו אף הכלים טמאים.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 אחרת, \u0003ר' שמעון בן יוחי אומר: חס ושלום שתשתכח תורה מישראל, שנאמר: \"\u0004וענתה השירה הזאת לפניו לעד \u0003כי לא תשכח מפי זרעו\"\u0004 (דברים לא, כא), \u0003אלא מה אני מקיים \"ישוטטו לבקש את דבר ה' ולא ימצאו\"\u0004 — \u0003שלא ימצאו\u0004"],["\u0003הלכה ברורה ומשנה ברורה במקום אחד,\u0004 אלא יהיו חלוקי דעות בין החכמים.","\u0003תניא\u0004 \u0005[שנוייה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי בן אלישע אומר: אם ראית דור שצרות רבות באות עליו\u0004 — \u0003צא ובדוק בדייני ישראל\u0004 שמא חטאיהם גרמו. \u0003שכל פורענות שבאה לעולם לא באה אלא בשביל דייני ישראל\u0004 שקלקלו, וכפי \u0003שנאמר: \"שמעו נא זאת ראשי בית יעקב וקציני בית ישראל המתעבים משפט ואת כל הישרה יעקשו. בנה ציון בדמים וירושלם בעולה. ראשיה בשחד ישפטו וכהניה במחיר יורו ונביאיה בכסף יקסמו ועל ה' ישענו\u0004 לאמר הלא ה' בקרבנו לא תבוא עלינו רעה\u0003\"\u0004 (מיכה ג, ט-יא).","ומעירים: \u0003רשעים הן, אלא שתלו בטחונם במי שאמר והיה העולם,\u0004 בקדוש ברוך הוא. \u0003לפיכך,\u0004 בשל חטאיה \u0003מביא הקדוש ברוך הוא עליהן שלש פורעניות כנגד שלש עבירות שבידם,\u0004 וכפי \u0003שנאמר\u0004 בהמשך הדברים: \u0003\"לכן בגללכם ציון שדה תחרש וירושלם עיין תהיה והר הבית לבמות יער\"\u0004 (מיכה ג, יב).","\u0003ואין הקדוש ברוך הוא משרה שכינתו על ישראל עד שיכלו שופטים ושוטרים רעים מישראל, שנאמר: \"ואשיבה ידי עליך ואצרף כבר סיגיך ואסירה כל בדיליך. ואשיבה שפטיך כבראשונה ויעציך כבתחלה\u0004 אחרי כן יקרא לך עיר הצדק קריה נאמנה\" (ישעיה א, כה-כו).","\u0003אמר עולא: אין ירושלים נפדה אלא בצדקה,\u0004 וכפי \u0003שנאמר: \"ציון במשפט תפדה ושביה בצדקה\"\u0004 (ישעיה א, כז).","\u0003אמר רב פפא: אי בטלי יהירי\u0004 \u0005[אם יתבטלו היהירים,\u0006 הגאוותנים\u0005]\u0006 — \u0003בטלי אמגושי\u0004 \u0005[יבטלו האמגושים,\u0006 כהני האש הפרסיים\u0005].\u0006 \u0003אי בטלי דייני\u0004 \u0005[אם יתבטלו הדיינים]\u0006 של שקר — \u0003בטלי גזירפטי\u0004 \u0005[יתבטלו שוטרי המלך\u0006 ונוגשיו\u0005].\u0006","ומסביר: \u0003אי בטלי יהירי\u0004 \u0005[אם יתבטלו היהירים,\u0006 הגאוותנים\u0005]\u0006 — \u0003בטלי אמגושי\u0004 \u0005[יבטלו האמגושים]\u0006 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ואצרוף כבר סגיך\u0004 ואסירה כל בדיליך\u0003\",\u0004 שכאשר יצאו אלה שהם סיגים (מתגדלים ומתייהרים), יבטלו גם כהני האש המובדלים מיראת השם.","ומה שאמר \u0003אי בטלי דייני\u0004 \u0005[אם יתבטלו הדיינים]\u0006 של שקר \u0003בטלי גזירפטי\u0004 \u0005[יתבטלו שוטרי המלך\u0006 ונוגשיו\u0005]\u0006 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"הסיר ה' משפטיך פנה אויבך\"\u0004 (צפניה ג, טו).","\u0003אמר ר' מלאי משום\u0004 (בשם) \u0003ר' אלעזר בר' שמעון: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"שבר ה' מטה רשעים שבט משלים\"\u0004 (ישעיה יד ה), ומסבירים: \u0003\"שבר ה' מטה רשעים\"\u0004 — \u0003אלו הדיינין שנעשו מקל לחזניהם\u0004 (שמשיהם), שהשמשים מתעללים בשאר אנשים והדיינים משמשים להם כעזר וכתמיכה. \u0003\"שבט משלים\"\u0004 — \u0003אלו תלמידי חכמים שבמשפחות הדיינין,\u0004 שמתוך שהם תלמידי חכמים הם מסייעים לקרוביהם הדיינים להעלים את מומיהם. \u0003מר זוטרא אמר: אלו תלמידי חכמים שמלמדים הלכות ציבור לדייני בור.\u0004 כלומר, שמלמדים מעט תורה ודרך התנהגות לדיינים בורים, ועל ידי כך אין אנשים יודעים עד כמה בורים הם, ומשאירים אותם במשרתם.","\u0003אמר ר' אליעזר בן מלאי משום ריש לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"כי כפיכם נגאלו בדם ואצבעותיכם בעון, שפתותיכם דברו שקר לשונכם עולה תהגה\"\u0004 (ישעיה נט, ג).","ומבאר: \u0003\"כי כפיכם נגאלו בדם\"\u0004 — \u0003אלו הדיינין\u0004 הנוטלים שוחד בידם. \u0003\"ואצבעותיכם בעון\"\u0004 — \u0003אלו סופרי הדיינין\u0004 הכותבים שקר באצבעותיהם. \u0003\"שפתותיכם דברו שקר\"\u0004 — \u0003אלו עורכי הדיינין. \"לשונכם עולה תהגה\"\u0004 — \u0003אלו בעלי\u0004 ה\u0003דינין\u0004 עצמם.","\u0003ואמר ר' מלאי משום ר' יצחק מגדלאה: מיום שפירש\u0004 (נפרד) \u0003יוסף מאחיו לא טעם טעם יין, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"\u0004תהיין לראש יוסף \u0003ולקדקד נזיר אחיו\"\u0004 (בראשית מט, כו), שלשון הכתוב מרמז על שנהג יוסף בנזירות ולא שתה יין.","\u0003ר' יוסי בר' חנינא אמר: אף הן,\u0004 האחים, \u0003לא טעמו טעם יין\u0004 מתוך חרטה, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וישתו וישכרו עמו\"\u0004 (בראשית מג, לד), ו\u0003מכלל\u0004 זה אתה למד ש\u0003עד האידנא\u0004 \u0005[עכשיו]\u0006 \u0003לא הוה\u0004 \u0005[היתה]\u0006 \u0003שיכרות,\u0004 אלא נמנעו משתיה. \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' מלאי\u0005]\u0006 סבור כי אמנם \u0003שיכרות הוא\u0004 ש\u0003לא הוה\u0004 \u0005[היתה],\u0006 ואולם \u0003שתיה מיהא הוה\u0004 \u0005[לפחות היתה].\u0006","\u0003ו\u0004עוד \u0003אמר ר' מלאי:\u0004 נאמר \"ויחר אף ה' במשה ויאמר הלא אהרן אחיך הלוי ידעתי כי דבר ידבר הוא וגם הנה הוא יוצא לקראתך וראך ושמח בלבו \u0005(שמות ד, יד)\u0006, ודרשו: \u0003בשכר \"וראך ושמח בלבו\",\u0004 שלא קינא אהרן בגדולת אחיו, \u0003זכה\u0004 להיות כהן ו\u0003לחשן המשפט על לבו.\u0004","וחוזרים עתה להלכה בדיני כילה. \u0003שלחו ליה\u0004 \u0005[לו]\u0006 \u0003בני\u0004 העיירה \u0003בשכר ללוי: כילה מהו\u0004 דינה לענין לפרסה בשבת? וכן: \u0003כשותא בכרמא\u0004 \u0005[כשות בכרם]\u0006 \u0003מהו\u0004 דינה, האם יש בה משום כלאיים? אדם ש\u0003מת ביום טוב מהו\u0004 הדין בכגון זה, כיצד נטפל בו?","\u0003אדאזיל נח נפשיה\u0004 \u0005[עד שהלך נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003לוי. אמר שמואל לרב מנשיא: אי חכימת\u0004 \u0005[אם חכם אתה]\u0006 ויודע לענות, \u0003שלח להו\u0004 \u0005[להם]\u0006 בתשובה לשאלותיהם: \u0003כילה\u0004 — \u0003חזרנו על כל צידי כילה ולא מצינו לה צד היתר.\u0004","ושואלים: \u0003ולישלח להו\u0004 \u0005[שישלח להם]\u0006 שיש היתר כדברי \u0003רמי בר יחזקאל!\u0004 ומשיבים: לא רצה לגלות להם היתר זה \u0003לפי שאינן בני תורה\u0004 ולא יבחינו בין אופן מותר ואסור.","ובענין \u0003כשותא בכרמא\u0004 — הרי זה \u0003עירבובא\u0004 \u0005[כשות בכרם כלאיים].\u0006 ושואלים: \u0003ולישלח להו\u0004 \u0005[ושישלח להם]\u0006 \u0003כ\u0004דברי \u0003ר' טרפון? דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 בתוספתא: \u0003כישות, ר' טרפון אומר: אין\u0004 הם \u0003כלאים בכרם. וחכמים אומרים:\u0004 כישות \u0003הם כלאים בכרם. וקיימא לן\u0004 \u0005[מוחזק בידינו]:\u0006 \u0003כל המיקל\u0004 בדיני כלאיים \u0003בארץ,\u0004 אפילו אין הלכה כמותו באותה הלכה, הרי \u0003הלכה כמותו בחוץ לארץ,\u0004 שדין כלאיים שם מדברי סופרים בלבד! ומסבירים: לא גילה להם את ההיתר \u0003לפי שאינן בני תורה.\u0004","ובענין זה של כישות בכרם מספרים שהיה \u0003מכריז רב\u0004 ואומר: \u0003האי מאן דבעי למיזרע כשותא בכרמא\u0004 \u0005[מי שרוצה לזרוע כשות בכרם]\u0006 — \u0003ליזרע\u0004 \u0005[שיזרע].\u0006 \u0003רב עמרם חסידא\u0004 \u0005[החסיד]\u0006 היה \u0003מנגיד עילויה\u0004 \u0005[מלקה על כך],\u0006 על מי שזרע כשות בכרם.","ומסופר: \u0003רב משרשיא יהיב ליה\u0004 \u0005[נתן לו]\u0006 \u0003פרוטה לתינוק גוי וזרע ליה\u0004 \u0005[ו\u0006היה \u0005זורע לו]\u0006 ושואלים: \u0003וליתן ליה\u0004 \u0005[ושיתן אותה\u0006 את הפרוטה\u0005]\u0006 \u0003לתינוק ישראל,\u0004 שהרי אף הוא אינו מחוייב במצוות! ומשיבים : \u0003אתי למיסרך\u0004 \u0005[יבוא להימשך\u0006 בדבר\u0005]\u0006 ויעשה כן גם כשיגדל. ושואלים: \u0003וליתן ליה\u0004 \u0005[ושיתן אותה\u0006 את הפרוטה\u0005]\u0006 \u0003לגדול גוי!\u0004 ומשיבים: \u0003אתי לאיחלופי\u0004 \u0005[יבוא להחליפו]\u0006 \u0003בישראל.\u0004","ולגבי \u0003מת שלח להו\u0004 \u0005[להם]\u0006 תשובה: \u0003מת לא יתעסקו ביה\u0004 \u0005[בו]\u0006 \u0003לא יהודאין\u0004 \u0005[יהודים]\u0006 \u0003ולא ארמאין\u0004 \u0005[נכרים]\u0006 \u0003לא ביום טוב ראשון ולא ביום טוב שני.\u0004","ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יהודה בר שילת\u0004 שכך \u0003אמר ר' אסי: עובדא הוה בבי כנישתא\u0004 \u0005[מעשה היה בבית הכנסת]\u0006 של היישוב \u0003מעון ביום טוב הסמוך לשבת\u0004 שמת אדם אחד,"],["\u0003ולא ידענא אי\u0004 \u0005[ואיני יודע אם]\u0006 חל היום טוב \u0003מלפניה אי\u0004 \u0005[אם]\u0006 \u0003מלאחריה,\u0004 כלומר, ביום הששי או ביום הראשון, \u0003ואתו לקמיה\u0004 \u0005[ובאו לפני]\u0006 \u0003ר' יוחנן ואמר להו\u0004 \u0005[להם]:\u0006 \u0003יתעסקו ביה\u0004 \u0005[בו]\u0006 \u0003עממין\u0004 (גויים).","\u0003ו\u0004כן \u0003אמר רבא: מת ביום טוב ראשון — יתעסקו בו עממין\u0004 ואם מת \u0003ביום טוב שני\u0004 שתקנו חכמים לגלויות — \u0003יתעסקו בו ישראל, ואפילו ביום טוב שני של ראש השנה. מה שאין כן בביצה,\u0004 שלגבי ביצה שנולדה ביום טוב מחשיבים את שני ימי ראש השנה כיום ארוך אחד, ואין מחלקים ביניהם, אבל משום כבוד המת הקילו בעניינו בשני. ואם כן, מדוע לא התיר רב מנשיא לבני בשכר לטפל במת ביום טוב? ומשיבים: \u0003לפי שאינן בני תורה.\u0004","\u0003אמר רב אבין בר רב הונא\u0004 שכך \u0003אמר רב חמא בר גוריא: מתעטף אדם בכילה ובכסכסיה\u0004 \u0005[רצועותיה]\u0006 \u0003ויוצא\u0004 כשהוא עטוף בה \u0003לרשות הרבים בשבת, ואינו חושש\u0004 משום נשיאת משא.","ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 הדבר ממה שאמר \u0003רב הונא,\u0004 ש\u0003אמר רב הונא\u0004 שכך \u0003אמר רב: היוצא\u0004 בשוגג לרשות הרבים \u0003בטלית שאינה מצויצת כהילכתה בשבת,\u0004 וכגון שציצית אחת חסרה בה — \u0003חייב\u0004 קרבן \u0003חטאת,\u0004 משום ששאר הציציות אינן מגוף הטלית, וכיון שאינן משמשות באותו זמן מצוה הרי הן כמשאוי שאסור להוציאו! ומשיבים: יש להבדיל ולומר כי \u0003ציצית לגבי טלית\u0004 — \u0003חשיבי, ולא בטלי\u0004 \u0005[חשובות ואינן בטלות]\u0006 ונחשבות כחפץ לעצמו ולכן אסור להוציאן. \u0003הני לא חשיבי, ובטלי\u0004 \u0005[אלה\u0006 רצועות הכילה \u0005אינן חשובות ובטלות].\u0006","\u0003אמר רבה בר רב הונא:\u0004 לדעת חכמים האוסרים לתלות את המשמרת ביום טוב, עדיין יכול שיהא \u0003מערים אדם על\u0004 איסור \u0003תליית המשמרת\u0004 ביום טוב, בכך שנוטל אותה \u0003ביום טוב\u0004 ותולה אותה כדי \u0003לתלות בה רמונים,\u0004 ודבר זה מותר, \u0003ו\u0004מאחר שהיא כבר תלויה יכול הוא כבר שיהא \u0003תולה בה\u0004 יין כדי לסננו מן ה\u0003שמרים,\u0004 שהרי אמרו שמותר לעשות כן ביום טוב במשמרת התלויה כבר. \u0003אמר רב אשי: ו\u0004היתר זה \u0003הוא\u0004 דווקא באופן ש\u0003תלה בה רמונים\u0004 קודם לפני שתלה בה שמרים, שהכל רואים שעשה בה שימוש של היתר.","ושואלים: \u0003מאי שנא מהא דתניא\u0004 \u0005[במה שונה\u0006 הדבר \u0005מ\u0006הלכה \u0005זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מטילין\u0004 (מתחילים לעשות) \u0003שכר\u0004 בחול \u0003המועד לצורך המועד,\u0004 ואולם \u0003שלא לצורך המועד\u0004 — \u0003אסור, אחד שכר תמרים ואחד שכר שעורים.\u0004 ו\u0003אף על פי שיש להן\u0004 שכר \u0003ישן\u0004 — הריהו \u0003מערים\u0004 ואומר שרצונו להיות \u0003שותה מן החדש\u0004 ולצורך זה עושה הוא שכר בחול המועד. נמצא שמותר להערים אף בלי להוכיח במעשה שעושה לצורך היתר ולא כדברי רב אשי!","ומשיבים: \u0003התם לא מוכחא מילתא\u0004 \u0005[שם אין הדבר מוכח\u0006 וניכר\u0005],\u0006 שכשרואים אותו מטיל שכר אין יודעים שיש לו בביתו שכר מוכן, ועצם מעשהו אינו אסור בכל מקרה, אבל \u0003הכא\u0004 \u0005[כאן]\u0006 במשמרת — \u0003מוכחא מילתא\u0004 \u0005[מוכח הדבר],\u0006 שרואים שהוא תולה משמרת ויש איסור בדבר.","כיון שדובר בענין הערמה מסופר ש\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרב אשי: חזי מר האי צורבא מרבנן\u0004 \u0005[יראה אדוני תלמיד חכם]\u0006 \u0003ורב הונא בר' חיון שמיה\u0004 \u0005[שמו],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003רב הונא בר' חלוון שמיה\u0004 \u0005[שמו]\u0006 \u0003דשקל ברא דתומא ומנח בברזא דדנא, ואמר: לאצנועיה קמיכוינא\u0004 \u0005[שלוקח בן שום,\u0006 פלח שום, \u0005ומניחו בנקב החבית ואומר: להצניע אותו,\u0006 את השום, \u0005אני מתכוון]\u0006 והריהו סותם נקב בשבת. \u0003ו\u0004כן \u0003אזיל ונאים במברא, ועבר להך גיסא וסייר פירי, ואמר: אנא למינם קמיכוינא\u0004 \u0005[הולך וישן במעבורת\u0006 שעל הנהר, ובעל המעבורת משיטו \u0005ועובר לצד השני\u0006 של הנהר, \u0005ומסייר\u0006 ובודק \u0005פירות\u0006 כרמו, \u0005ואומר: אני מתכוון לישון],\u0006 ונמצא שנסע בשבת בסירה באיסור!","\u0003אמר להו\u0004 \u0005[להם]\u0006 רב אשי: \u0003הערמה קאמרת\u0004 \u0005[אמרת]?\u0006 \u0003הערמה בדרבנן\u0004 \u0005[ב\u0006דברי \u0005חכמים]\u0006 \u0003היא,\u0004 שהרי לא עבר על איסור מן התורה, \u0003וצורבא מרבנן\u0004 \u0005[ותלמיד חכם]\u0006 \u0003לא אתי למיעבד\u0004 \u0005[יבוא לעשות]\u0006 \u0003לכתחילה\u0004 בלא הערמה, ואין לאסור עליו.","\u0003נותנין\u0004 בשבת \u0003מים על גב השמרים\u0004 התלויים במשמרת \u0003בשביל שיצולו\u0004 (שיהיו צלולים ונקיים). \u0003ו\u0004כן \u0003מסננין את היין בסודרין, ובכפיפה\u0004 (סל) \u0003מצרית\u0004 העשויה מעלי דקל. שכיון שראויים המשקים הללו לשתיה אף בלא הסינון אין בכך משום מלאכת בורר האסורה.","\u0003ו\u0004כן \u0003נותנין ביצה במסננת של חרדל\u0004 להפריד בין החלבון והחלמון, \u0003ועושין אנומלין\u0004 (משקה יין) \u0003בשבת. ר' יהודה אומר: בשבת\u0004 אין עושין אנומלין אלא \u0003בכוס\u0004 קטנה, \u0003ביום טוב\u0004 — \u0003בלגין\u0004 שהוא כלי גדול יותר, \u0003ובמועד\u0004 — אפילו \u0003בחבית. ר' צדוק אומר הכל לפי האורחין,\u0004 ואם מרובים הם מרבים באנומלין.","\u0003אמר זעירי: נותן אדם יין צלול ומים צלולין לתוך המשמרת בשבת ואינו חושש\u0004 משום איסור בורר, שהרי היין ראוי לשתיה גם בלא סינון זה, \u0003אבל עכורין\u0004 — \u0003לא.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו ש\u0003רבן שמעון בן גמליאל אומר: טורד\u0004 (מערב) \u0003אדם חבית של יין\u0004 על \u0003יינה ושמריה, ונותן לתוך המשמרת בשבת ואינו חושש,\u0004 נמצא שמותר לשים בתוך המשמרת גם יין עכור! \u0003תרגמה\u0004 \u0005[הסביר אותה\u0006 קושיה\u0005]\u0006 החכם \u0003זעירי: בין הגיתות שנו,\u0004 שהיין עדיין לא תסס והוא נשאר עכור בין כה וכה, וגם לאחר סינון לא יצטלל לגמרי.","שנינו במשנה ש\u0003מסננין\u0004 בשבת \u0003את היין בסודרין. אמר רב שימי בר חייא: ובלבד שלא יעשה גומא\u0004 בסודר לשפוך בו את היין, וזאת כדי לשנות ממעשהו בחול.","עוד שנינו במשנה שהתירו לסנן בשבת את היין \u0003בכפיפה מצרית, אמר רב חייא בר אשי\u0004 שכך \u0003אמר רב: ובלבד שלא יגביה\u0004 את הכפיפה \u0003מקרקעיתו של\u0004 ה\u0003כלי\u0004 התחתון \u0003טפח\u0004 וישנה גם בדבר זה (רבינו יונה).","\u0003אמר רב: האי פרונקא\u0004 \u0005[כיסוי זה]\u0006 שיש בו נקבים לסינון, \u0003אפלגיה דכובא\u0004 \u0005[על חצי החבית]\u0006 — \u0003שרי\u0004 \u0005[מותר]\u0006 לפורסו, ואולם \u0003אכוליה כובא\u0004 \u0005[על כל החבית]\u0006 — \u0003אסור,\u0004 שלא יסנן דרכו (ר\"ח).","\u0003אמר רב פפא: לא ניהדק איניש צינייתא בפומיה דכוזני דחביתא\u0004 \u0005[אל יהדק אדם צרור קש בפי משפך החבית],\u0006 \u0003משום דמיחזי\u0004 \u0005[שנראה]\u0006 \u0003כמשמרת.\u0004","מסופר: \u0003דבי\u0004 \u0005[\u0006בני \u0005בית]\u0006 \u0003רב פפא שאפו שיכרא ממנא למנא\u0004 \u0005[היו שופכים בזהירות שיכר מכלי לכלי]\u0006 כדי שהפסולת המצויה בכלי אחד לא תעבור לשני. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדיפתי לרבינא: האיכא\u0004 \u0005[הרי יש]\u0006 \u0003ניצוצות,\u0004 טיפות המשקה האחרונות, שכן בסופה של פעולה זו רואים שהשופך התכוון לברר את שארית השיכר מן הפסולת שבכלי, ויש כאן משום ברירה! ענה לו: בבית רב פפא היו משאירים את הניצוצות בכלי הראשון ולא ניסו לבררם, כי \u0003ניצוצות לבי\u0004 \u0005[בבית]\u0006 \u0003רב פפא לא חשיבי\u0004 \u0005[היו חשובים],\u0006 שהיה שיכר מצוי תמיד בביתו.","עוד שנינו ש\u0003נותנין\u0004 בשבת \u0003ביצה במסננת\u0004 חרדל כדי להפריד בין החלבון והחלמון. \u0003תני\u0004 \u0005[שנה]\u0006 החכם \u0003יעקב קרחה\u0004 בטעם הדבר:"],["\u0003לפי שאין עושין אותה אלא לגוון,\u0004 שצריכים את החלמון רק להוסיף צבע נאה לתבשיל, ואולם אין בכך כדי לבטל את חשיבות החלבון כאוכל ולעשותו כפסולת, ולכן אין בזה ברירה ממש.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 \u0003חרדל שלשו מערב שבת. למחר,\u0004 בשבת, \u0003אמר רב:\u0004 משנה בו ו\u0003ממחו\u0004 (ממיס אותו) ביין או מים \u0003ב\u0004אמצעות \u0003כלי אבל לא ביד,\u0004 וזהו השינוי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל: ביד?! אטו\u0004 \u0005[וכי]\u0006 ב\u0003כל יומא\u0004 \u0005[יום]\u0006 \u0003ממחו ליה\u0004 \u0005[אותו]\u0006 \u0003ביד?!\u0004 והלא \u0003מאכל חמורים הוא\u0004 אם עושים אותו בצורה זו! ובודאי אין זו דרך עשייתו בימי החול, ואין אם כן להתיר את המסתו בשבת בכלי. \u0003אלא אמר שמואל\u0004 להיפך: \u0003ממחו ביד\u0004 לעשות שינוי \u0003ואינו ממחו בכלי\u0004 כדרכו.","בענין זה \u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו גם אמוראי ארץ ישראל. ש\u0003ר' אלעזר אמר: אחד זה ואחד זה,\u0004 בין ביד בין בכלי — \u0003אסור. ור' יוחנן אמר: אחד זה ואחד זה\u0004 — \u0003מותר. אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אין הלכה כר' יוחנן\u0004 שהתיר.","לאחר זמן \u0003קם\u0004 \u0005[עמד]\u0006 \u0003ר' יוחנן בשיטתיה\u0004 \u0005[בשיטתו]\u0006 של \u0003ר' אלעזר,\u0004 שהסכים לשיטה זו הלכה למעשה, ואסר בכל מקרה, ו\u0003קם\u0004 \u0005[עמד]\u0006 \u0003ר' אלעזר בשיטתיה\u0004 \u0005[בשיטתו]\u0006 של \u0003שמואל\u0004 האוסר לעשות רק בכלי. ועל כך \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003הלכה כר' יוחנן\u0004 שאסר הכל.","ומסופר: \u0003אימיה\u0004 \u0005[אימו,\u0006 אומנתו\u0005]\u0006 של \u0003אביי עבדא ליה\u0004 \u0005[עשתה לו]\u0006 חרדל, \u0003ולא אכל. דביתהו\u0004 \u0005[ אשתו ]\u0006 של \u0003זעירא עבדא ליה\u0004 \u0005[ עשתה לו]\u0006 \u0003לר' חייא בר אשי\u0004 תלמידו, \u0003ולא אכיל\u0004 \u0005[אכל].\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003לרבך עבידי ליה\u0004 \u0005[עשיתי לו]\u0006 \u0003ואכל, ואת לא אכלת\u0004 \u0005[ואתה אינך אוכל]?\u0006 \u0003אמר רבא בר שבא: הוה קאימנא קמיה\u0004 \u0005[היייתי עומד לפני]\u0006 \u0003רבינא ובחשי ליה בשופתא דתומא\u0004 \u0005[ובחשו לו\u0006 חרדל \u0005בעמוד העלי של השום]\u0006 \u0003ואכל.\u0004","\u0003אמר מר זוטרא: לית הלכתא ככל הני שמעתתא\u0004 \u0005[אין הלכה ככל האמרות הללו],\u0006 \u0003אלא כי הא דאתמר\u0004 \u0005[כמו זו שנאמר]:\u0006 \u0003חרדל שלשו מערב שבת, למחר\u0004 הריהו \u0003ממחו בין ביד בין בכלי ונותן לתוכו דבש. ו\u0004כשהוא ממחה \u0003לא יטרוף\u0004 בחוזק וכדרך אומנות, \u0003אלא מערב\u0004 אותו בנחת.","\u0003שחליים\u0004 (מין ירק) \u0003ששחקן מערב שבת, למחר נותן לתוכן שמן וחומץ, וממשיך\u0004 (מכניס) \u0003לתוכן אמיתא. ולא יטרוף אלא מערב.\u0004 וכן \u0003שום שריסקו מערב שבת, למחר\u0004 בשבת הוא \u0003נותן לתוכו פול וגריסין, ולא ישחוק אלא מערב, וממשיך את אמיתא לתוכן\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003אמיתא?\u0004 ומשיבים: היא \u0003נינייא\u0004 (נענע, מנתה). \u0003אמר אביי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003האי\u0004 \u0005[זו]\u0006 ה\u0003נינייא\u0004 הריהי \u0003מעליא לתחלי\u0004 \u0005[מעולה,\u0006 יפה, \u0005לשחליים].\u0006","\u0003ו\u0004עוד שנינו במשנה ש\u0003עושין אנומלין\u0004 (משקה יין) \u0003בשבת. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003עושין אנומלין בשבת, ואין עושין אלונטית.\u0004 ומסבירים: \u0003ואיזו היא אנומלין ואיזו היא אלונטית? אנומלין\u0004 היא תערובת של \u0003יין ודבש ופלפלין. אלונטית\u0004 היא תערובת של \u0003יין ישן ומים צלולין ואפרסמון, דעבדי לבי מסותא למיקר\u0004 \u0005[שעושים אותו\u0006 לאחר רחיצה \u0005בבית המרחץ להתקרר]\u0006 מחום הרחצה ויש בכך מעין רפואה, ולכן אסור לעשותה בשבת.","\u0003אמר רב יוסף: זימנא חדא עלית בתר\u0004 \u0005[פעם אחת נכנסתי אחר]\u0006 \u0003מר עוקבא לבי באני\u0004 \u0005[לבית המרחץ].\u0006 \u0003כי נפקי, אתאי אשקיין חמרא חד כסא, וחשי מבינתא דראשי ועד טופרא דכרעי\u0004 \u0005[כאשר יצאתי, בא\u0006 ו\u0005השקה אותי יין\u0006 זה \u0005כוס אחת, וחשתי\u0006 בצינתו \u0005משערות ראשי ועד ציפורן רגלי].\u0006 \u0003ואי אשקיין כסא אחרינא\u0004 — \u0003הואי מסתפינא דלמא מנכו לי מזכותא דעלמא דאתי\u0004 \u0005[ואם היה משקני כוס אחרת\u0006 (נוספת) — \u0005הייתי חושש שמא מנכים לי מזכות העולם הבא]\u0006 אם הייתי נשאר חי לאחר מכן. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מר עוקבא\u0004 הוא זה \u0003דשתי כל יומא\u0004 \u0005[ששותה כל יום]\u0006 משקה זה ואיך אינו ניזוק? ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003מר עוקבא דדש ביה\u0004 \u0005[ש\u0006הוא \u0005רגיל בו].\u0006","\u0003אין שורין את\u0004 צמח \u0003החילתית בפושרין\u0004 כדי להכין ממנו משקה לרפואה. \u0003אבל נותן\u0004 אותו \u0003לתוך החומץ\u0004 כתבלין רגיל. \u0003ואין שולין\u0004 (שורים) \u0003את הכרשינין\u0004 במים לברור אותם מפסולתם, \u0003ולא שפין אותן\u0004 ביד להסיר מהם הפסולת \u0003אבל נותן\u0004 אותם \u0003לתוך הכברה או לתוך הכלכלה\u0004 (סל), ואם יצאה הפסולת יצאה.","ו\u0003אין כוברין\u0004 (מנפים, מסננים) \u0003את התבן בכברה, ו\u0004כן \u0003לא יתננו על גבי מקום גבוה בשביל\u0004 שיצא \u0003המוץ\u0004 מנשיבת הרוח. \u0003אבל נוטל הוא\u0004 תבן \u0003בכברה ונותן לתוך האיבוס\u0004 של בהמה, ואם נפל המוץ אינו חושש.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003שרה\u0004 חלתית בשבת בשוגג, \u0003מאי\u0004 \u0005[מה]\u0006 דינו? \u0003תרגמא\u0004 \u0005[הסבירה]\u0006 \u0003רב אדא נרשאה\u0004 \u0005[מ\u0006העיר \u0005נרש]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב יוסף: שרה\u0004 — \u0003חייב חטאת.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה\u0004 אם \u0003שרה אומצא במיא\u0004 \u0005[חתיכת בשר במים]\u0006 \u0003הכי נמי דמיחייב\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שיתחייב]?\u0006 והרי אין זה בישול כלל! \u0003אלא אמר אביי:\u0004 אסור הדבר \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 כדי \u0003שלא יעשה כדרך שהוא עושה בחול.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' יוחנן מר' ינאי: מהו\u0004 הדין האם מותר \u0003לשרות\u0004 בשבת \u0003את החלתית בצונן? אמר ליה\u0004 \u0005[לו]\u0006 ר' ינאי: \u0003אסור.\u0004 והקשה לו ר' יוחנן: \u0003והא אנן תנן\u0004 \u0005[והרי אנחנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין שורין את החלתית בפושרין,\u0004 ונלמד מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בצונן מותר!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ינאי: \u0003אם כן מה בין לי ולך.\u0004 כלומר, כאן ההבדל בין ידיעותי וידיעותיך, שאני יכול לדון בהלכה באופן מעמיק יותר, כי במקרה זה אין לסמוך על משנתנו, לפי ש\u0003מתניתין יחידאה\u0004 \u0005[משנתנו\u0006 כדעת \u0005יחיד]\u0006 \u0003היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 בתוספתא: \u0003אין שורין את החלתית לא בחמין ולא בצונן, ר' יוסי אומר: בחמין\u0004 — \u0003אסור, בצונן\u0004 — \u0003מותר.\u0004 ונמצא שמשנתנו שאינה אוסרת בצונן היא רק כדעת ר' יוסי, ואין ללמוד הלכה ממנה.","ושואלים: \u0003למאי עבדי ליה\u0004 \u0005[למה עושים אותה],\u0006 את החלתית השרויה? ומשיבים: \u0003ליוקרא דליבא\u0004 \u0005[לכובד הלב],\u0006 שמי שחש כאב בלבו שותה חלתית לרפואה. מסופר: \u0003רב אחא בר יוסף חש ביוקרא דליבא\u0004 \u0005[בכובד הלב].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003מר עוקבא\u0004 לשאול בעצתו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 מר עוקבא: \u0003זיל שתי תלתא תיקלי חילתתא בתלתא יומי\u0004 \u0005[לך שתה משקל שלושה שקלים חלתית בשלושה ימים].\u0006 \u0003אזל אישתי חמשא\u0004 \u0005[הלך ושתה\u0006 ביום ה\u0005חמישי]\u0006 \u0003בשבת ומעלי\u0004 \u0005[ובערב]\u0006 \u0003שבת. לצפרא אזל\u0004 \u0005[בבוקר הלך]\u0006 ו\u0003שאל בי מדרשא\u0004 \u0005[בבית המדרש]\u0006 מה לעשות בשבת. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב אדא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 כי \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003מר בר רב אדא: שותה אדם\u0004 בשבת חלתית אפילו \u0003קב או קביים ואינו חושש\u0004 משום גזירת רפואה, שאף בריאים שותים אותה.","\u0003אמר להו\u0004 \u0005[להם]\u0006 רב אחא בר יוסף: בענין ההיתר \u0003לשתות\u0004 — \u0003לא קמיבעיא\u0004 \u0005[נשאלה]\u0006 \u0003לי\u0004 השאלה, \u0003כי קא מיבעיא\u0004 \u0005[כאשר נשאלה]\u0006 \u0003לי\u0004 — הרי זה בענין ההיתר \u0003לשרות מאי\u0004 \u0005[מהו]\u0006 דינו? \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב חייא בר אבין: בדידי הוה עובדא\u0004 \u0005[בי עצמי היה מעשה],\u0006 \u0003ואתאי שאילתיה\u0004 \u0005[ובאתי\u0006 ו\u0005שאלתיו]\u0006 \u0003לרב אדא בר אהבה\u0004 אותה שאלה \u0003ולא הוה בידיה\u0004 \u0005[היתה בידו]\u0006 תשובה לכך. \u0003אתאי שאילתיה\u0004 \u0005[באתי\u0006 ו\u0005שאילתיה]\u0006 מ\u0003רב הונא, ואמר: הכי קאמר\u0004 \u0005[כך אמר]\u0006 \u0003רב: שורה בצונן ומניח בחמה\u0004 שיתחמם מעט על ידי כך ויהא ראוי לשתיה.","ושואלים: \u0003האם פסק כמאן דשרי\u0004 \u0005[כמי שהתיר]\u0006 לשרות חלתית בצונן? ומשיבים: \u0003אפילו למאן דאסר\u0004 \u0005[ל\u0006דעת \u0005מי שאוסר],\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003היכא\u0004 \u0005[היכן]\u0006 ש\u0003לא אישתי\u0004 \u0005[שתה]\u0006 \u0003כלל, אבל הכא\u0004 \u0005[כאן]\u0006 \u0003כיון דאישתי חמשא ומעלי שבתא\u0004 \u0005[ששתה\u0006 ביום \u0005חמישי וערב שבת],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא שתי\u0004 \u0005[ישתה]\u0006 \u0003בשבת\u0004 — הריהו \u0003מיסתכן\u0004 בכך, \u0005ולכן הותרה לו שריית החלתית.\u0006","ומביאים בדרך אגב סיפור נוסף על רב אחא בר יוסף: \u0003מיסתמיך ואזיל\u0004 \u0005[היה נשען והולך]\u0006 \u0003רב אחא בר יוסף אכתפיה\u0004 \u0005[על כתיפו]\u0006 של \u0003רב נחמן בר יצחק בר אחתיה\u0004 \u0005[בן אחותו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אחא: \u0003כי מטינן לבי\u0004 \u0005[כאשר נגיע לבית]\u0006 \u0003רב ספרא עיילינא\u0004 \u0005[הכניסני].\u0006 \u0003כי מטו עייליה\u0004 \u0005[כאשר הגיעו הכניסו]\u0006 רב נחמן. \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 רב אחא מרב ספרא: \u0003מהו\u0004 הדין ביחס \u0003לכסכוסי כיתניתא בשבתא\u0004 \u0005[לשפשוף וריכוך כתונת בשבת]\u0006 כשהיא נעשית נוקשה לאחר כביסה? האם \u0003לרכוכי כיתניתא קא מיכוין\u0004 — \u0003ושפיר דמי\u0004 \u0005[האם לרכך את הכתונת הוא מתכוון\u0006 — \u0005ומותר],\u0006 \u0003או דילמא לאולודי חיורא קמיכוין\u0004 — \u0003ואסיר\u0004 \u0005[שמא להוליד,\u0006 להוסיף, \u0005לובן הוא מתכוון\u0006 — \u0005ואסור]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ספרא: \u0003לרכוכי קא מיכוין ושפיר דמי\u0004 \u0005[לרכך הוא מתכוון\u0006 — \u0005ומותר].\u0006","\u0003כי נפק אתא\u0004 \u0005[כאשר יצא\u0006 ו\u0005בא]\u0006 רב אחא מבית רב ספרא, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003מאי בעא מר מיניה\u0004 \u0005[מה שאל אדוני ממנו]\u0006 מרב ספרא? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אחא \u0003בעי מיניה\u0004 \u0005[שאלתי ממנו]:\u0006 \u0003מהו\u0004 הדין ביחס \u0003לכסכוסי כיתניתא בשבתא\u0004 \u0005[לשפשוף וריכוך כתונת בשבת],\u0006 \u0003ואמר לי: שפיר דמי\u0004 \u0005[יפה הדבר,\u0006 מותר\u0005].\u0006","ושאל רב נחמן בר יצחק: \u0003ותבעי ליה למר סודרא\u0004 \u0005[ושתישאל לו לאדוני\u0006 אותה שאלה ביחס לשפשוף \u0005סודר]?\u0006 ענה לו: בענין \u0003סודרא\u0004 \u0005[סודר]\u0006 \u0003לא קמיבעיא\u0004 \u0005[נשאלה]\u0006 \u0003לי\u0004 השאלה, \u0003דבעי\u0004 \u0005[ששאלתי]\u0006 \u0003מרב הונא, ופשיט\u0004 \u0005[ופתר]\u0006 \u0003לי\u0004 שמותר (רי\"ף).","ושאלו רב נחמן: \u0003ותיפשיט ליה למר מסודרא\u0004 \u0005[ושתפתר לו לאדוני\u0006 בעיה זו \u0005מסודר]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אחא: יש להבדיל בין המקרים, \u0003התם\u0004 \u0005[שם]\u0006 בכותונת — \u0003מיחזי כי אולודי חיורא\u0004 \u0005[נראה כהולדת,\u0006 עשיית \u0005לובן],\u0006 ואילו \u0003הכא\u0004 — \u0003לא מיחזי כאולודי חיורא\u0004 \u0005[כאן\u0006 בסודר — \u0005אינו נראה כעשיית לובן],\u0006 שאין מקפידים כל כך על לובנו של סודר, ובודאי מתכוונים רק לרככו.","\u0003אמר רב חסדא: האי כיתניתא\u0004 \u0005[כותונת זו]\u0006"],["\u0003משלפו לדידה מקניא\u0004 \u0005[להסיר אותה מן הקנה]\u0006 שהיא תלויה בו — \u0003שרי\u0004 \u0005[מותר],\u0006 ואולם להסיר \u0003קניא\u0004 \u0005[\u0006את \u0005הקנה]\u0006 \u0003ממנה\u0004 — \u0003אסור,\u0004 שקנה זה אינו כלי, והרי הוא מוקצה. \u0003אמר רבא: ואם כלי קיואי\u0004 (כלי אורגים) \u0003הוא\u0004 — \u0003מותר,\u0004 שאף שמלאכתו לאיסור, כיון שכלי הוא מותר לטלטלו.","\u0003אמר רב חסדא: האי כישתא דירקא\u0004 \u0005[אגודת ירק זו],\u0006 \u0003אי חזיא\u0004 \u0005[אם ראויה]\u0006 היא \u0003למאכל בהמה\u0004 — \u0003שרי לטלטולי\u0004 \u0005[מותר לטלטלה]\u0006 בשבת, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003אסיר\u0004 \u0005[אסור]\u0006 לטלטלה.","\u0003אמר רב חייא בר אשי\u0004 שכך \u0003אמר רב: האי תליא, דבשרא\u0004 \u0005[וו זה,\u0006 שתולים בו \u0005בשר]\u0006 — \u0003שרי לטלטולי\u0004 \u0005[מותר לטלטלו],\u0006 שהוא ראוי גם לשימוש אחר, ואולם וו \u0003דכוורי\u0004 \u0005[של דגים]\u0006 — \u0003אסיר\u0004 \u0005[אסור]\u0006 לטלטלו, לפי שריחו רע (ר\"ח), ואין משתמשים בו אלא לדגים בלבד.","\u0003אמר רב קטינא: העומד באמצע המטה\u0004 על נסר אחד עלול הוא לשברו, והריהו \u0003כאילו עומד בכריסה של אשה\u0004 שודאי יזיק לה, ואף כאן ודאי יגרום לשבירת המיטה (גאונים), ולכן אם עושה זאת בשבת — מותר. ומעירים: \u0003ולאו מילתא היא\u0004 \u0005[ואין זה דבר\u0006 שמתקבל להלכה\u0005].\u0006","כיון שהוזכרו דברי רב חסדא באגודות ירק, מביאים כמה עצות בענין זה ובדברים דומים ש\u0003אמר רב חסדא\u0004 כדי לייעץ לתלמידי חכמים עניים המתפרנסים בדוחק: \u0003בר בי רב דזבין ירקא\u0004 \u0005[בן בית הרב\u0006 תלמיד חכם \u0005הקונה ירק]\u0006 — \u0003ליזבין אריכא\u0004 \u0005[שיקנה\u0006 אגודה \u0005ארוכה],\u0006 שהרי \u0003כישא כי כישא\u0004 \u0005[האגודה כמו אגודה],\u0006 שלכל אגודות הירק עובי אחד, \u0003ואורכא\u0004 \u0005[האורך]\u0006 בא \u0003ממילא\u0004 כרווח.","\u0003ו\u0004עוד \u0003אמר רב חסדא: בר בי רב דזבין קניא\u0004 \u0005[בן בית הרב\u0006 \u0005הקונה קנים]\u0006 — \u0003ליזבין אריכא\u0004 \u0005[שיקנה ארוכים],\u0006 שהרי \u0003טונא כי טונא\u0004 \u0005[האגודה כמו אגודה],\u0006 שלכל אגודות הקנים עובי אחד, \u0003ואורכא\u0004 \u0005[והאורך]\u0006 הוא רווח \u0003ממילא. ו\u0004עוד","\u0003אמר רב חסדא: בר בי רב דלא נפישא ליה ריפתא\u0004 \u0005[בן בית הרב שאין לו פת מרובה]\u0006 — \u0003לא ליכול ירקא\u0004 \u0005[יאכל ירק],\u0006 \u0003משום דגריר\u0004 \u0005[\u0006\u0005[ש\u0006הוא \u0005גורר\u0006 ומעורר\u0005]\u0006 את התיאבון. \u0003ואמר רב חסדא: אנא\u0004 \u0005[אני]\u0006 \u0003לא בעניותי אכלי ירקא\u0004 \u0005[אכלתי ירק],\u0006 \u0003ולא בעתירותי אכלי ירקא\u0004 \u0005[בעשירותי אכלתי ירק].\u0006 \u0003בעניותי\u0004 לא אכלתי — \u0003משום דגריר\u0004 \u0005[ש\u0006הוא \u0005גורר\u0006 ומעורר\u0005]\u0006 את התיאבון. \u0003בעתירותי\u0004 \u0005[בעשירותי]\u0006 לא אכלתי — \u0003דאמינא\u0004 \u0005[שאמרתי]:\u0006 \u0003היכא דעייל ירקא, ליעול בשרא וכוורי\u0004 \u0005[היכן שנכנס ירק, שיכנסו בשר ודגים].\u0006","\u0003ו\u0004עוד \u0003אמר רב חסדא: בר בי רב דלא נפישא ליה ריפתא\u0004 \u0005[בן בית הרב שאין לו פת מרובה]\u0006 — \u0003לא ליבצע בצועי\u0004 \u0005[יחתכנה לחתיכות קטנות],\u0006 אלא יאכל כמה שיש לו בבת אחת. \u0003ו\u0004עוד \u0003אמר רב חסדא: בר בי רב דלא נפישא ליה ריפתא\u0004 \u0005[בן בית הרב שאין לו פת מרובה]\u0006 — \u0003לא ליבצע\u0004 \u0005[יבצע]\u0006 \u0005לאורחים.\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]?\u0006 — \u0003דלא עביד\u0004 \u0005[שאינו עושה]\u0006 \u0003בעין יפה. ו\u0004עוד \u0003אמר רב חסדא: אנא מעיקרא\u0004 \u0005[אני מתחילה]\u0006 \u0003לא הואי בצענא\u0004 \u0005[הייתי בוצע]\u0006 \u0003עד דשדאי\u0004 \u0005[שהייתי משליך,\u0006 מכניס\u0005]\u0006 \u0003ידי בכולי מנא\u0004 \u0005[בכל כלי],\u0006 \u0003ואשכחי ביה\u0004 \u0005[ומוצא בו]\u0006 \u0003כל צרכי.\u0004","\u0003ו\u0004עוד \u0003אמר רב חסדא: האי מאן\u0004 \u0005[מי]\u0006 ש\u0003אפשר ליה למיכל נהמא דשערי ואכל דחיטי\u0004 \u0005[לו לאכול\u0006 \u0005לחם שעורים ואוכל\u0006 לחם \u0005של חיטים\u0006\u0003]\u0004 — \u0003קעבר\u0004 \u0005[הריהו עובר]\u0006 \u0003משום \"בל תשחית\",\u0004 שהוא כמבזבז ללא צורך. \u0003ואמר רב פפא: האי מאן\u0004 \u0005[מי]\u0006 ש\u0003אפשר\u0004 לו \u0003למישתי שיכרא ושתי חמרא\u0004 \u0005[לשתות שכר ושותה יין]\u0006 — \u0003עובר משום \"בל תשחית\". ו\u0004אולם מעירים על דברים אלה: \u0003לאו מילתא היא\u0004 \u0005[אין זה דבר\u0006 נכון\u0005]\u0006 כי \u0003\"בל תשחית\" דגופא\u0004 \u0005[של הגוף]\u0006 \u0003עדיף,\u0004 וטוב לאדם שישמור על גופו במזון טוב מאשר ישמור על ממונו.","\u0003ו\u0004עוד \u0003אמר רב חסדא: בר בי רב דלית ליה משחא\u0004 \u0005[בן בית הרב שאין לו שמן]\u0006 — \u0003נימשי במיא דחריצי\u0004 \u0005[ירחץ,\u0006 יסוך, \u0005במי תעלות],\u0006 שהירוקת שעליהם יש בה תועלת כמו סיכה בשמן.","\u0003ו\u0004עוד \u0003אמר רב חסדא: בר בי רב דזבין אומצא\u0004 \u0005[בן בית הרב הקונה בשר]\u0006 — \u0003ליזבין אונקא, דאית ביה תלתא מיני בישרא\u0004 \u0005[שיקנה מן הצואר, שיש בו שלושה מיני בשר].\u0006","\u0003ו\u0004עוד \u0003אמר רב חסדא: בר בי רב דזבין כיתוניתא\u0004 \u0005[בן בית הרב הקונה כותונת]\u0006 — \u0003ליזבן\u0004 \u0005[שיקנה]\u0006 \u0003מ\u0004אלו שעושים ב\u0003נהר אבא, וניחוורה\u0004 \u0005[וירחצנה]\u0006 \u0003כל תלתין יומין\u0004 \u0005[שלושים ימים],\u0006 \u0003דמפטיא ליה תריסר ירחי שתא\u0004 \u0005[שתספיק לו לשנים עשר חודשי השנה],\u0006 \u0003ואנא ערבא\u0004 \u0005[ואני ערב]\u0006 שתשמר הכתונת. ומעירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כיתוניתא\"\u0004 — \u0003כיתא נאה,\u0004 שכתונת נאה מכניסה אותו לחבורה (כתה) של הלבושים כיאות.","\u0003ו\u0004עוד \u0003אמר רב חסדא: בר בי רב לא ליתיב אציפתא חדתא, דמכליא מאניה\u0004 \u0005[בן בית הרב אל ישב על מחצלת חדשה,\u0006 לפי \u0005ש\u0006היא \u0005מכלה\u0006 את \u0005בגדיו\u0006 ברטיבותה\u0005].\u0006","\u0003ו\u0004עוד \u0003אמר רב חסדא: בר בי רב לא לישדר מאניה לאושפיזיה לחווריה ליה\u0004 \u0005[בן בית הרב אל ישלח בגדיו למאכסנו לכבס לו],\u0006 \u0003דלאו אורח ארעא, דילמא חזי ביה מידי, ואתי למגניא\u0004 \u0005[שאין\u0006 זה \u0005דרך ארץ, שמא יראה בו דבר\u0006 כגון קרי, \u0005ויבוא להתגנות\u0006 בפני מארחו\u0005].\u0006","ולאחר עצותיו של רב חסדא לתלמידי חכמים מביאים עוד מעצותיו לבנותיו. ש\u0003אמר להו\u0004 \u0005[להן]\u0006 \u0003רב חסדא לבנתיה\u0004 \u0005[לבנותיו]:\u0006 \u0003תיהוי צניעתן באפי גברייכו\u0004 \u0005[היינה צנועות בפני בעליכן],\u0006 \u0003לא תיכלון נהמא באפי גברייכו\u0004 \u0005[אל תאכלו לחם בפני בעליכן],\u0006 שמא תאכלו יותר מדי ותתגנו בעיניהם.","וכן \u0003לא תיכלון ירקא בליליא\u0004 \u0005[אל תאכלו ירק בלילה],\u0006 לפי שהירק גורם לריח הפה, \u0003לא תיכלון תמרי בליליא\u0004 \u0005[אל תאכלו תמרים בלילה],\u0006 \u0003ולא תשתון שיכרא בליליא\u0004 \u0005[ואל תשתו שכר בלילה],\u0006 שכל אלה משלשלים, \u0003ולא תיפנון היכא דמפני גברייכו\u0004 \u0005[ואל תפנו\u0006 לצרכיכן \u0005במקום שנפנים בעליכן]\u0006 שלא תמאסו עליהם.","\u0003וכי קא קארי אבבא איניש\u0004 \u0005[ וכאשר קורא על הפתח אדם]\u0006 הרוצה להיכנס \u0003לא תימרון\u0004 \u0005אל תאמרון\u0006 \u0003\"מנו\"\u0004 \u0005[\"מי הוא\"],\u0006 \u0003אלא \"מני\"\u0004 \u0005[\"מיהי\"]\u0006 בלשון נקבה, שיראו שאין להן עסק עם גברים אחרים.","והואיל ורב חסדא רצה להראות להן מעלת הצניעות, \u0003נקיט מרגניתא בחדא ידיה וכורא בחדא ידיה\u0004 \u0005[והחזיק מרגלית בידו האחת ורגב בידו האחרת].\u0006 \u0003מרגניתא\u0004 — \u0003אחוי להו, וכורא\u0004 — \u0003לא אחוי להו\u0004 \u0005[את המרגלית\u0006 — \u0005הראה להן\u0006 מיד \u0005ואת הרגב\u0006 — \u0005לא הראה להן]\u0006 \u0003עד דמיצטערן\u0004 \u0005[שהצטערו],\u0006 \u0003והדר אחוי להו\u0004 \u0005[ו\u0006רק \u0005אחר כך הראה להן],\u0006 ללמדן שדבר המוצנע מושך יותר מדבר גלוי ואפילו הוא פחות בערכו ממנו.","שנינו במשנה ש\u0003אין שולין\u0004 (שורים) \u0003את הכרשינין\u0004 במים לברור אותם מפסולתם, ואולם מותר להאכיל את הבהמות כשנותן להן תבן באיבוס בתוך כברה. על כך מעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 הריהי \u0003שלא כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: אין משגיחין\u0004 בשבת \u0003בכברה כל עיקר,\u0004 ואין משתמשים בה, שמא יבוא לברור.","\u0003גורפין\u0004 את התבן \u0003מלפני הפטם\u0004 (בהמה העומדת לפיטום) \u0003ומסלקין\u0004 את התבן \u0003לצדדין מפני הרעי\u0004 (בהמה הרועה בעצמה בשדה) (ר\"ח), אלו \u0003דברי ר' דוסא. וחכמים אוסרין. נוטלין\u0004 תבן המונח \u0003מלפני בהמה זו ונותנין לפני בהמה זו בשבת.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לתלמידים\u0005]:\u0006 \u0003רבנן ארישא פליגי\u0004 \u0005[חכמים\u0006 האוסרים, האם \u0005על ראש\u0006 המשנה הם \u0005חלוקים],\u0006 \u0003או אסיפא פליגי\u0004 \u0005[על סוף\u0006 המשנה הם \u0005חלוקים],\u0006 \u0003או\u0004 שמא \u0003אתרויהו פליגי\u0004 \u0005[על שניהם\u0006 הם \u0005חלוקים]?\u0006","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005],\u0006 \u0003וחכמים אומרים: אחד זה,\u0004 תבן המונח לפני הפטם, \u0003ואחד זה,\u0004 תבן המונח לפני הרעי — \u0003לא יסלקנו לצדדין,\u0004 הרי שחולקים ואוסרים בשני המקרים.","\u0003אמר רב חסדא: מחלוקת\u0004 זו היא דווקא \u0003באיבוס של קרקע,\u0004 שעשו בקרקע כעין איבוס לתבן, \u0003אבל באיבוס של כלי\u0004 — ל\u0003דברי הכל מותר.\u0004 ותוהים: \u0003ו\u0004ב\u0003איבוס של קרקע מי איכא למאן דשרי\u0004 \u0005[האם יש מי שהתיר]?!\u0006 \u0003הא קא משוי\u0004 \u0005[הרי הוא משווה,\u0006 מיישר\u0005]\u0006 בכך \u0003גומות,\u0004 ועובר משום בונה או חורש! \u0003אלא, אי איתמר, הכי איתמר\u0004 \u0005[אם נאמר, כך נאמר]:\u0006 \u0003אמר רב חסדא מחלוקת\u0004 זו היא דווקא \u0003באיבוס של כלי, אבל באיבוס של קרקע\u0004 — \u0003לדברי הכל אסור,\u0004 שיש בכך חשש יישור גומות.","\u0003ו\u0004עוד שנינו במשנה ש\u0003נוטלין\u0004 את התבן המונח \u0003מלפני בהמה\u0004 אחת ונותנים אותו לפני בהמה אחרת. \u0003תנא חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003נוטלין מלפני בהמה שפיה יפה ונותנין לפני בהמה שפיה רע. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003נוטלין מלפני בהמה שפיה רע ונותנין לפני בהמה שפיה יפה,\u0004 והרי זו לכאורה סתירה בין הברייתות!","\u0003אמר אביי: אידי ואידי\u0004 \u0005[זה וזה]\u0006 שתי הברייתות משמען שליטול את התבן \u0005המונח\u0006 \u0003מקמי חמרא\u0004 \u0005[מלפני החמור]\u0006 ולהעבירו \u0003לקמי תורא\u0004 \u0005[לפני השור]\u0006 — \u0003שקלינן\u0004 \u0005[נוטלים אנו],\u0006 וליטולו \u0003מקמי תורא\u0004 \u0005[מלפני השור]\u0006 ולהעבירו \u0003לקמי חמרא\u0004 \u0005[לפני החמור]\u0006 — \u0003לא שקלינן\u0004 \u0005[אין נוטלים].\u0006 אלא יש לבאר את הלשון כך: \u0003והא דקתני\u0004 \u0005[וזו ששנינו]\u0006 \u0003\"נוטל מלפני בהמה שפיה יפה\"\u0004 — הכוונה היא ל\u0003חמור.\u0004 ומדוע אומרים שפיהו יפה — כי \u0003לית ליה רירי\u0004 \u0005[אין לו רירים]\u0006 ואינו מרטיב ברירו את התבן שאינו אוכל. \u0003ו\"נותנין לפני בהמה שפיה רע\"\u0004 — הכוונה ל\u0003פרה\u0004"],["\u0003דאית\u0004 \u0005[שיש]\u0006 \u0003לה רירי\u0004 \u0005[רירים].\u0006","\u0003והא דקתני\u0004 \u0005[וזו ששנינו]\u0006 \u0003\"\u0004ו\u0003נוטלין מלפני בהמה שפיה רע\"\u0004 — אף הוא כוונתו \u0003בחמור,\u0004 ואומרים שפיהו רע — \u0003דלא דייק ואכיל\u0004 \u0005[שאינו מדקדק ואוכל\u0006 הכל\u0005].\u0006 \u0003\"ונותנין לפני בהמה שפיה יפה\"\u0004 — מדובר \u0003בפרה, דדייקא ואכלה\u0004 \u0005[שמדקדקת\u0006 במה \u0005שאוכלת].\u0006","\u0003הקש ש\u0004היה צבור ומונח \u0003על גבי המטה\u0004 ורצה אדם לשכב עליו — \u0003לא ינענענו בידו,\u0004 שקש זה מן הסתם מוקצה הוא להסיק בו, \u0003אלא מנענעו\u0004 ומיישרו \u0003בגופו,\u0004 וכיון שלא עושה טלטול כדרכו — מותר. \u0003ואם היה\u0004 קש זה מוכן ל\u0003מאכל בהמה, או שהיה עליו כר או סדין\u0004 שברור שהניחו את הקש על המטה כדי לישון עליו — שוב אינו מוקצה, ו\u0003מנענעו\u0004 אפילו \u0003בידו.\u0004","הלכה אחרת אמרו: \u0003מכבש\u0004 שכובשין בו את הכביסה הלחה ליבשה ולגהצה, זה \u0003של בעלי בתים\u0004 שאינו מהודק כל כך ואין צורך בו במלאכת אומן — \u0003מתירין\u0004 בשבת להוציא ממנו בגדים, \u0003אבל לא כובשין\u0004 בו בגדים בשבת. \u0003ושל כובסין\u0004 שמיוחד למלאכה וקשירתו והתרתו מעשי אומן הן — \u0003לא יגע בו. ר' יהודה אומר: אם היה\u0004 מכבש זה של כובס \u0003מותר מערב שבת\u0004 במקצת — \u0003מתיר את כולו\u0004 בשבת \u0003ושומטו\u0004 לבגד שבתוכו.","לענין טלטול מוקצה הביאו את מה ש\u0003אמר רב נחמן : האי פוגלא\u0004 \u0005[צנון זה]\u0006 שהיה טמון בתוך העפר, אם היה טמון \u0003מלמעלה למטה,\u0004 שחלקו הרחב למעלה וחלקו הצר למטה — \u0003שרי\u0004 \u0005[מותר]\u0006 להוציאו בשבת, לפי שבאופן כזה אינו מטלטל את העפר בשעת הוצאת הצנון ממנו. אבל אם היה הצנון טמון בעפר \u0003מלמטה למעלה,\u0004 שהצד הרחב למטה — \u0003אסיר\u0004 \u0005[אסור].\u0006","\u0003אמר רב אדא בר אבא, אמרי בי\u0004 \u0005[אומרים\u0006 בני \u0005בית\u0006 מדרשו\u0005]\u0006 \u0005של\u0006 \u0003רב: תנינא\u0004 \u0005[שנינו]\u0006 ש\u0003לא\u0004 כדברי \u0003רב נחמן.\u0004 שנאמר במשנתנו ש\u0003הקש שעל גבי המטה\u0004 — \u0003לא ינענעו בידו, אבל מנענעו בגופו. ואם היה מאכל בהמה, או שהיה עליו כר או סדין\u0004 — \u0003מנענעו בידו. שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003טלטול מן הצד\u0004 שלא במעשה בידים ממש — \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 \u0003טלטול:\u0004 ומסכמים, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","ודרך אגב הביאו דבר דומה במקצת. \u0003אמר רב יהודה: הני פלפלי, מידק חדא חדא בקתא דסכינא\u0004 \u0005[פלפלים אלה, לדוכם אחד אחד בקת הסכין]\u0006 — \u0003שרי\u0004 \u0005[מותר],\u0006 \u0003תרתי\u0004 \u0005[שנים]\u0006 — \u0003אסיר\u0004 \u0005[אסור],\u0006 שנראה הדבר כמלאכה. \u0003רבא אמר: כיון דמשני\u0004 \u0005[שמשנה]\u0006 ועושה שלא בדרך המקובלת — \u0003אפילו טובא נמי\u0004 \u0005[הרבה גם כן\u0006 מותר\u0005].\u0006","ועוד \u0003אמר רב יהודה: מאן דסחי במיא\u0004 — \u0003לינגיב נפשיה ברישא, והדר ליסליק\u0004 \u0005[מי שמתרחץ במים\u0006 — \u0005שינגב עצמו בראשונה\u0006 מיד כשיוצא, \u0005ואחר יעלה\u0006 לחוף\u0005].\u0006 שאם ישארו המים עליו \u0003דילמא אתי לאתויי\u0004 \u0005[שמא יבוא להביא]\u0006 את טיפות המים שעליו \u0003ארבע אמות בכרמלית.\u0004","ושואלים \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאתה חושש לטלטול המים, \u0003כי קא נחית נמי, קא דחי\u0004 \u0005[כאשר יורד\u0006 למים \u0005גם כן, נדחה]\u0006 מ\u0003כחו\u0004 חלק מן המים \u0003ארבע אמות\u0004 בנהר, \u0003ואסיר\u0004 \u0005[ואסור]!\u0006 ומשיבים: על דבר היוצא רק מ\u0003כחו בכרמלית,\u0004 כיון שאינו עושה מעשה בעצמו אלא הדבר בא רק מכוחו־מסיבתו, ובנהר שאינו אלא כרמלית שאיסורה רק מדברי סופרים — \u0003לא גזרו\u0004 בה חכמים.","ועוד גזירה הדומה לכך \u0003אמר אביי, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר \u0003זאת רב יהודה: טיט שעל גבי רגלו\u0004 — \u0003מקנחו\u0004 בשבת \u0003בקרקע, ואין מקנחו בכותל.\u0004","\u0003אמר רבא: מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003בכותל לא\u0004 יקנח? \u0003משום דמיחזי\u0004 \u0005[שנראה]\u0006 \u0003כבונה,\u0004 שמוסיף טיט לכתלים, ואולם \u0003הא\u0004 \u0005[זה]\u0006 \u0003בנין\u0004 של \u0003חקלאה\u0004 \u0005[שדה]\u0006 \u0003הוא,\u0004 ואינו דומה כלל לבניה ממש, ואין לחוש בכגון זה.","\u0003אלא אמר רבא\u0004 להיפך: \u0003מקנחו בכותל ואין מקנחו בקרקע.\u0004 וטעמו של דבר — משום החשש \u0003דילמא אתי לאשוויי\u0004 \u0005[שמא יבוא להשוות,\u0006 ליישר\u0005]\u0006 \u0003גומות\u0004 שבקרקע, אגב ניקוי הרגל.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שהיתה מחלוקת אמוראים בדבר: \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא אמר: אחד זה ואחד זה,\u0004 בין בכותל בין בקרקע — \u0003אסור\u0004 לקנח את הטיט. \u0003רב פפא אמר: אחד זה ואחד זה\u0004 — \u0003מותר.\u0004","ושואלים: ו\u0003ל\u0004שיטת \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא במאי מקנחי ליה\u0004 \u0005[במה מקנחים אותה]\u0006 את הרגל? ומשיבים: אף לשיטתו יש היתר, \u0003מקנחי ליה\u0004 \u0005[מקנח אותה]\u0006 \u0003בקורה\u0004 המוטלת בארץ.","\u0003אמר רבא: לא ליתיב איניש אפומיה דליחייא\u0004 \u0005[אל ישב אדם\u0006 בשבת \u0005על פי הלחי],\u0006 שעושים פס צר בפתחו של מבוי שאינו מפולש כדי שיהא כעין מחיצה סמלית להתיר את הטלטול בו. וטעמו של דבר: \u0003דילמא מיגנדרא ליה\u0004 \u0005[שמא יתגלגל לו]\u0006 \u0003חפץ\u0004 לרשות הרבים \u0003ואתי לאתויי\u0004 \u0005[ויבוא להביאו],\u0006 שהרי אין הבדל ניכר לעין בין תוך המבוי וחוץ לו.","\u0003ו\u0004עוד \u0003אמר רבא\u0004 כגזירה בדברים דומים: \u0003לא ליצדד איניש כובא, דילמא אתי לאשוויי גומות\u0004 \u0005[אל יצדד,\u0006 יישר, \u0005אדם חבית, שמא יבוא ליישר גומות]\u0006 שבקרקע, כדי לתת לחבית מקום נוח וחלק יותר.","— \u0003ו\u0004עוד \u0003אמר רבא: לא ליהדוק איניש אודרא בפומא דשישא, דילמא אתי\u0004 \u0005[אל יהדק אדם\u0006 בשבת \u0005סמרטוט בפי הכד, שמא יבוא]\u0006 \u0003לידי סחיטה\u0004 של המים העשויים להישפך מתוכו.","\u0003אמר רב כהנא: טיט שעל גבי בגדו\u0004 בשבת — \u0003מכסכסו\u0004 (משפשפו) \u0003מבפנים ואין מכסכסו מבחוץ,\u0004 שהוא כעושה מלאכת מכבס.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003טיט שעל גבי מנעלו\u0004 — \u0003מגררו בגב סכין\u0004 לשם שינוי, \u0003ושעל בגדו\u0004 — \u0003מגררו בצפורן, ובלבד שלא יכסכס, מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003שלא יכסכס כלל!\u0004 ודוחים: \u0003לא\u0004 הכוונה היא \u0003שלא יכסכס מבחוץ, אלא מבפנים.\u0004","\u0003אמר ר' אבהו\u0004 שכך \u0003אמר ר' אלעזר\u0004 שכך \u0003אמר ר' ינאי: מגררין\u0004 בשבת \u0003מנעל חדש\u0004 מן הטיט שדבק בו, \u0003אבל לא\u0004 מנעל \u0003ישן,\u0004 שיש בכך משום תיקון והרי זה בכלל מלאכת ממחק."],["\u0003במה מגררו? אמר ר' אבהו:\u0004 בשינוי, \u0003בגב סכין.\u0004 \u0003אמר ליה ההוא סבא\u0004 \u0005[לו זקן אחד]\u0006 לר' אבהו: \u0003סמי דידך מקמי הא דתני\u0004 \u0005[מחוק\u0006 את ההלכה \u0005שלך מלפני\u0006 הלכה \u0005זו ששנה]\u0006 \u0003ר' חייא: אין מגררין\u0004 כלל \u0003לא מנעל חדש ולא מנעל ישן, ולא יסוך את רגלו שמן והוא בתוך המנעל או בתוך הסנדל,\u0004 ששמן זה נספג בעור הנעל ומתקנו, ואסור משום מלאכת מעבד. \u0003אבל סך\u0004 הוא \u0003את רגלו שמן\u0004 כדרכו, \u0003ומניח\u0004 כך אותה אחר כך \u0003בתוך המנעל או בתוך הסנדל,\u0004 ואינו חושש שיועיל שמן זה לעור הנעל. \u0003ו\u0004כן \u0003סך כל גופו שמן, ומתעגל\u0004 (מתגלגל) \u0003על גבי קטבליא\u0004 (שטיח של עור), \u0003ואינו חושש.\u0004","","\u0003אמר רב חסדא: לא שנו\u0004 כך \u0003אלא\u0004 כשעושה זאת כדי \u0003לצחצחו, אבל\u0004 אם עושה \u0003לעבדו\u0004 — \u0003אסור.\u0004","ותוהים: \u0003לעבדו, פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 הרי זו מלאכה האסורה מן התורה, וכי יש צורך לומר שאסור לעשותה? \u0003ותו\u0004 \u0005[ועוד]:\u0006 אם עושה כן כדי \u0003לצחצחו, מי איכא מאן דשרי\u0004 \u0005[האם יש מי שהתיר]\u0006 שיכוון אדם לעשות מלאכה לכתחילה בשבת?","\u0003אלא,\u0004 יש לדחות את הנוסח שאמרנו, ו\u0003אי איתמר הכי איתמר\u0004 \u0005[אם נאמר כך נאמר],\u0006 \u0003אמר רב חסדא: לא שנו\u0004 שמותר לעשות כך בשבת \u0003אלא\u0004 כשסך עצמו ב\u0003שיעור\u0004 שדיו כדי \u0003לצחצחו\u0004 בלבד, \u0003אבל\u0004 כשסך עצמו ב\u0003שיעור\u0004 שיש בו כדי \u0003לעבדו\u0004 — \u0003אסור,\u0004 ואפילו לא נתכוין לכך. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003לא יצא\u0004 אדם \u0003קטן\u0004 בקומה \u0003במנעל גדול\u0004 ממידתו, שמא יפול המנעל ויבוא לטלטלו ברשות הרבים. \u0003אבל יוצא הוא בחלוק גדול,\u0004 שאף שאינו כמידתו ודאי לא יפול מעליו.","","\u0003ולא תצא אשה\u0004 בשבת \u0003במנעל מרופט\u0004 (קרוע מאוד מלמעלה) שמא יצחקו עליה, ותורידנו מרגלה ותטלטל אותו בשבת. \u0003ו\u0004מנעל כזה \u0003לא תחלוץ בו\u0004 היבמה ליבם, שאינו מנעל ראוי, \u0003ואם חלצה\u0004 — \u0003חליצתה כשרה,\u0004 שהרי סוף סוף מנעל הוא.","\u0003ואין יוצאין\u0004 בשבת \u0003במנעל חדש,\u0004 שמא ימצא שאינו מכוון לרגל, ויחלצנו ויטלטלנו. ומעירים: \u0003באיזה מנעל אמרו\u0004 — \u0003במנעל של אשה,\u0004 שמקפידה ביותר על המנעל שיהיה מכוון לרגלה.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003בר קפרא: לא שנו\u0004 שלא תצא בו בשבת \u0003אלא שלא יצאה בו\u0004 עדיין \u0003שעה אחת מבעוד יום, אבל יצאה בו מערב שבת,\u0004 שוודאי מצאה אם מתאים הוא לה — \u0003מותר\u0004 לה לצאת בו בשבת.","\u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003שומטין\u0004 בשבת \u0003מנעל מעל גבי אימוס\u0004 (אימום, תבנית שעליה תופרים נעל). \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]\u0006 \u0003אין שומטין.\u0004 ומסבירים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 \u0003הא\u0004 \u0005[זו]\u0006 הברייתא האוסרת — היא כשיטת \u0003ר' אליעזר,\u0004 ו\u0003הא\u0004 \u0005[זו]\u0006 זו המתירה — כשיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006 שנחלקו ר' אליעזר וחכמים בדיני טומאה וטהרה.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מנעל ש\u0004מצוי עדיין \u0003על גבי אימוס, ר' אליעזר מטהר\u0004 אותו, שאינו מקבל טומאה, שלדעתו מנעל זה לא נגמרה מלאכתו עדיין ואינו בגדר כלי גמור המקבל טומאה, \u0003וחכמים מטמאים,\u0004 שלדעתם נגמרה מלאכתו וכל כלי שנגמרה מלאכתו יכול לקבל טומאה.","ובהתאם לעקרון זה, חכמים הסבורים שהמנעל שעל האימום הוא כלי גמור מתירים הם לטלטלו בשבת. ושואלים: \u0003הניחא\u0004 \u0005[זה נוח,\u0006 מתקבל\u0005]\u0006 \u0003ל\u0004שיטת \u0003רבא\u0004 ש\u0003אמר: דבר שמלאכתו לאיסור, בין לצורך גופו בין לצורך מקומו\u0004 — \u0003מותר\u0004 לטלטלו בשבת ממקומו, אם כן \u0003שפיר\u0004 \u0005[יפה,\u0006 מובן\u0005]\u0006 הדבר שמטלטלים מעט את האימום אגב הסרת המנעל משום שצריך למקומו של האימום.","\u0003אלא לאביי\u0004 ש\u0003אמר\u0004 ש\u0003לצורך גופו\u0004 — \u0003מותר,\u0004 ואילו \u0003לצורך מקומו\u0004 — \u0003אסור. מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי אי אפשר לטלטל את האימום שהוא במפורש כלי שמלאכתו לאסור וכיצד ישמוט את המנעל בלא טלטול האימום?","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003ברפוי.\u0004 שאפשר להוריד את הנעל מבלי להזיז את האימום. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: אם היה רפוי\u0004 — \u0003מותר.\u0004","ומדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 שהוא \u0003רפוי, הא\u0004 \u0005[הרי]\u0006 אם \u0003לא\u0004 היה \u0003רפוי\u0004 — \u0003לא\u0004 הותר. \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003אביי\u0004 ש\u0003אמר :\u0004 ש\u0003דבר שמלאכתו לאיסור, לצורך\u0004 שימוש \u0003בגופו\u0004 — \u0003מותר\u0004 לטלטלו, ואולם \u0003לצורך מקומו\u0004 — \u0003אסור\u0004 לטלטלו, \u0003שפיר\u0004 \u0005[יפה\u0006 הדבר, מותר\u0005].\u0006","\u0003אלא לרבא\u0004 ש\u0003אמר\u0004 כי \u0003בין לצורך גופו בין לצורך מקומו\u0004 — \u0003מותר, מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע רק\u0005]\u0006 \u0003רפוי? אפילו לא רפוי נמי\u0004 \u0005[גם כן]\u0006 יהא מותר לטלטלו!","ומשיבים: הברייתא \u0003ההיא\u0004 שיטת \u0003ר' יהודה משום\u0004 (בשם) \u0003ר' אליעזר הוא,\u0004 ולא ביאורה של שיטת חכמים. ואף שסבור ר' אליעזר שהמנעל עדיין לא נגמר, בכל זאת לדעת ר' יהודה בשם ר' אליעזר מותר לטלטלו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר משום ר' אליעזר : אם היה\u0004 כבר \u0003רפוי\u0004 ואינו צריך עוד לאימום — \u0003מותר\u0004 לטלטלו שהוא כלי גמור.","","\u0003נוטל אדם\u0004 בשבת \u0003את בנו\u0004 על ידיו \u0003ו\u0004אף על פי ש\u0003האבן בידו\u0004 של התינוק, ואין אוסרים ליטול את הבן משום שהוא מטלטל מוקצה על ידי כך. \u0003ו\u0004כן מטלטלים בשבת \u0003כלכלה\u0004 (סל) \u0003והאבן בתוכה. ומטלטלין תרומה טמאה\u0004 שאסור לאכול אותה ומוקצה היא מטלטול \u0003עם הטהורה, ו\u0004כן \u0003עם החולין.\u0004 \u0003ר' יהודה אומר: אף מעלין את המדומע באחד ומאה.\u0004 שאם נפלה כמות של תרומה והתערבה בתוך חולין (והוא הקרוי 'דימוע') אם היו שם מאה שיעורים כנגד הכמות שנפלה — אומרים שבטלה התרומה, אלא שתקנו חכמים שיעלה משם אותה כמות שנפלה ויתננה לכהן, והשאר נחשב כחולין. והתיר ר' יהודה להעלות את המדומע בשבת לתקנו ולהכשירו לאכילה לכול.","","\u0003אמר רבא:\u0004 מי ש\u0003הוציא\u0004 בשבת לרשות הרבים \u0003תינוק חי וכיס\u0004 (כעין שקיק לכסף) \u0003תלוי בצוארו\u0004 של התינוק — \u0003חייב משום\u0004 הוצאת \u0003כיס.\u0004 ואם הוציא \u0003תינוק מת וכיס תלוי לו בצוארו\u0004 — \u0003פטור.\u0004 ועל מה ששנינו שאם הוציא \u0003תינוק חי וכיס תלוי לו בצוארו\u0004 — \u0003חייב משום כיס,\u0004 שואלים: \u0003וליחייב נמי\u0004 \u0005[ושיתחייב\u0006 \u0003גם כן] משום\u0004 נשיאת ה\u0003תינוק\u0004 עצמו! ומשיבים: \u0003רבא כ\u0004שיטת \u0003ר' נתן סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ש\u0003אמר\u0004 ר' נתן: \u0003חי נושא את עצמו,\u0004 ולכן המוציא חי מרשות לרשות אינו חייב על הוצאתו.","","","ושואלים: \u0003וליבטל\u0004 \u0005[ושיתבטל]\u0006 ה\u0003כיס לגבי\u0004 ה\u0003תינוק,\u0004 ויהא פטור אף על הכיס. \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 שהמוציא בשבת \u0003את החי במטה\u0004 — \u0003פטור אף על\u0004 הוצאת \u0003המטה,\u0004 לפי \u0003שהמטה טפילה לו.\u0004 ומדוע לא נאמר כן לגבי הכיס והתינוק?","ומשיבים: \u0003מטה לגבי חי\u0004 — \u0003מבטלי ליה\u0004 \u0005[מבטלים אותה],\u0006 שהרי דרושה המטה להוצאתו והיא טפילה לו, ואולם \u0003כיס לגבי תינוק\u0004 — \u0003לא מבטלי ליה\u0004 \u0005[אין מבטלים אותו],\u0006 שהוא חשוב לעצמו.","אמרנו כי אם הוציא בשבת \u0003תינוק מת וכיס תלוי לו בצוארו\u0004 — \u0003פטור\u0004 על הוצאתו. ושואלים: \u0003וליחייב\u0004 \u0005[ושיתחייב]\u0006 \u0003משום\u0004 הוצאת ה\u0003תינוק\u0004 עצמו! ומשיבים: \u0003רבא כ\u0004שיטת \u0003ר' שמעון סבירא ליה\u0004 \u0005[סבור]\u0006 ש\u0003אמר : כל מלאכה שאין צריך לגופה\u0004 — \u0003פטור עליה\u0004 אם עשה אותה בשבת, ומשום כך המוציא את המת, כיון שאין מוציאו משום שהוא נזקק למת אלא לצורך המת, כגון לקבורה או שלא ישאר במקום של בזיון — אין זו מלאכה האסורה מן התורה. ועל הכיס פטור משום שמתוך צערו ואבלו מבטל הוא אותו לגבי התינוק.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003נוטל אדם\u0004 בשבת \u0003את בנו והאבן בידו,\u0004 נמצא שאנו סבורים כי האבן בטלה לתינוק ומדוע יחייבו בתינוק חי שכיס תלוי בצוארו? \u0003אמרי דבי\u0004 \u0005[אמרו\u0006 \u0003בני\u0004 \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי:\u0004 אין להבין שהאבן בטלה ואין איסור בטלטולה, אלא שמדובר כאן \u0003בתינוק שיש לו גיעגועין על אביו,\u0004 ואם לא יטלנו בידיו עלול התינוק לחלות, ומשום כך התירו לו את טלטול האבן.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006"],["\u0003מאי איריא\u0004 \u0005[מדוע שייך]\u0006 דווקא \u0003אבן, אפילו דינר נמי\u0004 \u0005[גם כן]!\u0006 ואם כן \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003אמר רבא: לא שנו אלא\u0004 שהתינוק מחזיק \u0003אבן\u0004 בידו, \u0003אבל\u0004 אם מחזיק התינוק בידו \u0003דינר\u0004 — \u0003אסור\u0004 לטלטלו עמו! ומשיבים: לא בגלל האיסור להגביה את התינוק כשדינר בידו אסרו, אלא \u0003אבן, אי\u0004 \u0005[אם]\u0006 \u0003נפלה לה\u0004 מיד התינוק — \u0003לא אתי אבוה לאיתויי\u0004 \u0005[יבוא אביו להביאה],\u0006 ואולם \u0003דינר, אי נפיל\u0004 \u0005[אם יפול]\u0006 — \u0003אתי אבוה לאתויי\u0004 \u0005[יבוא אביו להביאו].\u0006","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא: המוציא\u0004 בשבת לרשות הרבים את \u0003כליו\u0004 (בגדיו) כשהם \u0003מקופלים ומונחים על כתפו, ו\u0004כן את \u0003סנדליו וטבעותיו\u0004 כשמחזיקם \u0003בידו\u0004 (ולא על אצבעו) — \u0003חייב\u0004 משום הוצאה. \u0003ואם היה מלובש בהן\u0004 — \u0003פטור\u0004 על כולם, שהם בטלים לו.","\u0003המוציא אדם וכליו עליו, וסנדליו ברגליו, וטבעותיו בידיו,\u0004 שהוא לבוש בכל בגדיו ותכשיטיו כראוי — \u0003פטור\u0004 על הכל, \u0003ואילו הוציאן כמות שהן,\u0004 שהוציא אדם המחזיק את בגדיו בידיו — \u0003חייב\u0004 משום הוצאת הבגדים, וזה ממש כדברי רבא.","שנינו במשנה שמותר לטלטל \u0003כלכלה\u0004 (סל) \u0003והאבן בתוכה.\u0004 ושואלים; \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003תיהוי\u0004 \u0005[תהיה]\u0006 ה\u0003כלכלה בסיס לדבר האסור,\u0004 ובסיס לדבר האסור הוא עצמו מוקצה ואסור בטלטול בשבת! \u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: הכא\u0004 \u0005[כאן]\u0006 \u0003בכלכלה מלאה פירות עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שיש בכלכלה גם דברים מותרים, ואין הכלכלה בסיס לאבן לבדה. ושואלים: בכל זאת מדוע יטלטל את הכלכלה והאבן? יש דרך אחרת, \u0003ולישדינהו לפירי\u0004 \u0005[ויזרוק את הפירות],\u0006 \u0003ונישדי\u0004 \u0005[ויזרוק]\u0006 את ה\u0003אבן, ונינקטינהו\u0004 \u0005[ויקח אותם,\u0006 את הפירות\u0005]\u0006 \u0003בידים,\u0004 ולא יצטרך לטלטל אבן! ומשיבים: \u0003כ\u0004פי שאמר \u0003ר' אלעי\u0004 שכך \u0003אמר רב\u0004 בענין אחר, שמדובר שם \u0003בפירות המיטנפין, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לומר כי מדובר \u0003בפירות המיטנפין\u0004 שאם ישליכם, יתלכלכו וימאסו לאכילה.","ושואלים: \u0003ולינערינהו נעורי\u0004 \u0005[ושינערם]\u0006 עד שתהא האבן בצד אחד של הכלכלה וישליכנה משם! \u0003אמר רב חייא בר אשי\u0004 שכך \u0003אמר רבא: הכא\u0004 \u0005[כאן]\u0006 \u0003בכלכלה פחותה\u0004 (שיש בה חור) \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שה\u0003אבן\u0004 עצמה \u0003נעשית דופן לכלכלה\u0004 וסותמת את החור ולכן אינו יכול להשליכה.","שנינו במשנה ש\u0003מטלטלין תרומה\u0004 טמאה עם הטהורה. \u0003אמר רב חסדא: לא שנו אלא ש\u0004התרומה ה\u0003טהורה למטה ו\u0004ה\u0003טמאה למעלה,\u0004 שאם רצונו בטהורה חייב הוא בעל כרחו לקחת גם את הטמאה. \u0003אבל\u0004 אם ה\u0003טהורה למעלה וטמאה למטה\u0004 — \u0003שקיל ליה\u0004 \u0005[נוטל אותה]\u0006 את ה\u0003טהורה ושביק ליה\u0004 \u0005[ועוזב אותה]\u0006 את ה\u0003טמאה.\u0004","ושואלים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 ה\u0003טהורה למטה נמי\u0004 \u0005[גם כן],\u0006 \u0003לישדינהו ולינקטינהו\u0004 \u0005[שישליכם\u0006 את הפירות הטמאים \u0005ויקח אותם,\u0006 את הטהורים\u0005]!\u0006 \u0003אמר ר' אלעי\u0004 שכך \u0003אמר רב: בפירות המיטנפין עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שאי אפשר להשליכם מן הסל.","על עיקר דבריו של רב חסדא \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003מטלטלין תרומה טמאה עם הטהורה ועם החולין, בין שטהורה למעלה וטמאה למטה, בין שטמאה למעלה וטהורה למטה,\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רב חסדא!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב חסדא: מתניתין\u0004 \u0005[משנתנו],\u0006 שאמר רב חסדא שהיא מתירה רק כאשר הטהורה מלמטה, עוסקת — כשצריך את הכלכלה \u0003לצורך גופו,\u0004 שרוצה לאכול את הפירות, ואילו \u0003הברייתא\u0004 עוסקת — כשצריך את הכלכלה \u0003לצורך מקומו,\u0004 שרוצה לסלק את הסל ממקומו, ואז גם אם היה הכל תרומה טמאה מותר לו לטלטל.","ושואלים: \u0003מאי דוחקיה\u0004 \u0005[מה דוחקו]\u0006 של \u0003רב חסדא לאוקמי מתניתין\u0004 \u0005[להעמיד\u0006 את \u0005המשנה]\u0006 ולהסבירה בשצריך את הכלכלה \u0003לצורך גופו,\u0004 ומדוע לא יפרש שהיא מדברת בכל מקרה שהוא?","\u0003אמר רבא: מתניתין כוותיה דייקא, דקתני סיפא\u0004 \u0005[משנתנו כשיטתו\u0006 היא \u0005מדוייקת, ששנוי בסופה]\u0006 במשנה הבאה: \u0003מעות שעל הכר\u0004 — \u0003מנער את הכר והן נופלות. ואמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: לא שנו\u0004 שמנער \u0003את הכר אלא\u0004 כשצריך את הכר \u0003לצורך גופו, אבל\u0004 כשצריך אותו \u0003לצורך מקומו\u0004 — \u0003מטלטלו, ו\u0004אף על פי שהמעות \u0003עודן עליו. ומדסיפא\u0004 \u0005[ומכיון\u0006 \u0003שסופה\u0004 של המשנה\u0005]\u0006 בשצריך את החפץ (הכר) \u0003לצורך גופו\u0004 — \u0003רישא נמי\u0004 \u0005[ראשה גם כן]\u0006 בשצריך את החפץ (הכלכלה) \u0003לצורך גופו.\u0004","שנינו במשנה ש\u0003ר' יהודה אומר: אף מעלין\u0004 את התרומה המדומעת באחד ומאה. ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]?!\u0006 \u0003הא קא\u0004 \u0005[\u0006הרי בכך \u0005הוא]\u0006 \u0003מתקן,\u0004 וכל תיקון גזרו בו חכמים שלא יעשנו בשבת!","ומשיבים: לדעתו אין בכך תיקון, כי \u0003ר' יהודה כ\u0004שיטת \u0003ר' אליעזר סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ש\u0003אמר : תרומה בעינא מחתא\u0004 \u0005[התרומה בעינה\u0006 היא \u0005מוטלת]\u0006 ואינה נחשבת כמעורבת, אלא מניחים שלא היתה תערובת כלל, ואותה כמות שהוא מעלה — היא היא אותה תרומה שנפלה.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 סאה \u0003תרומה שנפלה ל\u0004מקום שהיו בו \u0003פחות ממאה\u0004 שיעורים כמותו, \u0003ונדמעו\u0004 (נתערבו), וכיון שהיו פחות ממאה לא ביטלו את הסאה שנפלה לתוכן, \u0003ונפל מן המדומע למקום אחר, ר' אליעזר אומר: מדמעת\u0004 הסאה שנפלה מן התערובת \u0003כתרומת ודאי,\u0004 שאנו חוששים שמא סאת התרומה שנפלה מתחילה, היא שנפלה שנית ולא נתערבה כלל, וצריכה ביטול התרומה.","\u0003וחכמים אומרים: אין המדומע מדמע\u0004 שנית \u0003אלא לפי חשבון.\u0004 כלומר, כל סאה מן המדומע נחשבת כמעורבת היטב ויש בה רק אחוז מסויים של תרומה, לפי חשבון התרומה שנפלה, ויש צורך לבטל רק כנגד אחוז זה של אותה תרומה המצוי בתערובת שנפלה. ונראה ששיטת ר' אליעזר היא שהתרומה שנפלה אינה נחשבת כמעורבת אלא כאילו היתה כמוטלת לעצמה ודומה הדבר לשיטת ר' יהודה, שאין תיקון בהעלאה מן המדומע.","ודוחים: \u0003אימר דשמעת ליה\u0004 \u0005[אמור ששמעת אותו]\u0006 את ר' אליעזר לענין זה רק \u0003לחומרא\u0004 \u0005[\u0006לענין \u0005להחמיר],\u0006 ואולם \u0003לקולא מי שמעת ליה\u0004 \u0005[להקל האם שמעת אותו]\u0006 שמחזיק בסברה זו?! שאמנם חושש הוא שמא לא נתערבה התרומה שנפלה ואוסר משום כך את החולין, אבל אינו בטוח בכך עד כדי להתיר מטעם זה.","\u0003אלא\u0004 נדחה הסבר זה, ומציעים: ר' יהודה \u0003הוא\u0004 ש\u0003אמר\u0004 את דבריו \u0003כ\u0004שיטת \u0003ר' שמעון, כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003סאה\u0004 פירות \u0003תרומה שנפלה למאה\u0004 סאים של חולין, \u0003ולא הספיק להגביה\u0004 סאה מן המדומע \u0003עד שנפלה\u0004 לשם סאה \u0003אחרת\u0004 של תרומה — \u0003הרי זו,\u0004 כל התערובת כולה, \u0003אסורה,\u0004 שיש בה סאתים תרומה למאה סאים חולין. \u0003ור' שמעון מתיר.\u0004 נמצא שסבור ר' שמעון שהסאה הראשונה שנפלה אין דינה כמעורבת, אלא כמונחת במקומה, וכשנפלה השניה אף היא כמונחת במקום מיוחד, ואינן מצטרפות יחד.","את ההשוואה דוחים: \u0003וממאי\u0004 \u0005[וממה]\u0006 מסיק אתה שזה הוא בסיס המחלוקת? \u0003דילמא התם בהא קמיפלגי\u0004 \u0005[שמא שם ב\u0006דבר \u0005זה נחלקו],\u0006 שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]\u0006 כי \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003נפלו\u0004 שתי הסאים של תרומה \u0003בזה אחר זה\u0004 — \u0003כמאן\u0004 \u0005[כמי]\u0006 ש\u0003נפל בבת אחת דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006 \u0003והא לחמשין\u0004 \u0005[וזו לחמישים\u0006 סאים\u0005]\u0006 \u0003נפלה, והא לחמשין\u0004 \u0005[וזו לחמישים\u0006 סאים\u0005]\u0006 \u0003נפלה,\u0004 ואינן בטלות בחמישים בלבד. \u0003ו\u0004אילו \u0003ר' שמעון סבר\u0004 \u0005[סבור]:\u0006 \u0003קמייתא בטיל\u0004 \u0005[הראשונה בטלה]\u0006 מיד עם נפילתה \u0003במאה, והא תיבטיל\u0004 \u0005[וזו\u0006 השניה \u0005תיבטל]\u0006 \u0003במאה וחד\u0004 \u0005[ואחד],\u0006 ואין כל קשר למחלוקת זו עם השיטה שהמעלה את המדומע לא עשה ולא כלום.","\u0003אלא\u0004 דוחים הסבר זה, ומציעים: שר' יהודה \u0003הוא\u0004 ש\u0003אמר כ\u0004שיטת \u0003ר' שמעון בן אלעזר. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר:\u0004 אין אדם צריך להפריש מיד סאה אחת מן המדומע אלא דיו ש\u0003נותן עיניו בצד זה\u0004 ומחליט בלבו להפריש מפירות הנמצאים באותו צד, \u0003ואוכל מצד אחר\u0004 ויפריש אחר כך. נמצא שהעלאת הסאה מן המדומע אין בה תיקון, שהרי אף בלא העלאה מותר לאכול מן המדומע והוא טעמו של ר' יהודה.","ומקשים: \u0003ומי סבר ליה כוותיה\u0004 \u0005[והאם סבור\u0006 ר' יהודה \u0005כשיטתו]?\u0006"],["\u0003והא מיפליג פליג עילויה\u0004 \u0005[והרי\u0006 הוא \u0005חולק עליו],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: מעלין את המדומע באחד ומאה. ר' שמעון בן אלעזר אומר: נותן עיניו בצד זה ואוכל מצד אחר.\u0004","ודוחים: בכל זאת בעיקרו של דבר מסכימים שני התנאים, אלא שהשיטה של \u0003ר' יהודה עדיפא\u0004 \u0005[עדיפה,\u0006 קיצונית\u0005]\u0006 \u0003מ\u0004שיטת \u0003ר' שמעון בן אלעזר,\u0004 שר' יהודה אומר שמאחר שמחשבה מספקת הרי אין תיקון בהעלאה, ומוטב שיעשה אותה אפילו בשבת.","\u0003האבן ש\u0004היתה מונחת \u0003על פי החביות\u0004 שאסור לטלטלה משום מוקצה — \u0003מטה\u0004 את החבית \u0003על צדה, והיא,\u0004 האבן, \u0003נופלת. היתה\u0004 החבית \u0003בין החביות,\u0004 ואם תיפול האבן עלולה לשבור את החביות האחרות — \u0003מגביה\u0004 חבית זו ומוציאה מבין החביות \u0003ו\u0004אחר \u0003מטה על צדה, והיא,\u0004 האבן, \u0003נופלת.\u0004","\u0003מעות ש\u0004היו \u0003על הכר\u0004 — \u0003מנער את הכר והן נופלות. היתה עליו\u0004 על הכר \u0003לשלשת\u0004 (צואת עופות. ערוך) — \u0003מקנחה בסמרטוט,\u0004 אבל אינו רוחצה במים משום איסור כיבוס. ואם \u0003היתה\u0004 הכר \u0003של עור\u0004 שאין בו חשש כיבוס — \u0003נותנין עליה מים עד שתכלה\u0004 הלשלשת.","\u0003אמר רב הונא\u0004 שכך \u0003אמר רב: לא שנו\u0004 הלכה זו באבן \u0003אלא בשוכח\u0004 את האבן על החבית, \u0003אבל במניח\u0004 מדעתו — \u0003נעשה\u0004 החבית \u0003בסיס לדבר האסור,\u0004 ואף היא בעצמה אסורה בטלטול כל השבת.","שנינו במשנה שאם \u0003היתה\u0004 החבית שעל גביה מונחת האבן עומדת \u0003בין החביות\u0004 — מגביהה ואחר משליך מעליה את האבן. ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור שב\u0003כל היכא דאיכא איסורא והיתרא\u0004 \u0005[מקום שיש איסור והיתר]\u0006 — \u0003בהיתרא טרחינן, באיסורא לא טרחינן\u0004 \u0005[בהיתר אנו טורחים, באיסור אין טורחים]?\u0006 שהרי מטריחים את האיש להגביה את החבית ואין מתירים לו לקחת את האבן, ולמעט בטירחה.","\u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן:\u0004 שיטת \u0003רבן שמעון בן גמליאל היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הבורר קטנית ביום טוב, בית שמאי אומרים: בורר אוכל\u0004 (הראוי לאכילה) \u0003ואוכל\u0004 אותו מיד ומשאיר את הפסולת. \u0003ובית הלל אומרים: בורר כדרכו,\u0004 ואף יכול להשליך את הפסולת ולהשאיר את האוכל \u0003בחיקו ובתמחוי\u0004 (כלי גדול).","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר רבן שמעון בן גמליאל: במה דברים אמורים\u0004 שנחלקו בית שמאי ובית הלל — באופן \u0003שהאוכל מרובה על הפסולת. אבל\u0004 אם ה\u0003פסולת מרובה על האוכל\u0004 — ל\u0003דברי הכל בורר אוכל,\u0004 שלא להרבות בטירחה בטלטול הפסולת שהיא בדבר האסור בטלטול כשלעצמו. וכן הוא כאן שמתירים לטלטל את החבית ולא את האבן, שהיא כפסולת.","ומקשים: \u0003והא הכא, דכי\u0004 \u0005[והרי כאן, שכמו]\u0006 \u0003אוכל מרובה על הפסולת דמי\u0004 \u0005[נחשב],\u0006 שהרי החבית שהיא אוכל גדולה וכבדה מן האבן, וקל יותר להזיז את האבן, ובכל זאת אין מתירים לעשות זאת על פי שיטת בית הלל!","ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 \u0003כיון דאי בעי למישקל לא משתקיל ליה\u0004 \u0005[שאם רוצה ליטול\u0006 את היין \u0005אין יכול להילקח]\u0006 ה\u0003יין עד דשקיל לה\u0004 \u0005[שיטול אותה],\u0006 את ה\u0003אבן\u0004 — הרי \u0003כפסולת מרובה על האוכל דמי\u0004 \u0005[נחשב],\u0006 ואין הדבר דומה לברירה, לפי שכאן עליו לטלטל בכל אופן את האבן שאינו יכול לקחת את החבית לעצמה.","שנינו במשנה שאם \u0003היתה\u0004 החבית עליה מונחת האבן עומדת \u0003בין החביות\u0004 — \u0003מגביה\u0004 את החבית. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי אומר: היתה החבית מונחת באוצר\u0004 (מחסן) בין חביות אחרות, \u0003או שהיו כלי זכוכית מונחין תחתיה,\u0004 שאינו יכול להטותה על צדה ולהפיל את האבן — \u0003מגביה\u0004 אותה ומעבירה \u0003למקום אחר, ומטה על צדה, והיא,\u0004 האבן, \u0003נופלת. ונוטל הימנה\u0004 (ממנה, מן החבית) \u0003מה שצריך לו, ומחזירה למקומה.\u0004","שנינו במשנה ש\u0003מעות ש\u0004היו מונחות \u0003על הכר\u0004 — מנער את הכר והן נופלות. \u0003אמר רב חייא בר אשי\u0004 שכך \u0003אמר רב: לא שנו אלא בשוכח\u0004 את המעות על הכר, \u0003אבל במניח\u0004 — \u0003נעשה\u0004 הכר עצמו \u0003בסיס לדבר האסור\u0004 ואין לטלטלו כלל.","\u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: לא שנו\u0004 דין של ניעור \u0003אלא\u0004 שצריך את הכר \u0003לצורך\u0004 שימוש ב\u0003גופו, אבל\u0004 שצריך אותו \u0003לצורך מקומו\u0004 — \u0003מטלטלו ועודן\u0004 (המעות) \u0003עליו. וכן תני\u0004 \u0005[שנה]\u0006 בברייתא \u0003חייא בר רב מדיפתי: לא שנו\u0004 דין של ניעור \u0003אלא\u0004 שצריך את הכר \u0003לצורך\u0004 שימוש ב\u0003גופו, אבל\u0004 כשצריך אותו \u0003לצורך מקומו\u0004 — \u0003מטלטלו ועודן עליו.\u0004","שנינו במשנתנו: \u0003מעות שעל הכר\u0004 — מנער את הכר והן נופלות. ובענין זה \u0003אמר ר' אושעיא: שכח\u0004 בערב שבת \u0003ארנקי\u0004 (ארנק) של כסף \u0003בחצר\u0004 ובשבת נזכר בו ורוצה להכניסו לבית — \u0003מניח עליה ככר\u0004 לחם \u0003או תינוק ומטלטלה,\u0004 שנעשה הארנק כבסיס לדברים שמותר לטלטלם. וכן \u0003אמר רב יצחק:\u0004 אם \u0003שכח לבינה בחצר\u0004 — \u0003מניח עליה ככר או תינוק, ומטלטלה. אמר ר' יהודה בר שילא\u0004 שכך \u0003אמר ר' אסי: פעם אחת שכחו דסקיא\u0004 (שק כפול) \u0003מלאה מעות בסרטיא\u0004 \u0005[ברחוב],\u0006 \u0003ובאו ושאלו את ר' יוחנן, ואמר להן: הניחו עליה ככר או תינוק, וטלטלוה.\u0004","\u0003אמר מר זוטרא: הלכתא ככל הני שמעתתא\u0004 \u0005[הלכה ככל האמרות הללו]\u0006 \u0003בשוכח,\u0004 אבל אם הניח מדעת אפילו חפץ יקר בערב שבת — אסור לטלטלו למחרת על ידי הערמה זו. \u0003רב אשי אמר: אפילו\u0004 ב\u0003שכח נמי\u0004 \u0005[גם כן]\u0006 — \u0003לא\u0004 התירו, \u0003ולא אמרו\u0004 היתר טלטול על ידי הנחת \u0003ככר או תינוק אלא ל\u0004טלטול \u0003מת בלבד.\u0004","ומסופר: \u0003אביי מנח כפא אכיפי\u0004 \u0005[היה מניח כף על עומרים\u0006 של תבואה\u0005]\u0006 כדי לטלטלם בשבת אגב הכף. \u0003רבא מנח סכינא אבר יונה ומטלטלה\u0004 \u0005[היה מניח סכין על בן יונה\u0006 שחוט \u0005ומטלטלו].\u0006 \u0003אמר רב יוסף\u0004 בלגלוג: \u0003כמה חריפא שמעתתא דדרדקי\u0004 \u0005[חריפה ההלכה של התינוקות,\u0006 התלמידים\u0005]!\u0006 \u0003אימר דאמור רבנן\u0004 \u0005[אמור שאמרו חכמים]\u0006 היתר זה דווקא \u0003בשוכח,\u0004 ואולם לעשות כך \u0003מלכתחילה מי אמור\u0004 \u0005[האם אמרו]?!\u0006","\u0003אמר אביי\u0004 והסביר את עצמו: \u0003אי לאו\u0004 \u0005[אם לא]\u0006 ש\u0003אדם חשוב אנא\u0004 \u0005[אני],\u0006 \u0003כפא אכיפי\u0004 \u0005[כף על העומרים]\u0006 \u0003למה לי? הא חזו למיזגא עלייהו\u0004 \u0005[הרי ראויים\u0006 הם \u0005להישען עליהם]\u0006 ויכול הייתי לטלטל את העומרים גם בלא נתינת הכף! אלא כיון שהחמרתי על עצמי עשיתי עוד פעולה נוספת שלא ילמדו ממנו להתיר.","וכן \u0003אמר רבא: אנא\u0004 \u0005[אני],\u0006 \u0003אי לאו\u0004 \u0005[אם לא]\u0006 ש\u0003אדם חשוב אנא\u0004 \u0005[אני]\u0006 — \u0003סכינא אבר יונה\u0004 \u0005[סכין על בן יונה]\u0006 \u0003למה לי? הא חזי\u0004 \u0005[הרי ראוי]\u0006 \u0003לי לאומצא\u0004 \u0005[ל\u0006אוכלו כ\u0005בשר חי].\u0006","ומקשים: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא — \u0003דחזי לאומצא\u0004 \u0005[שראוי\u0006 מכל מקום לאכילה כשהוא \u0005חי],\u0006 \u0003הא לא חזי לאומצא\u0004 \u0005[הרי\u0006 אם \u0005אינו ראוי ל\u0006אכילה כשהוא \u0005חי]\u0006 — \u0003לא. למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003רבא כר' יהודה\u0004 שאין מטלטלים בשבת מאכל שנועד מתחילה לאדם כשהוא ראוי עתה לאכילת בעלי חיים בלבד?","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא לשמעיה\u0004 \u0005[לשמשו]\u0006 ביום טוב: \u0003טווי לי בר אווזא, ושדי מיעיה לשונרא\u0004 \u0005[צלה לי ברווז וזרוק את מעיו לחתול],\u0006 ונמצא שהתיר לטלטל את מעי הברווז לצורך החתול, ובאותו אופן היה צריך להתיר טלטול בן יונה לא משום אומצא, אלא משום שהוא ראוי לאכילת כלב."],["אלא יש לומר כי \u0003התם\u0004 \u0005[שם]\u0006 \u0003כיון דמסרח\u0004 \u0005[שמסריחים]\u0006 המעיים אם משהה אותם, ואם כן \u0003דעתיה עילויה\u0004 \u0005[דעתו עליהם]\u0006 כבר \u0003מאתמול,\u0004 מבעוד יום ליעדם לחתול.","ומוסיפים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר ש\u0003רבא כר' יהודה סבירא ליה\u0004 \u0005[סבור הוא],\u0006 שכן \u0003דרש רבא: אשה לא תכנס\u0004 ביום טוב \u0003לבית\u0004 (מחסן) \u0003העצים ליטול מהן אוד\u0004 (קרש לחתות בו את האש). \u0003ואוד שנשבר\u0004 — \u0003אסור להסיקו ביום טוב, לפי שמסיקין\u0004 ביום טוב \u0003בכלים\u0004 שהם מותרים בטלטול, \u0003ואין מסיקין בשברי כלים\u0004 שנשברו בו ביום, שהם אסורים משום מוקצה. \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שקיבל רבא את שיטת ר' יהודה בדיני מוקצה. \u0003בית שמאי אומרים: מעבירין\u0004 (מורידים) בידים \u0003מעל השלחן\u0004 שאכלו עליו \u0003עצמות וקליפין\u0004 (קליפות) שנותרו עליו מן הסעודה בשבת. \u0003ובית הלל אומרים: מסלק את הטבלא כולה\u0004 של כיסוי השולחן \u0003ומנערה,\u0004 אבל לא יטול עצמות בידים, שאסור לטלטלן משום מוקצה.","","\u0003מעבירין מלפני השלחן פירורין\u0004 של לחם אפילו שיעורם \u0003פחות מכזית, ושער של אפונין ושער עדשים\u0004 (חלקי הצמח הדקים הדומים לשערות), שאף שאינם ראויים למאכל אדם מותר לטלטלם \u0003מפני שהוא מאכל בהמה.\u0004","ואמרו עוד: \u0003ספוג, אם יש לו עור בית אחיזה\u0004 — \u0003מקנחין בו\u0004 את השולחן, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין מקנחין בו,\u0004 שמא יבוא בשעת אחיזתו לסחוט ממנו את הנוזל. \u0003וחכמים אומרים: בין כך ובין כך,\u0004 גם אם אין לו בית אחיזה, \u0003ניטל בשבת\u0004 כשהוא יבש, \u0003ואינו מקבל טומאה,\u0004 לפי שאין הספוג בין החומרים המקבלים טומאה לא מדברי תורה ולא מדברי סופרים.","\u0003אמר רב נחמן: אנו\u0004 איננו מקבלים את הגירסה הזאת שבמשנה ו\u0003אין לנו אלא\u0004 שיטה זו: \u0003בית שמאי כ\u0004שיטת \u0003ר' יהודה\u0004 סבורים הם, ולכן הם אוסרים טלטול מוקצה. \u0003ובית הלל כ\u0004שיטת \u0003ר' שמעון\u0004 שאינו סובר דין מוקצה סבורים הם. ולפי זה צריך להפוך את שיטות בית שמאי ובית הלל שבמשנה.","שנינו במשנה ש\u0003מעבירין\u0004 בשבת \u0003מלפני השלחן פירורין.\u0004 ומעירים: דבר זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003ל\u0004שיטת \u0003ר' יוחנן.\u0004 ש\u0003אמר ר' יוחנן : פירורין\u0004 אף על פי \u0003שאין בהן כזית\u0004 — \u0003אסור לאבדן ביד\u0004 משום כבוד האוכלים.","בהמשך המשנה שנינו ש\u0003שער של אפונין\u0004 ועדשים מותרים בטלטול בשבת, ושואלים: \u0003מני\u0004 \u0005[של מי היא]\u0006 משנה זו? — כשיטת \u0003ר' שמעון היא, דלית ליה\u0004 \u0005[שאין לו,\u0006 שאינו מקבל\u0005]\u0006 איסור \u0003מוקצה,\u0004","\u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003ספוג, אם יש לו בית אחיזה\u0004 — \u0003מקנחין בו, ואם לאו\u0004 \u0005[לא]\u0006 \u0003אין מקנחין בו. אתאן\u0004 \u0005[הגענו]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה\u0004 ש\u0003אמר : דבר שאין מתכוין\u0004 — \u0003אסור\u0004\u0003,\u0004 שהרי בודאי אינו מתכוין לסחוט את הנוזלים מן הספוג!","ומשיבים: \u0003בהא\u0004 \u0005[בזה]\u0006 \u0003אפילו ר' שמעון מודה\u0004 שאסור, שכן \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מודה ר' שמעון ב\"פסיק רישיה\u0004 \u0005[חתוך ראשו]\u0006 \u0003ולא ימות\",\u0004 שכאשר התוצאה מחוייבת מן המעשה אף ר' שמעון מודה שגם כשאינו מתכוין אסור, ולכן אסור לקנח בספוג כזה.","\u0003הני גרעינין דתמרי ארמייתא שרו לטלטולינהו\u0004 \u0005[אותם גרעינים של תמרים ארמיים\u0006 שאינם משובחים ולעתים ניתנים לבהמה, \u0005מותר לטלטלם],\u0006 \u0003הואיל וחזיין\u0004 \u0005[וראויים]\u0006 התמרים \u0003אגב אמן,\u0004 התמר השלם, שהרי היו מוכנים לבהמה אף קודם לכן. \u0003ודפרסייתא\u0004 \u0005[ו\u0006גרעינים \u0005של\u0006 תמרים \u0005פרסיים]\u0006 — \u0003אסור,\u0004 שאין התמרים מוכנים לבהמה, והגרעינים לא היו מוכנים לצורך זה.","ומסופר כי \u0003שמואל\u0004 היה \u0003מטלטל להו\u0004 \u0005[להן]\u0006 \u0003אגב ריפתא\u0004 \u0005[לחם].\u0006 (אותיות \u0003שרנ\"ם שפ\"ז\u0004 הם \u0003סימן\u0004 לחכמים המוזכרים: \u0003ש\u0004מואל, \u0003ר\u0004בה, הו\u0003נ\u0004א, א\u0003מ\u0004ימר, \u0003ש\u0004שת, \u0003פ\u0004פא, \u0003ז\u0004כריה). ומעירים כי \u0003שמואל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר שמואל: עושה אדם כל צרכו בפת\u0004 ואינו סבור שיש בכך ביזוי הפת, אם אפשר יהא לאכלה אחר כך.","\u0003רבה\u0004 היה \u0003מטלטל להו\u0004 \u0005[אותם]\u0006 \u0003אגב לקנא דמיא\u0004 \u0005[ספל מים].\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע עביד להו\u0004 \u0005[היה עושה אותם]\u0006 \u0003כגרף של ריעי,\u0004 שהרי התירו חכמים ליטול כלי מאוס של צואה מלפניו, ואף כאן היה שם את כל גרעיני התמרים יחד וזורקם אחר כך משום מאיסות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: וכי עושין גרף של ריעי לכתחילה?\u0004 שאמנם התירו לטלטל גרף של ריעי המונח לפניו, אבל לא התירו לעשות לכתחילה דבר שייחשב אחר כך כגרף של ריעי כדי להתיר לעצמו לטלטלו.","\u0003רב ששת זריק להו בלישניה\u0004 \u0005[היה זורק אותם\u0006 את הגרעינים \u0005בלשונו].\u0006 \u0003רב פפא זריק להו\u0004 \u0005[היה זורק אותם]\u0006 \u0003אחורי המטה\u0004 שהיה מסב עליה בשעת אכילה, כי לא רצה לטלטלם בדרך אחרת. \u0003אמרו עליו על\u0004 החכם \u0003ר' זכריה בן אבקולס שהיה מחזיר פניו אחורי המטה וזורקן.\u0004",""],["\u0003חבית\u0004 יין או שמן \u0003שנשברה\u0004 בשבת \u0003מצילין הימנה\u0004 (ממנה) \u0003מזון שלש סעודות, ואומר לאחרים: באו והצילו לכם\u0004 (עבורכם). \u0003ובלבד שלא יספוג\u0004 את היין או השמן בספוג או במטלית משום איסור סחיטה. \u0003אין סוחטין את הפירות\u0004 בשבת \u0003כדי להוציא מהן משקין. ואם יצאו\u0004 המשקים \u0003מעצמן\u0004 — \u0003אסורין\u0004 להשתמש בהם בשבת. \u0003ר' יהודה אומר: אם לאוכלין\u0004 (לאכילה) הוכנו הפירות — הרי המשקה \u0003היוצא מהן\u0004 בשבת \u0003מותר,\u0004 שכן אין לחשוש שמא יבוא לכתחילה לסחוט פירות שנועדו לאכילה. \u0003ואם\u0004 נועדו מתחילה הפירות \u0003למשקין\u0004 — המשקה \u0003היוצא מהן\u0004 בשבת \u0003אסור. חלות דבש שריסקן מערב שבת, ויצאו\u0004 הדבש והשעוה \u0003מעצמן\u0004 בשבת — \u0003אסורין, ור' אליעזר מתיר.\u0004","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: \u0003לא יספוג ביין ולא יטפח\u0004 (ישים ידו ויספיגנה) \u0003בשמן, שלא יעשה כדרך שהוא עושה בחול. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא כעין זה: \u0003נתפזרו לו\u0004 בשבת \u0003פירות בחצר\u0004 — \u0003מלקט על יד על יד,\u0004 כלומר, מיד, \u0003ואוכל, אבל לא\u0004 ילקט \u0003לתוך הסל ולא לתוך הקופה, שלא יעשה כדרך שהוא עושה בחול.\u0004","שנינו במשנה כי \u0003אין סוחטין את הפירות\u0004 בשבת, ומשקים שיצאו מהם מעצמם — אסורים. ור' יהודה מבדיל בין אם נועדו הפירות מתחילה לאכילה שמותר, או שנועדו למשקים שאסור. \u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: מודה היה ר' יהודה לחכמים בזיתים וענבים\u0004 שאפילו הועידם לאכילה, שהמשקים היוצאים מהם אסורים. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003כיון\u0004 ש\u0003לסחיטה נינהו\u0004 \u0005[הם]\u0006 נועדים כרגיל — \u0003יהיב דעתיה\u0004 \u0005[נתן דעתו]\u0006 עליהם מתחילה שישמשו גם לצורך זה. \u0003ועולא אמר\u0004 בשם \u0003רב: חלוק היה ר' יהודה אף בזיתים וענבים. ור' יוחנן אמר: הלכה כר' יהודה בשאר פירות, ואין הלכה כר' יהודה בזיתים וענבים.\u0004","\u0003אמר רבה\u0004 שכך \u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: מודה היה ר' יהודה לחכמים בזיתים וענבים, ומודים חכמים לר' יהודה בשאר פירות.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' אבא:\u0004 אם כן, שמודים הם זה לזה, \u0003אלא במאי פליגי\u0004 \u0005[במה נחלקו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לר' אבא: \u0003לכי תשכח\u0004 \u0005[לכאשר תמצא],\u0006 כלומר, עיין ותמצא דברים שיש בהם מקום למחלוקת. \u0003אמר רב נחמן בר יצחק: מסתברא\u0004 \u0005[מסתבר]\u0006 לומר כי \u0003בתותים ורמונים פליגי\u0004 \u0005[נחלקו],\u0006 שהם מקרה ביניים בין פירות סתם וזיתים וענבים.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003זיתים שמשך\u0004 (סחט) \u0003מהן שמן\u0004 מבעוד יום (תוס'), \u0003ו\u0004כן \u0003ענבים שמשך מהן יין, והכניסן\u0004 אחר כך לביתו, \u0003בין\u0004 שהכניסן \u0003ל\u0004צורך \u0003אוכל, בין\u0004 שהכניסן \u0003ל\u0004צורך \u0003משקין\u0004 — \u0003היוצא מהן\u0004 מעצמו בשבת \u0003אסור.\u0004 ואילו \u0003תותים שמשך מהן מים\u0004 (מיץ תותים), \u0003ורמונים שמשך מהן יין\u0004 (מיץ רמונים), \u0003והכניסן,\u0004 יש לחלק: אם הכניסן מתחילה \u0003לאוכלין\u0004 — \u0003היוצא מהן מותר.\u0004 הכניסן \u0003למשקין,\u0004 וכן אם הכניסן \u0003לסתם\u0004 בלא לפרש את כוונתו — \u0003היוצא מהן אסור,\u0004 אלו \u0003דברי ר' יהודה. וחכמים אומרים: בין\u0004 הכניסן \u0003לאוכלין בין למשקין\u0004 — \u0003היוצא מהן אסור.\u0004","על הברייתא הזו מקשים: \u0003וסבר\u0004 \u0005[ו\u0006כי \u0005סבור]\u0006 \u0003ר' יהודה\u0004 ש\u0003סתם,\u0004 כלומר, דבר שלא נועד למטרה מסויימת הרי הוא \u0003אסור?! והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003חלב האשה מטמא לרצון ושלא לרצון,\u0004 כלומר חלב האשה בין שיצא ממנה לרצונה, בין שיצא שלא ברצונה — נחשב כמשקה ומכשיר, ודברי מאכל שנפל עליהם חלב זה נעשים מוכשרים לקבל טומאה. ואילו \u0003חלב בהמה אינו מטמא אלא לרצון,\u0004 שאם יצא מעצמו ללא חליבה — אינו מכשיר לטומאה.","\u0003אמר ר' עקיבא:\u0004 אפשר לומר כי \u0003קל וחומר הוא,\u0004 שאין הדבר כן, \u0003ומה חלב האשה שאינו מיוחד אלא ל\u0004ילדים \u0003קטנים\u0004 נחשב כמשקה, ו\u0003מטמא לרצון ושלא לרצון, חלב הבהמה\u0004 שהוא משקה מקובל, \u0003שמיוחד בין לקטנים בין לגדולים, אינו דין שיטמא בין לרצון ובין שלא לרצון? אמרו לו:\u0004 יש מקום לסתור קל וחומר זה, כך: \u0003אם\u0004 ראינו ש\u0003טמא חלב האשה שלא לרצון, ש\u0004כן אף \u0003דם מגפתה\u0004 (דם היוצא מפצע שלה), גם הוא \u0003טמא\u0004 (מכשיר לקבל טומאה) כמשקה, ואולם אין לומר ש\u0003יטמא חלב הבהמה\u0004"],["\u0003לא לרצון, ש\u0004כן \u0003דם מגפתה\u0004 של הבהמה \u0003טהור\u0004 (אינו מכשיר לקבל \u0003טומאה). אמר להן\u0004 ר' עקיבא: \u0003מחמיר אני בחלב מבדם, שהחולב לרפואה\u0004 — \u0003טמא,\u0004 שהחלב היוצא מחליבה זו מכשיר לקבל טומאה, \u0003ו\u0004אילו \u0003המקיז\u0004 דם \u0003לרפואה\u0004 — אין הדם נחשב למשקה, ו\u0003טהור. אמרו לו: סלי זיתים וענבים יוכיחו, שהמשקין היוצאין מהן לרצון\u0004 — \u0003טמאין,\u0004 ו\u0003שלא לרצון\u0004 — \u0003טהורים.\u0004 נמצא שהכל תלוי אם המשקה יוצא לרצון, ומשקה היוצא שלא לרצון טהור.","ולענייננו \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003\"לרצון\"\u0004 משמעו — \u0003דניחא ליה\u0004 \u0005[שנוח לו,\u0006 שהוא רוצה בכך\u0005],\u0006 ו\u0003שלא לרצון\u0004 — \u0003בסתמא\u0004 \u0005[בסתם]\u0006 שלא גילה דעתו, ומעתה נסיק לענין שהתחלנו בו. \u0003ומה זיתים וענבים\u0004 ש\u0003בני סחיטה נינהו\u0004 \u0005[הם],\u0006 כלומר, שהם מיועדים בעיקרם לסחיטה ולעשות משקים מהם, אם יצא מהם \u0003משקה שלא לרצון,\u0004 שלא נתכוון במיוחד לכך — \u0003ולא כלום\u0004 הוא ואינו מטמא, \u0003תותים ורמונים, דלאו\u0004 \u0005[שלא]\u0006 \u0003בני סחיטה נינהו\u0004 \u0005[הם]\u0006 כרגיל, \u0003לא כל שכן\u0004 שאינו מכשיר לקבל טומאה?","ודוחים: \u0003לא, \"לרצון\"\u0004 משמעו — אפילו \u0003בסתמא\u0004 \u0005[בסתם],\u0006 \u0003\"שלא לרצון\"\u0004 — \u0003דגלי אדעתיה\u0004 \u0005[שגילה דעתו]\u0006 במפורש ו\u0003אמר \"לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי\u0004 במשקה היוצא\". \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003סלי זיתים וענבים, כיון\u0004 ש\u0003לאיבוד קיימי\u0004 \u0005[\u0006הם \u0005עומדים],\u0006 שהם נוטפים ויוצאים, והרי \u0003מעיקרא אפקורי מפקרי להו\u0004 \u0005[מתחילה מפקיר\u0006 הוא \u0005אותם],\u0006 ואין להוכיח מהם, וכרגיל משקים שאינם נועדים מתחילה לאיבוד נחשבים כמשקים אפילו בסתם.","\u0003אשכחן\u0004 \u0005[מצאנו]\u0006 בברייתא שהובאה מקודם \u0003ר' יהודה דמודי לרבנן\u0004 \u0005[שמודה ל\u0006שיטת \u0005חכמים]\u0006 \u0003בזיתים ובענבים,\u0004 שבין אם יצאו המשקים לרצון בין לא לרצון הריהם מכשירים לקבל טומאה, ואולם \u0003רבנן דמודו ליה\u0004 \u0005[חכמים שמודים לו]\u0006 \u0003לר' יהודה בשאר פירות\u0004 שיש \u0003הבדל בין אם הכניסן למשקים או לאוכלים מנלן\u0004 \u0005[מנין לנו]?\u0006 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003סוחטין\u0004"],["\u0003בפגעין\u0004 (שזיפים) \u0003ובפרישין\u0004 (חבושים) \u0003ובעוזרדין, אבל לא ברמונים,\u0004 כיון שהדרך לסחוט אותם, שכן \u0003של בית מנשיא בר מנחם היו סוחטין ברמונים\u0004 בימות החול. נמצא שבשאר פירות, שאינם רמונים ותותים, מודים חכמים לר' יהודה.","ומקשים: \u0003וממאי דרבנן\u0004 \u0005[וממה\u0006 מסיק אתה שברייתא זו לשיטת \u0005חכמים]\u0006 \u0003היא, דילמא\u0004 \u0005[שמא]\u0006 שיטת \u0003ר' יהודה היא?!\u0004 ומשיבים: \u0003ותהוי נמי\u0004 \u0005[ותהא\u0006 ברייתא זו \u0005גם כן]\u0006 כ\u0003ר' יהודה,\u0004 עדיין \u0003אימר דשמעת ליה\u0004 \u0005[אמור ששמעת אותו]\u0006 את \u0003ר' יהודה\u0004 שאמר כי במשקים ש\u0003יצאו מעצמן\u0004 מותר להשתמש, ואולם ש\u0003סוחטין לכתחילה מי שמעת ליה\u0004 \u0005[האם שמעת אותו]\u0006 שהתיר לעשות זאת?! \u0003אלא מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר]:\u0006 \u0003כיון דלאו\u0004 \u0005[שלא]\u0006 \u0003בני סחיטה נינהו\u0004 \u0005[הם],\u0006 שאינם ראויים לסחיטה, אם כן — \u0003אפילו לכתחילה,\u0004 ואם כן הוא שיש לומר טעם זה, \u0003אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שכשיטת \u0005חכמים]\u0006 היא, \u0003כיון דלאו\u0004 \u0005[שלא]\u0006 \u0003בני סחיטה נינהו\u0004 \u0005[הם] —\u0006 \u0003אפילו לכתחילה\u0004 מותר, וכיון שלא התיר ברמונים \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שברייתא זו כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","שנינו בברייתא שהובאה קודם כי \u0003של בית מנשיא בר מנחם היו סוחטין ברמונים\u0004 בימות החול, והרי שסוחטים כרגיל את הרימונים ולכן אסור לסוחטם בשבת. \u0003אמר רב נחמן: הלכה כשל בית מנשיא בר מנחם.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן:\u0004 וכי \u0003מנשיא בן מנחם תנא הוא\u0004 שאתה פוסק הלכה כמותו?! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי כוונת הדברים היא ש\u0003הלכה כי האי תנא דסבר לה\u0004 \u0005[כתנא זה הסבור]\u0006 \u0003כשל מנשיא בן מנחם,\u0004 עדיין יש להקשות: \u0003ו\u0004כי \u0003משום דסבר\u0004 \u0005[ש\u0006הוא \u0005סבור]\u0006 \u0003כמנשיא בן מנחם\u0004 הרי \u0003הלכה כמותו?\u0004 וכי \u0003מנשיא בן מנחם הוי רובא דעלמא\u0004 \u0005[הינו רוב\u0006 העולם\u0005]?\u0006 וכיון שאין רוב העולם נוהג כך תיבטל דעתו מפני דעת הרוב!","ענה לו רב נחמן: \u0003אין\u0004 \u0005[כן],\u0006 במקרים כאלה אנו סומכים על מנהג שאינו מנהג רוב העולם, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 שדנו בענין \u0003המקיים קוצים בכרם,\u0004 ונשאלה שאלה אם קוצים אלה דינם ככלאים בכרם. \u0003ר' אליעזר אומר: קדש,\u0004 שהקוצים הינם כלאיים והמקיימם אסר (\"קידש \") משום כלאים בכרם. \u0003וחכמים אומרים: אינו מקדש\u0004 (אוסר) בכרם \u0003אלא דבר שכמוהו מקיימין\u0004 ומגדלים אנשים בירק. \u0003ואמר ר' חנינא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר\u0004 — \u0003שכן בערביא מקיימין קוצי שדות\u0004 כדי לתת \u0003לגמליהם,\u0004 ונחשבים שם הקוצים כשאר מיני ירקות וזרעים. הרי שלשיטה זו כיון שבמקום אחד נוהגים לקיים את הקוצים נעשו חשובים בכל מקום ומקום, וכן הדבר גם לגבי סחיטת הרמונים.","ודוחים: \u0003מידי איריא\u0004 \u0005[האם שייך,\u0006 דומה הדבר\u0005]?\u0006 והלא \u0003ערביא\u0004 היא \u0003אתרא\u0004 \u0005[מקום],\u0006 ומקום מדינה שלימה שנוהגת כך חשובה היא, ואולם \u0003הכא\u0004 \u0005[כאן\u0006 בבית מנשיא\u0005]\u0006 שיחיד הוא — \u0003בטלה דעתו אצל כל אדם!\u0004","\u0003אלא\u0004 יש לומר ש\u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של דברי רב נחמן \u0003כ\u0004שיטת \u0003רב חסדא.\u0004 ש\u0003אמר רב חסדא : תרדין שסחטן ונתנן\u0004 את מי התרדים \u0003במקוה\u0004 — \u0003פוסלין את המקוה בשינוי מראה,\u0004 שכל מין נוזל שמכניסים במקוה שאין בו שיעורו השלם, אם הוא משנה את צבע המים הרי הוא פוסל את המקוה. \u0003והא לאו\u0004 \u0005[והרי לא]\u0006 \u0003בני סחיטה נינהו\u0004 \u0005[הם]\u0006 התרדים, ומשקים היוצאים מהם אין דינם להיחשב כלל כמשקים? \u0003אלא מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר]\u0006 — \u0003כיון דאחשבינהו, הוה להו\u0004 \u0005[שהחשיבם, הרי הם\u0006 נעשים\u0005]\u0006 \u0003משקה,\u0004 ואם כן \u0003הכא נמי\u0004 \u0005[כאן\u0006 ברימונים \u0005גם כן]\u0006 \u0003כיון דאחשבינהו, הוה להו\u0004 \u0005[שהחשיבם, הרי הם\u0006 נעשים\u0005]\u0006 \u0003משקה,\u0004 ולכן מיץ הרמונים אסור, כיון שסוחטים אותו ומחשיבים אותו.","\u0003רב פפא אמר:\u0004 טעמו של רב חסדא הפוסל מקוה במי תרדין \u0003משום דהוי\u0004 \u0005[שהם]\u0006 \u0003דבר שאין עושין ממנו מקוה לכתחילה, ו\u0004כלל בידינו ש\u0003כל דבר שאין עושין ממנו מקוה לכתחילה\u0004 (שאינו מים או שלג וקרח) הריהו \u0003פוסל את המקוה בשינוי מראה,\u0004 גם אם אינו משקה.","\u0003תנן התם\u0004 \u0005[שנויה\u0006 משנה \u0005שם]\u0006 במסכת מקואות: מקוה ש\u0003נפל לתוכו יין או חומץ\u0004 או \u0003מוחל\u0004 (המיץ היוצא מן הזיתים, שאינו שמן), \u0003ושנה מראיו\u0004 של המקוה — המקוה \u0003פסול.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור ש\u0003מוחל\u0004 כ\u0003משקה הוא\u0004 נחשב? \u0003אמר אביי:\u0004 כשיטת \u0003ר' יעקב היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יעקב אומר: מוחל הרי הוא כמשקה. ומה טעם אמרו\u0004 חכמים ש\u0003מוחל היוצא בתחלה,\u0004 כלומר, לפני שמתחילים לסחוט את השמן, הוא \u0003טהור\u0004 — לא משום שאינו משקה, אלא \u0003לפי שאינו רוצה בקיומו,\u0004 שנוח לו שלא יצא המוחל מן הזיתים אלא יתערב אחר כך בשמן,","\u0003ר' שמעון אומר: מוחל אינו\u0004 נחשב \u0003כמשקה. ומה טעם אמרו\u0004 חכמים ש\u0003מוחל היוצא מעיקול בית הבד\u0004 לאחר סחיטת השמן \u0003טמא\u0004 — \u0003לפי שאי אפשר לו בלא ציחצוחי שמן,\u0004 כלומר, בלא מעט שמן היוצא עמו מן הזיתים.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל המעשי \u0005ביניהם]?\u0006 שהרי לכאורה שניהם מסכימים שמוחל היוצא בתחילה טהור, והיוצא מעיקול בית הבד טמא. ומשיבים: \u0003איכא בינייהו דאתי בתר איצצתא\u0004 \u0005[יש ביניהם\u0006 הבדל ביחס למוחל \u0005היוצא לאחר סחיטה רבה],\u0006 שלדעת ר' יעקב טמא, ולדעת ר' שמעון טהור. \u0003רבא אמר:\u0004 הטעם שמוחל פוסל אינו משום שהוא משקה, אלא \u0003משום דהוי\u0004 \u0005[שהוא]\u0006 \u0003דבר שאין עושין הימנו\u0004 (ממנו) \u0003מקוה\u0004 לכתחילה, \u0003ופוסל את המקוה בשינוי מראה.\u0004","\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: סוחט אדם אשכול של ענבים\u0004 בשבת \u0003לתוך הקדרה\u0004 שיש בה מאכל ואין זה כסחיטה אלא כהכנסת מאכל במאכל, \u0003אבל לא לתוך הקערה\u0004 הריקה. \u0003אמר רב חסדא: מדברי רבינו\u0004 (שמואל) \u0003נלמד\u0004 ש\u0003חולב אדם עז\u0004 בשבת \u0003לתוך הקדרה,\u0004 שאינו כמוציא חלב בדרך סחיטה ודישה, \u0003אבל לא לתוך הקערה\u0004 הריקה. ומסיקים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 יוצא \u0005שסבור]\u0006 הוא ש\u0003משקה הבא לאוכל\u0004 אין דינו כמשקה, אלא \u0003אוכל הוא.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רמי בר חמא\u0004 ממה ששנינו: \u0003זב שחולב את העז\u0004 — \u0003החלב טמא\u0004 בכל מקרה ואפילו לא נגע בו. וטומאתו של החלב ממה שהזב העבירו ממקום למקום, שהזב מטמא במשא ובהיסט אף בלא מגע. \u0003ואי אמרת\u0004 \u0005[ואם אומר\u0006 \u0003אתה\u0004\u0005]\u0006 ש\u0003משקה הבא לאוכלין אוכל הוא\u0004 ואין דינו כמשקה, נמצא שחלב שנחלב ישר לתוך הקדירה דינו כאוכל, והלא אין אוכל מקבל טומאה אלא אם כן הוכשר לטומאה במשקים, ואם כן אוכל זה \u0003במאי איתכשר\u0004 \u0005[במה הוכשר]\u0006 לקבל טומאה?","ומשיבים: יש לומר \u0003כ\u0004מו ש\u0003אמר ר' יוחנן\u0004 בנושא אחר שמדובר \u0003בטיפה המלוכלכת על פי הדד,\u0004 בטיפת החלב הראשונה מרטיבים את פי הדד להקל את החליבה או היניקה, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003בטיפה המלוכלכת על פי הדד,\u0004 שאינה מיועדת לקדרה והיא המשקה המכשיר את שאר החלב.","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רבינא\u0004 ממה ששנינו במשנה אחרת: \u0003טמא מת שסחט זיתים וענבים,\u0004"],["\u0003כביצה מכוונת\u0004 — \u0003טהור,\u0004 שבכלל אין אוכל מטמא אלא ביותר מכביצה. \u0003הא\u0004 \u0005[הרי]\u0006 אם היה שם \u0003יותר מכביצה\u0004 — \u0003טמא, ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003\"משקה הבא לאוכל אוכל הוא\", במאי איתכשר\u0004 \u0005[במה הוכשר]\u0006 אוכל זה לקבלת טומאה? \u0003הוא מותיב לה\u0004 \u0005[הוא מקשה אותה,\u0006 קושיה זו\u0005],\u0006 \u0003והוא מפרק לה\u0004 \u0005[מתרץ אותה],\u0006 שמדובר כאן \u0003בסוחט לתוך הקערה,\u0004 וכבר אמרנו שהסוחט לקערה כסוחט למשקה.","\u0003אמר ר' ירמיה:\u0004 ענין משקה הבא לאוכל אם דינו כאוכל או כמשקה הריהו \u0003כתנאי\u0004 \u0005[כתנאים]\u0006 שנחלקו כבר בענין זה. ששנינו במשנה: \u0003המחליק\u0004 את הלחם לפני אפייתו \u0003בענבים\u0004 שהוא סוחט עליהם — \u0003לא הוכשר\u0004 הלחם לקבל טומאה. \u0003ר' יהודה אומר: הוכשר. מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בדבר זה נחלקו],\u0006 \u0003מר סבר\u0004 \u0005[חכם\u0006 זה, התנא הראשון \u0005סבור]\u0006 ש\u0003משקה הבא לאוכל\u0004 — \u0003אוכל הוא,\u0004 ולכן לדעתו לא הוכשר עדיין הלחם. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה \u0005סבור]\u0006 ש\u0003לאו\u0004 \u0005[לא]\u0006 \u0003אוכל הוא,\u0004 אלא משקה גמור, והוכשר הלחם במיץ הענבים.","\u0003אמר רב פפא:\u0004 אין זו הוכחה, ואפשר לפרש \u0003דכולי עלמא\u0004 \u0005[כל העולם,\u0006 לדעת הכל\u0005]\u0006 \u0003משקה הבא לאוכל לאו\u0004 \u0005[לא]\u0006 \u0003אוכל הוא, והכא\u0004 \u0005[וכאן]\u0006 \u0003במשקה הבא לאיבוד קמיפלגי\u0004 \u0005[נחלקו].\u0006 שהרי המשקה הנמשח על ככרות הלחם סופו שכלה באש התנור, ובכך נחלקו: ש\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יהודה \u0005סבור]\u0006 שבכל זאת \u0003משקה הוא,\u0004 ולכן לדעתו הוא מכשיר לקבלת טומאה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 התנא הראשון \u0005סבור]\u0006 ש\u0003לאו\u0004 \u0005[לא]\u0006 \u0003משקה הוא. ובפלוגתא דהני תנאי\u0004 \u0005[ו\u0006נחלקו \u0005במחלוקתם של תנאים אלה]\u0006 שכבר נחלקו בבעיה זו, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003המפצע\u0004 (חותך) \u0003בזיתים בידים מסואבות\u0004 \u0005[טמאות]\u0006 — \u0003הוכשר\u0004 על ידי המשקה הזב מן הזיתים ונטמאו. ואם היה עושה זאת כדי \u0003לסופתן\u0004 (לטבלם) \u0003במלח\u0004 — \u0003לא הוכשר,\u0004 שהיוצא מן הזיתים שלא לרצונו אינו מכשיר.","ואם היה מפצע כדי \u0003לידע אם הגיעו זיתיו\u0004 לדרגת בשילות שיהיו ראויים \u0003למסוק אם\u0004 עדיין \u0003לאו\u0004 \u0005[לא]\u0006 — \u0003לא הוכשר. ר' יהודה אומר: הוכשר. מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה נחלקו]\u0006 \u0003דמר סבר\u0004 \u0005[שחכם\u0006 זה, ר' יהודה, \u0005סבור]\u0006 \u0003משקה העומד לאיבוד,\u0004 שיוצא אגב הבדיקה של הזיתים ואינו מעוניין בשמירתו — \u0003משקה הוא,\u0004 ומכשיר. \u0003ומר סבר\u0004 \u0005[וחכם\u0006 זה, סתם ברייתא, \u0005סבור]\u0006 ש\u0003לאו\u0004 \u0005[לא]\u0006 \u0003משקה הוא\u0004 ואינו מכשיר.","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' יהושע:\u0004 אין הכרח להשוות את שתי המחלוקות האחרונות, אלא \u0003הני תנאי\u0004 \u0005[תנאים אלה]\u0006 שנחלקו במפצע זיתים \u0003במשקה העומד לאיבוד פליגי\u0004 \u0005[חולקים],\u0006 \u0003והנך תנאי\u0004 \u0005[ותנאים אלה]\u0006 שנחלקו במשקה שעל הלחם \u0003ב\u0004ענין \u0003משקה העומד לצחצחו\u0004 (לתקנו ולייפותו) \u0003קמיפלגי\u0004 \u0005[נחלקו],\u0006 אם משקה שנועד רק לצחצחו ולתיקונו של מאכל דינו כמשקה אם לא.","\u0003אמר ר' זירא\u0004 שכך \u0003אמר רב חייא בר אשי\u0004 שכך \u0003אמר רב: סוחט אדם\u0004 בשבת \u0003אשכול של ענבים לתוך הקדרה\u0004 שיש בה דברי מאכל, שכל הנכנס לאוכל דינו כמין מאכל ולא כמשקה, \u0003אבל לא לתוך הקערה\u0004 שהיא ריקה או שיש בה משקה. \u0003ודג\u0004 שצריך את \u0003צירו\u0004 מותר לסוחטו \u0003אפילו לתוך הקערה.\u0004","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב דימי וקאמר לה להא שמעתא\u0004 \u0005[ואמר אותה, את ההלכה הזו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב דימי: אתון משמיה\u0004 \u0005[אתם משמו]\u0006 של \u0003רב מתניתון ולא קשיא לכו\u0004 \u0005[שונים אתם\u0006 את ההלכה הזו \u0005ואינה קשה לכם],\u0006 \u0003אנן משמיה\u0004 \u0005[אנחנו משמו]\u0006 של \u0003שמואל מתנינן לה\u0004 \u0005[שונים אנו אותה\u0006 הלכה\u0005],\u0006 \u0003וקשיא לן\u0004 \u0005[וקשה לנו]:\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר שמואל\u0004 ש\u0003דג\u0004 שצריך \u0003לצירו\u0004 מותר לו לסוחטו \u0003אפילו לתוך הקערה\u0004 הריקה? \u0003והאיתמר\u0004 \u0005[והרי נאמר]\u0006 שנחלקו בענין \u0003כבשים\u0004 (ירקות כבושים) \u0003שסחטן, אמר רב:\u0004 אם סחטן משום שצריך \u0003לגופן\u0004 שרוצה בכבשים בלא מימיהן — \u0003מותר\u0004 לכתחילה לעשות כן בשבת, ואם סחטן משום שצריך \u0003למימיהן\u0004 — \u0003פטור\u0004 מחטאת, \u0003אבל אסור\u0004 לעשות כן מלכתחילה.","\u0003ו\u0004אילו \u0003שלקות\u0004 (דברים מבושלים) \u0003בין\u0004 אם צריך \u0003לגופן בין למימיהן\u0004 — \u0003מותר\u0004 לסחוט. \u0003ושמואל אמר: אחד כבשים ואחד שלקות,\u0004 אם צריך \u0003לגופן\u0004 — \u0003מותר, למימיהן\u0004 — \u0003פטור, אבל אסור.\u0004 וסחיטת דג לכאורה כסחיטת שלקות היא כשצריך לצירו (\"למימיהם\") אסור, וסותרים אם כן דברי שמואל אלו את אלו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 יכול אתה בהחלט לסמוך על גרסתי, וחיזק דבריו בביטוי של שבועה: \u0003האלהים!\u0004 וכלשון הכתוב יכול הוא לומר \u0003\"\u0004אשר אני אחזה לי ו\u0003עיני ראו ולא זר\"\u0004 (איוב יט, כז), \u0003מפומיה\u0004 \u0005[מפיו]\u0006 של \u0003ר' ירמיה שמיע לי\u0004 \u0005[שמעתי]\u0006 מסורת זו, \u0003ור' ירמיה\u0004 שמע בעצמו \u0003מר' זירא, ור' זירא מרב חייא בר אשי, ורב חייא בר אשי מרב,\u0004 ולא היה בין מוסרי הדברים אף אחד שאינו בדוק ושאין לסמוך עליו.","כיון שהוזכרה ההלכה בענין סחיטת כבשים דנים בה \u0003גופא\u0004 \u0005[לגופא].\u0006 שנינו \u0003כבשים שסחטן\u0004 בשבת, \u0003אמר רב:\u0004 אם סחטם משום שצריך \u0003לגופן\u0004 בלא הנוזלים שבהם — \u0003מותר,\u0004 ואם משום שצריך \u0003למימיהן\u0004 — \u0003פטור, אבל אסור. ושלקות, בין לגופן בין למימיהן\u0004 — \u0003מותר. ושמואל אמר: אחד זה ואחד זה,\u0004 בין כבשים בין שלקות אם סחטם משום שצריך \u0003לגופן\u0004 — \u0003מותר, למימיהן\u0004 — \u0003פטור, אבל אסור. ר' יוחנן אמר: אחד כבשים ואחד שלקות,\u0004 אם סחטם משום שצריך \u0003לגופן\u0004 — \u0003מותר, למימיהן\u0004 — \u0003חייב חטאת\u0004 שעשה מלאכה האסורה מן התורה.","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא: \u0003סוחטין כבשים בשבת לצורך השבת, אבל לא ל\u0004צורך \u0003מוצאי שבת. וזיתים וענבים לא יסחוט\u0004 כלל בשבת, \u0003ואם סחט\u0004 בשוגג — \u0003חייב חטאת.\u0004 נמצא שמותר לסחוט כבשים בשבת לכל צורך, אפילו למימיהם, ולכתחילה ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003לרב, קשיא\u0004 \u0005[קשה]\u0006 \u0003לשמואל, קשיא\u0004 \u0005[קשה]\u0006 \u0003לר' יוחנן,\u0004 שלדעת כולם יש איסור מסויים בסחיטת כבשים למימיהן! ואומרים: כל אחד מהם \u0003מתרץ לטעמיה\u0004 \u0005[מיישב\u0006 את הברייתא \u0005לטעמו,\u0006 לפי שיטתו\u0005].\u0006","\u0003רב מתרץ לטעמיה\u0004 \u0005[מיישב לטעמו,\u0006 לשיטתו \u0005],\u0006 וכך הוא מבין את הברייתא, ומוסיף בה דברים: \u0003סוחטין כבשים בשבת לצורך\u0004 השבת, אבל לא לצורך \u0003מוצאי שבת. במה דברים אמורים\u0004 — כשסוחטם \u0003ל\u0004צורך \u0003גופן, אבל\u0004 אם סוחטם \u0003משום שצריך למימיהן\u0004 — \u0003פטור, אבל אסור. ושלקות בין לגופן בין למימיהן\u0004 — \u0003מותר. וזיתים וענבים\u0004 — \u0003לא יסחוט\u0004 כלל, \u0003ואם סחטן\u0004 בשוגג — \u0003חייב חטאת.\u0004","ו\u0003שמואל מתרץ לטעמיה\u0004 \u0005[מיישב לטעמו,\u0006 לשיטתו \u0005],\u0006 וכך הוא מבין את הברייתא, ואף מוסיף בה דברים: \u0003סוחטין כבשים בשבת לצורך השבת\u0004 ו\u0003הוא הדין לשלקות. במה דברים אמורים\u0004 — כשסוחטם משום שצריך \u0003לגופן אבל\u0004 אם סוחטם \u0003למימיהן\u0004 — \u0003פטור, אבל אסור. וזיתים וענבים לא יסחוט\u0004 כלל, \u0003ואם סחט\u0004 בשוגג — \u0003חייב חטאת.\u0004","ו\u0003ר' יוחנן\u0004 אף הוא \u0003מתרץ לטעמיה\u0004 \u0005[מיישב לטעמו,\u0006 לשיטתו \u0005],\u0006 וכך הוא מבין את הברייתא, ואף הוא כאחרים מוסיף בה דברים: \u0003סוחטין כבשים לצורך השבת אבל לא ל\u0004צורך \u0003מוצאי שבת, אחד כבשים ואחד שלקות. במה דברים אמורים\u0004 — כשסוחטם \u0003משום שצריך לגופן, אבל\u0004 אם סוחטם משום שצריך \u0003למימיהן\u0004 — \u0003לא יסחוט, ואם סחט\u0004 בשוגג — \u0003נעשה כמי שסחט זיתים וענבים, וחייב חטאת.\u0004","\u0003אמר רב חייא בר אשי\u0004 שכך \u0003אמר רב: דבר תורה\u0004 — \u0003אינו חייב אלא על דריסת\u0004 (סחיטת) \u0003זיתים וענבים בלבד,\u0004 וכל שאר איסורי סחיטה שבהלכה גזירות וסייגי חכמים הם. \u0003וכן תני דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003מנשה: דבר תורה\u0004 הסוחט בשבת \u0003אינו חייב אלא על דריסת זיתים וענבים בלבד.\u0004 ועוד שנו בבית מדרש זה: \u0003ואין עד מפי עד\u0004 המעיד רק מתוך מה ששמע מפי עד אחר \u0003כשר\u0004"],["\u0003אלא לעדות אשה בלבד,\u0004 כלומר, להעיד לאשה שמת בעלה, שרק לענין זה התירו לסמוך על עדות שאינה שלמה, כדי להתיר את העגונה.","אגב כך \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 \u0003עד מפי עד לעדות בכור מהו\u0004 הדין? שאם היה בכור בהמה טהורה בידי כהן לאחר חורבן בית המקדש ונפל מום בבכור, תקנו חכמים שיביא הכהן עד להעיד שמום זה נפל מעצמו, ולא עשהו הכהן, שנחשדו הכהנים שהם מטילים מומים בבכורות כדי שיוכלו לאוכלם. והשאלה היתה אם לא היה כאן עד שראה בעצמו את התהוות המום אלא אדם אחר ששמע ממנו. \u0003רב אמי אסיר\u0004 \u0005[אסר]\u0006 לקבל לענין זה עד מפי עד, \u0003ורב אסי שרי\u0004 \u0005[התיר].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אמי לרב אסי: והא תנא דבי\u0004 \u0005[והרי שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003מנשיא: אין עד מפי עד כשר אלא לעדות אשה בלבד!\u0004 ומכאן שלעדות בכור אינו כשר. ענה לו רב אסי: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן שעד מפי עד כשר רק \u0003לעדות שהאשה כשרה לה בלבד.\u0004 והאשה כשרה להעיד שמת אדם וכן כשרה להעיד על בכור, ובעדויות כאלה מקבלים גם עד מפי עד. \u0003רב יימר אכשר\u0004 \u0005[הכשיר]\u0006 עדות \u0003עד מפי עד ל\u0004התיר את ה\u0003בכור\u0004 בשחיטה אחר שנעשה בו מום. \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 החכם \u0003מרימר: יימר שרי בוכרא\u0004 \u0005[מתיר הבכור].\u0006 שמרימר סבר שעדות כזו אין בכוחה להכשיר. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא ש\u0003עד מפי עד כשר לבכור.\u0004","במשנה שנינו שאמר ר' אליעזר שדבש הזב מעצמו מן החלות מותר בשבת. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב הושעיא מנהרדעא אתא ואייתי מתניתא בידיה\u0004 \u0005[בא והביא ברייתא בידו],\u0006 וכך נאמר בה: \u0003זיתים וענבים שריסקן מערב שבת, ויצאו\u0004 המשקים \u0003מעצמן\u0004 — \u0003אסורין\u0004 בשבת. \u0003ור' אלעזר ור' שמעון מתירין.\u0004","\u0003אמר רב יוסף\u0004 בתמיהה: וכי \u0003גברא יתירא אתא לאשמעינן\u0004 \u0005[אדם נוסף בא להשמיענו],\u0006 שהרי כבר ידענו מן המשנה על דעה זו, אלא נאמרה בשמו של ר' אלעזר בלבד והוסיף רב הושעיא גם את ר' שמעון ואין בכך לכאורה כל חשיבות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: טובא קא משמע לן\u0004 \u0005[הרבה השמיע לנו],\u0006 וחידוש הדברים הוא מהותי, \u0003דאי ממתניתין הוה אמינא\u0004 \u0005[שאם מהמשנה\u0006 בלבד \u0005הייתי אומר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 מותר — כיון \u0003דמעיקרא אוכלא\u0004 \u0005[שמתחילה\u0006 היה \u0005אוכל]\u0006 \u0003ולבסוף אוכלא\u0004 \u0005[אוכל],\u0006 שאפשר לומר שאף הדבש הזב דינו כמאכל ולא כמשקה, \u0003אבל הכא דמעיקרא אוכלא\u0004 \u0005[כאן\u0006 בענבים \u0005שמתחילה אוכל]\u0006 \u0003ולבסוף משקה\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יתיר אפילו ר' אלעזר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהוא מתיר אפילו בזיתים וענבים.","\u0003כל שבא בחמין\u0004 שהתבשל כבר \u0003מערב שבת\u0004 — \u0003שורין אותו בחמין בשבת,\u0004 שאין איסור בישול בדבר המבושל כבר כראוי. \u0003וכל שלא בא בחמין מערב שבת\u0004 — \u0003מדיחין אותו בחמין בשבת, חוץ מן המליח הישן ודגים מלוחין קטנים ו\u0004הדג הקרוי \u0003קולייס האיספנין,\u0004 שאסורים אף בהדחה, כיון \u0003שהדחתן זו היא גמר מלאכתן\u0004 ואינם צריכים לבישול נוסף, ונמצא שמבשלם בשבת.","שנינו במשנה שדבר שבושל בחמין מערב שבת — שורין אותו בחמין בשבת. ושואלים: דבר שכבר בושל בערב שבת וצריך להשרותו שוב בחמין בשבת \u0003כגון מאי\u0004 \u0005[מה]?\u0006 ולשם מה צריך בישול נוסף זה? \u0003אמר רב ספרא: כגון תרנגולתא\u0004 \u0005[התרנגולת]\u0006 של \u0003ר' אבא.\u0004 שלצורך רפואה היו מבשלים תרנגולת פעמים רבות כל כך עד שנימוחה ונמסה לגמרי \u0003ואמר רב ספרא: זימנא חדא איקלעית להתם, ואוכלן מיניה\u0004 \u0005[פעם אחת הזדמנתי לשם והאכיל אותי ממנה,\u0006 מתרנגולת כזו\u0005],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא ר' אבא דאשקיין חמרא בר תלתא טרפי\u0004 \u0005[שהשקני יין בן שלשה עלים,\u0006 שלוש שנים\u0005]\u0006 — \u0003איתנסי\u0004 \u0005[הייתי אנוס\u0006 להקיא\u0005].\u0006","מסופר כי \u0003ר' יוחנן רייק\u0004 \u0005[היה יורק]\u0006 \u0003מכותח דבבלאי\u0004 \u0005[הבבלי],\u0006 כשהיה נזכר בו, מחמת גועל. \u0003אמר רב יוסף: ולירוק אנן מתרנגולתא\u0004 \u0005[ושנירק אנחנו מן התרנגולת]\u0006 של \u0003ר' אבא,\u0004 שהיא מאוסה יותר, בעיני יושבי בבל. \u0003ועוד,\u0004 הרי \u0003אמר רב גזא: זימנא חדא איקלעית להתם, ועבדית\u0004 \u0005[פעם אחת הזדמנתי לשם,\u0006 לארץ ישראל, \u0005ועשיתי]\u0006 \u0003כותח דבבלאי\u0004 \u0005[הבבלי],\u0006 \u0003שאילו מיניה כל בריחי מערבא\u0004 \u0005[\u0006ו\u0005ביקשו ממני כל חולי ארץ ישראל]\u0006 נמצא שאינו מאוס בעיני כל בני הארץ.","שנינו במשנה ש\u0003כל שלא בא בחמין\u0004 מערב שבת מדיחים אותו בחמין בשבת חוץ מדג מליח וקולייס האיספנין. ושואליםן: ואם \u0003הדיח\u0004 בשוגג \u0003מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 \u0003אמר רב יוסף:\u0004 אם \u0003הדיח\u0004 — \u0003חייב חטאת\u0004 כמבשל. \u0003אמר מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא : אף אנן נמי תנינא\u0004 \u0005[אנחנו גם כן שנינו]\u0006 במקום אחר: \u0003חוץ ממליח ישן וקולייס האיספנין שהדחתן זו היא גמר מלאכתן.\u0004 והרי שהוא חייב על מלאכה זו. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","אגב הדברים שהוזכרו בענין יחסי בני ארץ ישראל ובבל מספרים: \u0003יתיב\u0004 \u0005[ישבו]\u0006 \u0003ר' חייא בר אבא ור' אסי קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן ויתיב\u0004 \u0005[וישב]\u0006 \u0003ר' יוחנן וקא\u0004 \u0005[והיה]\u0006 \u0003מנמנם,\u0004 והם בינתיים שוחחו ביניהם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא בר אבא לר' אסי: מפני מה עופות שבבבל שמנים\u0004 יותר מאלה שבארץ ישראל? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אין זה נכון כלל, \u0003כלך\u0004 \u0005[לך]\u0006 \u0003למדבר עזה\u0004 שבארץ ישראל \u0003ואראך שמנים מהן.\u0004 ועוד שאלו \u0003ר' חייא בר אבא: מפני מה\u0004 ב\u0003מועדים\u0004 האנשים \u0003שבבבל שמחים\u0004 יותר מאלו שבארץ ישראל? ענה לו ר' אסי: \u0003מפני שהן עניים\u0004 ורק בחג מרבים הם באכילה ושמחים הם בכך. ועוד שאל ר' חייא: \u0003מפני מה תלמידי חכמים שבבבל מצוינין\u0004 בלבוש מיוחד של תלמידי חכמים? אמר לו ר' אסי: \u0003לפי שאינן בני תורה,\u0004 ואם לא יהיו ניכרים בלבושם לא יכבדום מפני תורתם. ועוד שאלו: \u0003מפני מה\u0004 ה\u0003גוים מזוהמים\u0004 מבחינה מוסרית? אמר לו: \u0003מפני שאוכלין שקצים ורמשים\u0004 והדבר גורם להם למדות רעות.","\u0003איתער בהו\u0004 \u0005התעורר בהם,\u0006 מדבריהם\u0005]\u0006 \u0003ר' יוחנן\u0004 ו\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דרדקי\u0004 \u0005[תינוקות]!\u0006 וכי \u0003לא כך אמרתי לכם\u0004 שכוונת הפסוק \u0003\"אמור לחכמה אחתי את\u0004 ומודע לבינה תקרא\u0003\"\u0004 (משלי ז, ד) לומר: \u0003אם ברור לך הדבר כאחותך שהיא אסורה לך\u0004 — \u0003אומרהו, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003לא תאמרהו,\u0004 וסברות אלה שאמרתם אינן מבוססות. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ולימא לן מר\u0004 \u0005[ושיאמר לנו אדוני]\u0006 \u0003איזה מהן?\u0004 אמר להם: \u0003מפני מה עופות שבבבל שמנים\u0004 יותר מאלה של ארץ ישראל — \u0003מפני שלא גלו,\u0004 וכפי \u0003שנאמר: \"שאנן מואב מנעוריו ושקט הוא אל שמריו\u0004 ולא הורק מכלי אל כלי \u0003ובגולה לא הלך\u0004 על כן עמד טעמו בו וריחו לא נמר\u0003\"\u0004 (ירמיהו מח, יא), ומכאן אנו למדים שמי שלא גלה נשמרים כוחותיו הראשונים.","\u0003והכא מנלן\u0004 \u0005[וכאן,\u0006 בארץ ישראל \u0005מנין לנו]\u0006 ש\u0003גלו\u0004 בעלי החיים? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יהודה אומר חמשים ושתים שנה לא עבר איש ביהודה,\u0004 וכפי \u0003שנאמר: \"על ההרים אשא בכי ונהי\u0004 ועל נאות מדבר קינה כי ניצתו מבלי איש עובר ולא שמעו קול מקנה \u0003מעוף השמים ועד בהמה נדדו הלכו\"\u0004 (ירמיה ט, ט), \u0003\"בהמ\"ה\" בגימטריא חמשין ותרתין הוו\u0004 \u0005[חמישים ושתים הן],\u0006 מכל מקום נאמר בכתוב שאף בעלי החיים גלו מן הארץ (\"נדדו הלכו\").","\u0003אמר ר' יעקב\u0004 שכך \u0003אמר ר' יוחנן: כולן חזרו, חוץ מקולייס האיספנין\u0004 וכפי ש\u0003אמר רב: הני מדרי\u0004 \u0005[אותם מדרונות]\u0006 של \u0003בבל מהדרי מיא\u0004 \u0005[מחזירים את מימיהן]\u0006 דרך מחילות תת־קרקעיות \u0003לעין עיטם\u0004 שבירושלים, ודרך אותן מחילות חזרו אף הדגים. \u0003והאי\u0004 \u0005[וזה,\u0006 הקולייס\u0005]\u0006 \u0003כיון דלא שריר שדריה\u0004 \u0005[שאין שדרתו חזקה]\u0006 \u0003לא מצי סליק\u0004 \u0005[אינו יכול לעלות]\u0006 באותן מחילות, ולא חזר לארץ.","והמשיך ר' יוחנן להסביר להם את תמיהות ר' חייא בר אבא: \u0003מפני מה\u0004 ב\u0003מועדים\u0004 האנשים \u0003שבבבל שמחים\u0004 יותר מאלו שבארץ ישראל? — \u0003מפני שלא היו באותה קללה\u0004 שנתקללה ארץ ישראל, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והשבתי כל משושה חגה חדשה ושבתה וכל מועדה\"\u0004 (הושע ב, יג). \u0003וכתיב\u0004 \u0005[ו\u0006כן \u0005נאמר]:\u0006 \u0003\"חדשיכם ומועדיכם שנאה נפשי היו עלי לטרח\u0004 נלאיתי נשוא\u0003\"\u0004 (ישעיה א, יד) \u0003מאי\u0004 \u0005[מה\u0006 פירוש] \u0003\"היו עלי לטרח\"? אמר ר' אלעזר, אמר הקדוש ברוך הוא:\u0004 וכי \u0003לא דיין לישראל שחוטאין לפני, אלא ש\u0004עוד \u0003מטריחין אותי לידע איזו גזירה קשה אביא עליהן!\u0004 ו\u0003אמר ר' יצחק:\u0004 מכוח קללה זו \u0003אין לך כל רגל ורגל שלא באתה בולשת לציפורי\u0004 לחיפושים או לגבות קנסות. \u0003ואמר ר' חנינא: אין לך כל רגל ורגל שלא בא לטבריה אגמון וקמטון ובעל זמורה\u0004 (פקידים רומאיים) שבאו לגביית המיסים ומשביתים את שמחת הרגל.","\u0003מפני מה תלמידי חכמים שבבבל מצוינין\u0004 (מסומנים בסימן מיוחד) \u0003— לפי שאינן בני מקומן\u0004 ולכן צריכים הם לסימן. \u0003דאמרי אינשי\u0004 \u0005[שאומרים אנשים]\u0006 כפתגם עממי: \u0003במתא\u0004 \u0005[בעירי,\u0006 במקומי\u0005]\u0006 מכובד אני בשל \u0003שמאי\u0004 \u0005[שמי],\u0006 \u0003בלא מתא\u0004 \u0005[שלא בעירי]\u0006 — בשל \u0003תותבאי\u0004 \u0005[בגדי].\u0006 ועוד הוסיפו בשבחם של חכמי בבל במדרש הפסוק \u0003\"הבאים ישרש יעקב יציץ ופרח ישראל\"\u0004 (ישעיה כז, ו). \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף: אלו תלמידי חכמים שבבבל, שעושין ציצין ופרחים לתורה.\u0004","ועוד הסביר להם ר' יוחנן: \u0003מפני מה גוים מזוהמין\u0004 מבחינה מוסרית — מפני \u0003שלא עמדו על הר סיני. שבשעה\u0004"]]};
